// ── DB circuit breaker (incident 2026-06-02) ──
// Sheds background + heavy-read load when Supabase is unreachable / restarting, so an
// ~8-min platform restart stays an ~8-min blip instead of a cascading outage. Fed by
// the DB-health probe, the background sync loops, and the heaviest read endpoints
// (via dbLoadShedGuard); read by those same loops, the custom-domain cron, and the
// guard. Pure decision logic + tests in lib/db-circuit.js. Tunables via env.
let dbCircuitState = freshCircuitState();
const DB_CIRCUIT_CONFIG = {
  failureThreshold: Number(process.env.DB_CIRCUIT_FAILS) || DEFAULT_CIRCUIT_CONFIG.failureThreshold,
  openCooldownMs: Number(process.env.DB_CIRCUIT_COOLDOWN_MS) || DEFAULT_CIRCUIT_CONFIG.openCooldownMs,
};
const DB_DEGRADED_RECHECK_MS = Number(process.env.DB_DEGRADED_RECHECK_MS) || 30 * 1000;
let dbCircuitOpenLogged = false;

function recordDbResult(ok) {
  const wasOpen = isCircuitOpen(dbCircuitState, Date.now(), DB_CIRCUIT_CONFIG);
  dbCircuitState = recordDbOutcome(dbCircuitState, { ok: ok === true, nowMs: Date.now() }, DB_CIRCUIT_CONFIG);
  const nowOpen = isCircuitOpen(dbCircuitState, Date.now(), DB_CIRCUIT_CONFIG);
  if (nowOpen && !dbCircuitOpenLogged) {
    console.warn('[DB-Circuit] 🔴 OPEN — DB unreachable; shedding background + heavy-read load');
    dbCircuitOpenLogged = true;
  } else if (wasOpen && !nowOpen) {
    console.log('[DB-Circuit] 🟢 CLOSED — DB reachable again; resuming normal load');
    dbCircuitOpenLogged = false;
  }
}

function isDbDegraded() {
  return isCircuitOpen(dbCircuitState, Date.now(), DB_CIRCUIT_CONFIG);
}

// Route guard for the heaviest read endpoints: fast-fail with 503 while the breaker
// is OPEN (so dashboard polls stop hanging-to-timeout and piling queries onto a
// recovering DB), and feed each let-through request's outcome back into the breaker
// — a 5xx on these DB-heavy routes trips it within failureThreshold polls (seconds),
// a 2xx closes it immediately. Runs before authMiddleware: shedding needs no auth.
function dbLoadShedGuard(req, res, next) {
  if (isDbDegraded()) {
    res.set('Retry-After', '15');
    return res.status(503).json({
      error: 'db_degraded',
      message: 'Database sedang pulih sebentar (maintenance singkat). Coba lagi beberapa saat.',
    });
  }
  let recorded = false;
  res.on('finish', () => {
    if (recorded) return;
    recorded = true;
    if (res.statusCode >= 500) recordDbResult(false);
    else if (res.statusCode < 400) recordDbResult(true);
  });
  next();
}

function withTimeout(promise, ms, message) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => {
      const err = new Error(message);
      err.code = 'APP_TIMEOUT';
      reject(err);
    }, ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

function sanitizeTourLeaderPrepRoomNumber(value) {
  if (typeof value !== 'string') return null;
  const digits = value.replace(/\D/g, '').slice(0, 4);
  return /^\d{1,4}$/.test(digits) ? digits : null;
}

function sanitizeTourLeaderPrepText(value, maxLength) {
  if (typeof value !== 'string') return null;
  const text = value.trim().slice(0, maxLength);
  return text || null;
}

function tourLeaderPrepEntryFromPayload(payload = {}) {
  const zamzamMethod = payload.zamzam_method === 'pickup' || payload.zamzam_method === 'delivery'
    ? payload.zamzam_method
    : null;
  const isDelivery = zamzamMethod === 'delivery';

  return {
    phone: typeof payload.phone === 'string' ? payload.phone.trim().slice(0, 32) : null,
    wa_confirmed: payload.wa_confirmed === true,
    nusuk_installed: payload.nusuk_installed === true,
    raudhah_reserved: payload.raudhah_reserved === true,
    room_mekkah: sanitizeTourLeaderPrepRoomNumber(payload.room_mekkah),
    room_madinah: sanitizeTourLeaderPrepRoomNumber(payload.room_madinah),
    zamzam_method: zamzamMethod,
    zamzam_recipient_name: isDelivery ? sanitizeTourLeaderPrepText(payload.zamzam_recipient_name, 120) : null,
    zamzam_recipient_phone: isDelivery ? sanitizeTourLeaderPrepText(payload.zamzam_recipient_phone, 32) : null,
    zamzam_address: isDelivery ? sanitizeTourLeaderPrepText(payload.zamzam_address, 500) : null,
    updated_at: new Date().toISOString(),
  };
}

function tourLeaderPrepRowToItems(row) {
  const tahapan = plainObjectOrEmpty(row?.tahapan);
  const tripPrep = plainObjectOrEmpty(tahapan[RAHMAH_JULI_PUBLIC_SLUG]);
  const jamaahPrep = plainObjectOrEmpty(tripPrep.jamaah);

  return Object.entries(jamaahPrep)
    .map(([jamaahNo, entry]) => {
      const member = RAHMAH_JULI_MEMBER_BY_NO.get(Number(jamaahNo));
      const saved = plainObjectOrEmpty(entry);
      if (!member || member.idUmrah !== row.id_umroh) return null;
      return {
        jamaah_no: member.no,
        phone: typeof saved.phone === 'string' ? saved.phone : null,
        wa_confirmed: saved.wa_confirmed === true,
        nusuk_installed: saved.nusuk_installed === true,
        raudhah_reserved: saved.raudhah_reserved === true,
        room_mekkah: typeof saved.room_mekkah === 'string' ? saved.room_mekkah : null,
        room_madinah: typeof saved.room_madinah === 'string' ? saved.room_madinah : null,
        zamzam_method: saved.zamzam_method === 'pickup' || saved.zamzam_method === 'delivery'
          ? saved.zamzam_method
          : null,
        zamzam_recipient_name: typeof saved.zamzam_recipient_name === 'string' ? saved.zamzam_recipient_name : null,
        zamzam_recipient_phone: typeof saved.zamzam_recipient_phone === 'string' ? saved.zamzam_recipient_phone : null,
        zamzam_address: typeof saved.zamzam_address === 'string' ? saved.zamzam_address : null,
      };
    })
    .filter(Boolean);
}

function validateTourLeaderPrepPayload(tripSlug, jamaahNo, payload = {}) {
  if (tripSlug !== RAHMAH_JULI_PUBLIC_SLUG) {
    return { error: 'Paket tidak ditemukan' };
  }
  const member = RAHMAH_JULI_MEMBER_BY_NO.get(jamaahNo);
  if (!Number.isInteger(jamaahNo) || !member) {
    return { error: 'Nomor jamaah tidak valid' };
  }

  const entry = tourLeaderPrepEntryFromPayload(payload);
  if (payload.zamzam_method != null && !entry.zamzam_method) {
    return { error: 'Pilihan pengambilan Air Zam-zam tidak valid' };
  }
  if (entry.zamzam_method === 'delivery'
    && (!entry.zamzam_recipient_name || !entry.zamzam_recipient_phone || !entry.zamzam_address)) {
    return { error: 'Data penerima dan alamat pengantaran wajib dilengkapi' };
  }

  return { member, entry };
}

// ── Helper: fetch all rows from a Supabase query (bypasses 1000-row PostgREST limit) ──
async function fetchAllRows(queryBuilder) {
  const PAGE_SIZE = 1000;
  let allRows = [];
  let from = 0;
  while (true) {
    const { data, error } = await queryBuilder.range(from, from + PAGE_SIZE - 1);
    if (error) throw error;
    if (!data || data.length === 0) break;
    allRows = allRows.concat(data);
    if (data.length < PAGE_SIZE) break; // last page
    from += PAGE_SIZE;
  }
  return allRows;
}

function umrohPhase1EnrichmentKey(row) {
  return `${row?.id_umroh || ''}_${row?.jm_id || ''}`.toLowerCase();
}

async function mergeExistingUmrohPhase1Enrichment(agentId, rows) {
  const safeRows = Array.isArray(rows) ? rows : [];
  if (safeRows.length === 0) return [];

  const existingIduIds = [...new Set(safeRows.map(r => r.id_umroh).filter(Boolean))];
  const existingJmIds = [...new Set(safeRows.map(r => r.jm_id).filter(Boolean))];
  if (existingIduIds.length === 0 || existingJmIds.length === 0) {
    return safeRows.map(row => preserveUmrohPhase1Enrichment(row, null));
  }

  const { data: existingRows, error } = await supabase
    .from('jamaah')
    .select('id_umroh, jm_id, wa, tgl_lahir, perlengkapan, dokumen, no_paspor, paspor_expired, hijriah_year, tgl_berangkat')
    .eq('agent_id', agentId)
    .in('id_umroh', existingIduIds)
    .in('jm_id', existingJmIds);

  if (error) {
    console.warn('[Sync/P1] existing enrichment lookup failed:', error.message);
    return safeRows.map(row => preserveUmrohPhase1Enrichment(row, null));
  }

  const existingLookup = new Map();
  (existingRows || []).forEach(row => {
    existingLookup.set(umrohPhase1EnrichmentKey(row), row);
  });

  return safeRows.map(row => preserveUmrohPhase1Enrichment(row, existingLookup.get(umrohPhase1EnrichmentKey(row))));
}

// Kompresi origin (gzip/br via negotiation) — penting untuk agent ber-custom-domain
// yang TIDAK lewat proxy Cloudflare: tanpa ini HTML landing ~370KB terkirim mentah.
app.use(compression({
  filter: (req, res) => {
    const ct = String(res.getHeader('Content-Type') || '');
    if (ct.includes('text/event-stream')) return false; // jangan buffer SSE
    return compression.filter(req, res);
  },
}));

// MCP JSON-RPC requests are tiny — cap /mcp tight so the global 10mb parser
// can't be used to push oversized bodies at the public MCP endpoint.
app.use('/mcp', express.json({ limit: '128kb' }));
// Dev-MCP (developer tool, /dev-mcp) — body juga kecil; cap ketat sebelum global.
app.use('/dev-mcp', express.json({ limit: '256kb' }));
// A 10 MiB KTP becomes ~13.4 MiB after base64 encoding. Parse these upload
// routes before the tighter global parser so the UI's documented limit works.
app.use('/api/umrah/register', express.json({ limit: '16mb' }));
app.use('/api/umrah/ocr-ktp', express.json({ limit: '16mb' }));
// Community payload caps must run before the global parser. Keep the more
// specific mutation paths first so their tighter limits take precedence.
app.use('/api/community/read', express.json({ limit: '2kb' }));
app.use('/api/community/posts/:id/reaction', express.json({ limit: '2kb' }));
app.use('/api/community/notification-prefs', express.json({ limit: '2kb' }));
app.use('/api/community/posts/:id/comments', express.json({ limit: '8kb' }));
// Ini batas yang berlaku, BUKAN yang di app.post('/api/community/posts', ...)
// di bawah — parser path-scoped berjalan sebelum parser route-level, jadi
// limit di route itu tidak pernah tereksekusi (jebakan ini sudah menggigit
// repo ini 3x). 96kb: utas 5 segmen dengan metadata media bisa melewati 32kb.
//
// Lampiran teks (maks 10.000 karakter) tidak muat di 96kb begitu datang
// bersama segmen utas + metadata media, jadi POST kiriman baru dinaikkan ke
// 256kb. Kenaikan itu digerbangi method+path PERSIS supaya HANYA
// `POST /api/community/posts` yang longgar: sub-path di bawahnya
// (poll-vote, PATCH edit, dst.) jatuh ke baris 96kb di bawah, tidak ikut
// naik hanya karena app.use mencocokkan prefiks.
const communityCreatePostJson = express.json({ limit: '256kb' });
app.use('/api/community/posts', (req, res, next) => (
  req.method === 'POST' && (req.path === '/' || req.path === '')
    ? communityCreatePostJson(req, res, next)
    : next()
));
app.use('/api/community/posts', express.json({ limit: '96kb' }));
// Webhook Resend Inbound butuh raw body (verifikasi signature Svix) — harus
// terpasang SEBELUM parser JSON global di bawah
app.use('/api/resend-inbound', express.raw({ type: '*/*', limit: '1mb' }));
app.use(express.json({ limit: '10mb' }));

// ──────────────────────────────────────────────
// Custom Domain — host detection + redirect middleware
// Harus dipasang sebelum semua route. Lookup agent by Host header,
// inject ke req.customDomainAgent supaya catch-all bisa pakai context yang sama.
// ──────────────────────────────────────────────

const agentDomainCache = new Map();
const AGENT_DOMAIN_CACHE_TTL = 5 * 60 * 1000;
const customDomainDnsHealthCache = new Map();
const CUSTOM_DOMAIN_DNS_HEALTH_TTL = 5 * 60 * 1000;

function isCustomDomainEnabledForAgent(agent) {
  return Boolean(agent?.slug);
}

const PRIMARY_HOSTS = new Set(['alhijaz.co', 'www.alhijaz.co']);
function isPrimaryHost(host) {
  if (!host) return true;
  if (PRIMARY_HOSTS.has(host)) return true;
  if (host === 'localhost' || host.startsWith('127.') || host.startsWith('0.0.0.0')) return true;
  // local dev tunneling / preview hosts — skip custom domain logic
  if (host.endsWith('.localhost')) return true;
  return false;
}

function isSharedStaticRequestPath(path) {
  const p = String(path || '/');
  if (p.startsWith('/api/')) return false;
  const firstSegment = p.split('/').filter(Boolean)[0]?.toLowerCase();
  if (['assets', 'fonts', 'agents', 'flags', 'logo-bank', 'wp-content', 'wp-includes'].includes(firstSegment)) {
    return true;
  }
  if (/^\/(?:sw\.js|manifest\.webmanifest|favicon(?:\.ico|\.svg)?|apple-touch-icon\.png|icon-\d+x\d+\.png|logo(?:-[\w-]+)?\.(?:png|svg|webp)|meta-logo\.(?:png|svg|webp)|workbox-[\w.-]+\.js)$/i.test(p)) {
    return true;
  }
  return /\.(?:js|mjs|css|map|png|jpe?g|webp|svg|ico|woff2?|ttf|otf|json|txt|xml)$/i.test(p);
}

async function getAgentByCustomDomain(host) {
  const key = (host || '').toLowerCase();
  if (!key) return null;
  const cached = agentDomainCache.get(key);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.agent;
  }
  const { data, error } = await supabase
    .from('agents')
    .select('*')
    .ilike('custom_domain', key)
    .eq('custom_domain_status', 'active')
    .limit(1)
    .maybeSingle();
  if (error) {
    console.warn('[custom-domain] lookup error for', key, '—', error.message);
    return null;
  }
  const agent = data && isCustomDomainEnabledForAgent(data) ? data : null;
  agentDomainCache.set(key, {
    agent,
    expiresAt: Date.now() + AGENT_DOMAIN_CACHE_TTL,
  });
  return agent;
}

function invalidateAgentDomainCache(host) {
  if (!host) return;
  agentDomainCache.delete(String(host).toLowerCase());
  customDomainDnsHealthCache.delete(String(host).toLowerCase());
}

async function isCustomDomainDnsHealthyForRedirect(domain) {
  const expectedIp = String(process.env.VPS_PUBLIC_IP || '').trim();
  if (!expectedIp) return true;

  const key = String(domain || '').trim().toLowerCase();
  if (!key) return false;

  const cached = customDomainDnsHealthCache.get(key);
  if (cached && cached.expiresAt > Date.now()) return cached.healthy;

  let healthy = false;
  try {
    const addresses = await dns.resolve4(key);
    healthy = addresses.includes(expectedIp);
    if (!healthy) {
      console.warn('[custom-domain] skip redirect, DNS mismatch:', key, '->', addresses.join(',') || '(empty)', 'expected', expectedIp);
    }
  } catch (err) {
    console.warn('[custom-domain] skip redirect, DNS lookup failed:', key, err.message);
  }

  customDomainDnsHealthCache.set(key, {
    healthy,
    expiresAt: Date.now() + CUSTOM_DOMAIN_DNS_HEALTH_TTL,
  });
  return healthy;
}

// 0) Gerbang maintenance sementara; no-op otomatis setelah deadline. Pada mode
// strict, JWT agent allowlist atau cookie login turunannya menjadi bypass.
app.use(createMaintenanceGate({
  isPrimaryHost,
  isSharedStaticRequestPath,
  verifyAccessToken: token => jwt.verify(token, JWT_SECRET),
}));

// 1) Host detection — set req.customDomainAgent when accessing via custom domain
app.use(async (req, res, next) => {
  const host = (req.hostname || '').toLowerCase();
  if (isPrimaryHost(host)) return next();
  if (isSharedStaticRequestPath(req.path || '/')) return next();
  try {
    const agent = await getAgentByCustomDomain(host);
    if (!agent) {
      return res.status(404).type('text/plain').send('Domain not configured for this service.');
    }
    req.customDomainAgent = agent;
    req.customDomain = host;
    next();
  } catch (err) {
    console.error('[custom-domain] host middleware error:', err);
    return res.status(500).type('text/plain').send('Internal Server Error');
  }
});

// 2) Pada custom domain: canonicalize URL (strip own slug), redirect auth, blokir /api/* sensitif
app.use((req, res, next) => {
  if (!req.customDomain) return next();
  const path = req.path || '/';
  // a) Strip own-slug prefix: miqot.com/nikita/umroh → miqot.com/umroh
  if (req.customDomainAgent) {
    const ownSlug = String(req.customDomainAgent.slug || '').toLowerCase();
    const firstSeg = path.split('/').filter(Boolean)[0]?.toLowerCase();
    if (ownSlug && firstSeg && firstSeg === ownSlug) {
      const restPath = path.replace(/^\/[^/]+/, '') || '/';
      const qs = req.url.includes('?') ? req.url.slice(req.url.indexOf('?')) : '';
      return res.redirect(301, restPath + qs);
    }
  }
  const isAuthPath =
    path.startsWith('/dashboard') ||
    path === '/login' ||
    path.startsWith('/login/') ||
    path === '/register' ||
    path.startsWith('/register/') ||
    path === '/admin' ||
    path.startsWith('/admin/') ||
    path.startsWith('/reset-password');
  if (isAuthPath) {
    const qs = req.url.includes('?') ? req.url.slice(req.url.indexOf('?')) : '';
    return res.redirect(301, `https://alhijaz.co${path}${qs}`);
  }
  if (path.startsWith('/api/')) {
    const isSensitiveApi =
      path.startsWith('/api/auth/') ||
      path === '/api/auth' ||
      path.startsWith('/api/admin/') ||
      path.startsWith('/api/agent/custom-domain');
    if (isSensitiveApi) {
      return res.status(404).type('text/plain').send('API only available on alhijaz.co');
    }
  }
  next();
});

// 3) Pada alhijaz.co: redirect /{slug}/... ke custom domain kalau agent punya
app.use(async (req, res, next) => {
  const host = (req.hostname || '').toLowerCase();
  if (!PRIMARY_HOSTS.has(host)) return next();
  const pathParts = req.path.split('/').filter(Boolean);
  const slug = (pathParts[0] || '').toLowerCase();
  if (!slug) return next();
  if (RESERVED_SPA_SLUGS.has(slug)) return next();
  if (slug.startsWith('api') || slug === 'dashboard') return next();
  try {
    const agent = await getAgentBySlug(slug);
    if (!isCustomDomainEnabledForAgent(agent)) return next();
    if (!agent?.custom_domain || agent.custom_domain_status !== 'active') return next();
    if (!(await isCustomDomainDnsHealthyForRedirect(agent.custom_domain))) return next();
    const restPath = pathParts.slice(1).join('/');
    const qs = req.url.includes('?') ? req.url.slice(req.url.indexOf('?')) : '';
    const target = `https://${agent.custom_domain}/${restPath}${qs}`;
    return res.redirect(301, target);
  } catch (err) {
    console.warn('[custom-domain] alhijaz redirect lookup failed:', err.message);
    next();
  }
});

// ── Analytics: fire-and-forget event logger ──
function getClientIpUa(req) {
  if (!req) return { ip: null, userAgent: null };
  const fwd = req.headers?.['x-forwarded-for'] || '';
  const ip = (typeof fwd === 'string' ? fwd.split(',')[0].trim() : '') || req.ip || null;
  const userAgent = req.headers?.['user-agent'] || null;
  return { ip, userAgent };
}

async function logAnalyticsEvent(agentId, eventType, eventName, metadata = {}, opts = {}) {
  if (!agentId) {
    console.warn('[Analytics] Skipping event with null agent_id:', { eventType, eventName });
    return { ok: false, error: 'missing agent_id' };
  }
  try {
    const { error } = await supabase.from('analytics_events').insert({
      agent_id: agentId,
      event_type: eventType,
      event_name: eventName,
      metadata,
      ip: opts.ip || null,
      user_agent: opts.userAgent || null,
    });
    if (error) {
      console.error('[Analytics] Supabase insert error:', error.message, error.details);
      return { ok: false, error: error.message };
    }
    return { ok: true };
  } catch (err) {
    console.error('[Analytics] Log error:', err.message);
    return { ok: false, error: err.message };
  }
}

// ── Stats cache (60s TTL, per agent+year) ────────────────────────────
const STATS_TTL_MS = 60 * 1000;
const statsCache = new Map(); // key -> { data, expiresAt }

function statsCacheGet(key) {
  const entry = statsCache.get(key);
  if (!entry) return null;
  if (Date.now() > entry.expiresAt) {
    statsCache.delete(key);
    return null;
  }
  return entry.data;
}

function statsCacheSet(key, data) {
  statsCache.set(key, { data, expiresAt: Date.now() + STATS_TTL_MS });
}

function invalidateStatsCache(agentId) {
  if (!agentId) return;
  for (const k of statsCache.keys()) {
    if (k.includes(`:${agentId}:`)) statsCache.delete(k);
  }
}

// Periodic cleanup of expired entries (every 5 min)
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of statsCache.entries()) {
    if (now > v.expiresAt) statsCache.delete(k);
  }
}, 5 * 60 * 1000);

// ============ KURS BANK MANDIRI ============
let kursCache = null; // { rates: { USD: number, ... }, updatedAt: string, fetchedAt: number }
const KURS_CACHE_TTL = 6 * 60 * 60 * 1000; // 6 hours
const KURS_REFRESH_INTERVAL = Number(process.env.KURS_REFRESH_INTERVAL_MS || 30 * 60 * 1000); // 30 minutes
let kursRefreshInFlight = null;

async function loadKursFromSupabase() {
  try {
    const { data, error } = await supabase
      .from('kurs_cache')
      .select('data, synced_at')
      .eq('id', 'mandiri')
      .single();
    if (error || !data) return false;
    kursCache = {
      rates: data.data.rates,
      updatedAt: data.data.updatedAt,
      fetchedAt: new Date(data.synced_at).getTime(),
    };
    console.log(`[Kurs] Loaded from Supabase. USD=${kursCache.rates.USD}, synced: ${data.synced_at}`);
    return true;
  } catch (err) {
    console.error('[Kurs] Supabase load error:', err.message);
    return false;
  }
}

// Returns true if fetched data is from today, false otherwise
async function fetchKursMandiri() {
  try {
    const res = await fetch('https://www.bankmandiri.co.id/kurs', {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/135.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
        'Accept-Language': 'id-ID,id;q=0.9,en-US;q=0.8,en;q=0.7',
        'Accept-Encoding': 'gzip, deflate, br',
        'Referer': 'https://www.bankmandiri.co.id/',
        'Sec-Fetch-Dest': 'document',
        'Sec-Fetch-Mode': 'navigate',
        'Sec-Fetch-Site': 'same-origin',
        'Sec-Ch-Ua': '"Chromium";v="135", "Google Chrome";v="135", "Not-A.Brand";v="8"',
        'Sec-Ch-Ua-Mobile': '?0',
        'Sec-Ch-Ua-Platform': '"Windows"',
        'Cache-Control': 'no-cache',
      },
      signal: AbortSignal.timeout(15000),
    });

    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const html = await res.text();
    const { rates, updatedAt } = parseMandiriKursHtml(html);

    if (Object.keys(rates).length > 0) {
      const nextCache = {
        rates,
        updatedAt: updatedAt || new Date().toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }),
        fetchedAt: Date.now(),
      };
      if (!shouldReplaceKursCache(kursCache, nextCache)) {
        console.log(`[Kurs] Fetched older data (${nextCache.updatedAt}); keeping cache ${kursCache.updatedAt}`);
        kursCache.fetchedAt = Date.now();
        return isKursToday(kursCache.updatedAt);
      }
      kursCache = nextCache;
      console.log(`[Kurs] Fetched ${Object.keys(rates).length} currencies. USD=${rates.USD}, SAR=${rates.SAR}, date=${updatedAt}`);

      // Persist to Supabase
      try {
        await supabase.from('kurs_cache').upsert({
          id: 'mandiri',
          data: { rates: kursCache.rates, updatedAt: kursCache.updatedAt },
          synced_at: new Date().toISOString(),
        }, { onConflict: 'id' });
        console.log('[Kurs] Persisted to Supabase');
      } catch (err) {
        console.error('[Kurs] Supabase persist error:', err.message);
      }

      return isKursToday(kursCache.updatedAt);
    } else {
      console.warn('[Kurs] Gagal parse rates dari halaman Bank Mandiri');
      return false;
    }
  } catch (err) {
    console.error('[Kurs] Fetch error:', err.message);
    return false;
  }
}

async function refreshKursIfDue({ force = false } = {}) {
  if (!force && !isKursCacheRefreshDue(kursCache, Date.now(), KURS_REFRESH_INTERVAL)) {
    return isKursToday(kursCache?.updatedAt);
  }
  if (!kursRefreshInFlight) {
    kursRefreshInFlight = fetchKursMandiri().finally(() => {
      kursRefreshInFlight = null;
    });
  }
  return kursRefreshInFlight;
}

// On startup: load from Supabase, then fetch fresh if cache is missing or stale.
// Telegram broadcast is NOT triggered here — only after the scheduled daily
// scrape (10:02 WIB) succeeds. This prevents re-broadcasting whenever the
// server restarts during the day.
(async () => {
  const loaded = await loadKursFromSupabase();
  if (!loaded) {
    console.log('[Kurs] No Supabase cache, attempting first fetch...');
    await refreshKursIfDue({ force: true });
  } else if (isKursCacheRefreshDue(kursCache, Date.now(), KURS_REFRESH_INTERVAL)) {
    console.log('[Kurs] Cached kurs is due for refresh, fetching fresh...');
    await refreshKursIfDue({ force: true });
  }
})();

const KURS_RETRY_INTERVAL = 15 * 60 * 1000; // 15 minutes
const KURS_MAX_RETRIES = 8;

function scheduleKursCron() {
  const now = new Date();
  // 10:02 WIB = 03:02 UTC
  const next = new Date(now);
  next.setUTCHours(3, 2, 0, 0);
  if (next <= now) {
    next.setUTCDate(next.getUTCDate() + 1);
  }
  const msUntil = next - now;
  const wibHour = (next.getUTCHours() + 7) % 24;
  const wibMin = String(next.getUTCMinutes()).padStart(2, '0');
  console.log(`[Kurs] Next daily fetch in ${Math.round(msUntil / 60000)} minutes (${wibHour}:${wibMin} WIB)`);
  setTimeout(async () => {
    await fetchKursWithRetry();
    scheduleKursCron();
  }, msUntil);
}

async function fetchKursWithRetry() {
  for (let attempt = 1; attempt <= KURS_MAX_RETRIES; attempt++) {
    const isCurrent = await fetchKursMandiri();
    if (isCurrent) {
      console.log(`[Kurs] Got today's rates on attempt ${attempt}`);
      sendKursUpdate().catch(err => console.error('[Kurs] post-scrape send error:', err.message));
      return;
    }
    if (attempt < KURS_MAX_RETRIES) {
      console.log(`[Kurs] Data belum hari ini (attempt ${attempt}/${KURS_MAX_RETRIES}), retry in 15 min...`);
      await new Promise(r => setTimeout(r, KURS_RETRY_INTERVAL));
    } else {
      console.warn(`[Kurs] Max retries reached (${KURS_MAX_RETRIES}), using latest available data`);
    }
  }
}

if (shouldRunBackgroundJobs()) {
  scheduleKursCron();
} else {
  console.log('[BackgroundJobs] Disabled — skipping kurs daily fetch and Telegram broadcast scheduler');
}

async function runKursShareCacheCleanup(reason = 'scheduled') {
  try {
    const stats = await cleanupKursShareCache();
    console.log(
      `[KursShareCache] Cleanup ${reason}: scanned=${stats.scanned}, ` +
      `expired=${stats.deletedExpired}, size=${stats.deletedForSize}, ` +
      `freed=${Math.round(stats.freedBytes / 1024)}KB, remaining=${Math.round(stats.remainingBytes / 1024)}KB`
    );
  } catch (err) {
    console.warn('[KursShareCache] Cleanup failed:', err.message);
  }
}

runKursShareCacheCleanup('startup');
cron.schedule('30 3 * * *', () => {
  runKursShareCacheCleanup('daily');
}, { timezone: 'Asia/Jakarta' });

function scheduleAnalyticsMaintenanceCron() {
  // 02:00 WIB daily via persistent cron — a per-boot setTimeout could be perpetually
  // deferred by frequent restarts, leaving the analytics_events_daily rollup stale.
  cron.schedule('0 2 * * *', async () => {
    try {
      await runAnalyticsMaintenance(supabase);
    } catch (err) {
      console.error('[Analytics] Maintenance run threw:', err.message);
    }
  }, { timezone: 'Asia/Jakarta' });
  console.log('[Analytics] Maintenance cron scheduled (02:00 WIB daily)');
}

if (shouldRunBackgroundJobs()) scheduleAnalyticsMaintenanceCron();

// GET /api/kurs — Kurs semua mata uang (public, no auth)
app.get('/api/kurs', async (req, res) => {
  if (isKursCacheRefreshDue(kursCache, Date.now(), KURS_REFRESH_INTERVAL)) {
    await refreshKursIfDue();
  }
  if (!kursCache || Object.keys(kursCache.rates).length === 0) {
    return res.json({
      success: false,
      error: 'Kurs belum tersedia, coba lagi nanti',
    });
  }
  res.json({
    success: true,
    data: {
      rates: kursCache.rates,
      names: CURRENCY_NAMES,
      updatedAt: kursCache.updatedAt,
      stale: Date.now() - kursCache.fetchedAt > KURS_CACHE_TTL * 2,
    },
  });
});

app.get('/api/tour-leader-prep/:tripSlug', async (req, res) => {
  const { tripSlug } = req.params;
  if (tripSlug !== RAHMAH_JULI_PUBLIC_SLUG) {
    return res.status(404).json({ success: false, error: 'Paket tidak ditemukan' });
  }

  try {
    const { data, error } = await supabase
      .from(TOUR_LEADER_PREP_TABLE)
      .select('id_umroh,tahapan')
      .in('id_umroh', RAHMAH_JULI_ID_UMRAH);
    if (error) throw error;
    const rows = (data || [])
      .flatMap((row) => tourLeaderPrepRowToItems(row))
      .sort((left, right) => left.jamaah_no - right.jamaah_no);
    return res.json({ success: true, data: rows });
  } catch (err) {
    console.error('GET /api/tour-leader-prep error:', err?.message || err);
    return res.status(500).json({ success: false, error: 'Gagal memuat data jamaah' });
  }
});

app.put('/api/tour-leader-prep/:tripSlug/:jamaahNo', async (req, res) => {
  const jamaahNo = Number(req.params.jamaahNo);
  const validation = validateTourLeaderPrepPayload(req.params.tripSlug, jamaahNo, req.body);
  if (validation.error) {
    return res.status(400).json({ success: false, error: validation.error });
  }

  try {
    const { member, entry } = validation;
    const { data: existing, error: readError } = await supabase
      .from(TOUR_LEADER_PREP_TABLE)
      .select('agent_id,tahapan,spiritual')
      .eq('id_umroh', member.idUmrah)
      .maybeSingle();
    if (readError) throw readError;

    let agentId = existing?.agent_id || null;
    if (!agentId) {
      const { data: jamaahRow, error: jamaahError } = await supabase
        .from('jamaah')
        .select('agent_id')
        .eq('id_umroh', member.idUmrah)
        .not('agent_id', 'is', null)
        .limit(1)
        .maybeSingle();
      if (jamaahError) throw jamaahError;
      agentId = jamaahRow?.agent_id || null;
    }

    if (!agentId) {
      return res.status(404).json({ success: false, error: 'Data booking jamaah belum ditemukan' });
    }

    const tahapan = plainObjectOrEmpty(existing?.tahapan);
    const tripPrep = plainObjectOrEmpty(tahapan[RAHMAH_JULI_PUBLIC_SLUG]);
    const jamaahPrep = plainObjectOrEmpty(tripPrep.jamaah);
    const now = new Date().toISOString();
    const nextTahapan = {
      ...tahapan,
      [RAHMAH_JULI_PUBLIC_SLUG]: {
        ...tripPrep,
        jamaah: {
          ...jamaahPrep,
          [String(member.no)]: entry,
        },
      },
    };

    const { error: upsertError } = await supabase.from('booking_persiapan').upsert({
      id_umroh: member.idUmrah,
      agent_id: agentId,
      tahapan: nextTahapan,
      spiritual: plainObjectOrEmpty(existing?.spiritual),
      updated_at: now,
    }, { onConflict: 'id_umroh' });
    if (upsertError) throw upsertError;
    return res.json({ success: true });
  } catch (err) {
    console.error('PUT /api/tour-leader-prep error:', err?.message || err);
    return res.status(500).json({ success: false, error: 'Gagal menyimpan data jamaah' });
  }
});

// GET /api/kurs/share-image — per-agent kurs image, generated on demand and cached on disk.
app.get('/api/kurs/share-image', authMiddleware, async (req, res) => {
  try {
    if (!kursCache || Object.keys(kursCache.rates || {}).length === 0) {
      return res.status(503).json({
        success: false,
        error: 'Kurs belum tersedia, coba lagi nanti',
      });
    }

    const usd = kursCache.rates?.USD;
    if (!usd) {
      return res.status(503).json({
        success: false,
        error: 'Kurs USD belum tersedia',
      });
    }

    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ success: false, error: 'Agent not found' });

    const result = await getOrCreateKursShareImage({
      kurs: {
        usd,
        updatedAt: formatKursDateForShare(kursCache.updatedAt),
      },
      agent: {
        name: agent.name || '',
        phone: agent.phone || '',
        photo: agent.photo || '',
        slug: agent.slug || req.user.slug,
        website: agent.website || '',
      },
    });

    const dateForFilename = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Jakarta' }).replace(/-/g, '');
    const filename = `kurs-${agent.slug || req.user.slug}-${dateForFilename}.jpg`;
    res.set({
      'Content-Type': 'image/jpeg',
      'Content-Length': String(result.buffer.length),
      'Content-Disposition': `inline; filename="${filename}"`,
      'Cache-Control': 'no-store',
      'X-Kurs-Image-Cache': result.cacheHit ? 'HIT' : 'MISS',
    });
    res.send(result.buffer);
  } catch (err) {
    console.error('[KursShare] Generate error:', err.message);
    try { Sentry.captureException(err); } catch { /* noop */ }
    res.status(500).json({
      success: false,
      error: 'Gagal generate gambar kurs',
    });
  }
});


