// ── JWT Auth middleware ──
async function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Token required' });
  }
  try {
    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, JWT_SECRET);
    // Backward compat: old tokens don't have id, resolve from slug
    if (!decoded.id && decoded.slug) {
      let agent = await getAgentBySlug(decoded.slug);
      // If slug was changed, check history
      if (!agent) {
        const { data: history } = await supabase
          .from('agent_slug_history')
          .select('agent_id')
          .eq('old_slug', decoded.slug)
          .order('changed_at', { ascending: false })
          .limit(1)
          .single();
        if (history) agent = await getAgentById(history.agent_id);
      }
      if (agent) {
        decoded.id = agent.id;
        decoded.slug = agent.slug; // update to current slug
      }
    }
    if (!decoded.id) {
      return res.status(401).json({ error: 'Invalid or expired token' });
    }
    req.user = decoded; // { id, slug, name, role }
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

function adminOnly(req, res, next) {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin access required' });
  }
  next();
}

// ── Agent cache (in-memory, refreshes every 5 minutes) ──
let agentCacheById = null;
let agentCacheBySlug = null;
let agentCacheByAlias = null;
let agentCacheTime = 0;
const AGENT_CACHE_TTL = 5 * 60 * 1000; // 5 min
// When a refresh FAILS (DB unreachable / 522), keep serving the stale cache and
// back off for this long before retrying. Without it, agentCacheTime only advances
// on success — so during a DB blip the cache stays "expired" and EVERY public
// request re-fires `agents?select=*` against the sick DB. On the small instance
// that stampede depletes the Disk-IO burst and turns a few-second blip into a
// prolonged 522 outage (incident 2026-06-03). See [[db-io-throttling-incident]].
const AGENT_CACHE_FAIL_TTL = 15 * 1000; // 15s backoff after a failed refresh
let agentCacheFailUntil = 0;
let agentRefreshInFlight = null; // single-flight: collapse concurrent refreshes onto one query

async function getAgents() {
  const now = Date.now();
  if (agentCacheById && now - agentCacheTime < AGENT_CACHE_TTL) return agentCacheById;
  // A recent refresh failed — serve stale cache instead of stampeding a sick DB.
  if (agentCacheById && now < agentCacheFailUntil) return agentCacheById;
  // Single-flight: if a refresh is already running, await it rather than firing another.
  if (agentRefreshInFlight) return agentRefreshInFlight;
  agentRefreshInFlight = (async () => {
    const { data, error } = await supabase.from('agents').select('*');
    if (error) {
      console.error('[Supabase] agents fetch error:', error.message);
      agentCacheFailUntil = Date.now() + AGENT_CACHE_FAIL_TTL;
      return agentCacheById || {};
    }
    const idMap = {};
    const slugMap = {};
    const aliasMap = {};
    for (const a of data) {
      idMap[a.id] = a;
      slugMap[a.slug] = a;
      if (a.email_alias) aliasMap[a.email_alias.toLowerCase()] = a;
    }
    agentCacheById = idMap;
    agentCacheBySlug = slugMap;
    agentCacheByAlias = aliasMap;
    agentCacheTime = Date.now();
    agentCacheFailUntil = 0;
    return idMap;
  })().finally(() => { agentRefreshInFlight = null; });
  return agentRefreshInFlight;
}

async function getAgentsBySlug() {
  await getAgents();
  return agentCacheBySlug || {};
}

async function getAgentById(id) {
  const agents = await getAgents();
  return agents[id] || null;
}

async function getAgentBySlug(slug) {
  await getAgents();
  return (agentCacheBySlug || {})[slug] || null;
}

async function getAgentByAlias(alias) {
  await getAgents();
  return (agentCacheByAlias || {})[String(alias).toLowerCase()] || null;
}

function invalidateAgentCache() {
  agentCacheById = null;
  agentCacheBySlug = null;
  agentCacheByAlias = null;
  agentCacheTime = 0;
  agentCacheFailUntil = 0;
}

// One-account-per-agent guard: find another agent (≠ excludeAgentId) that
// currently has the given legacy/internal account (jamaah_username) connected.
// Case-insensitive exact match. Returns the claiming agent {id,slug,name} or
// null. Fails open (returns null) on a DB error so a transient blip never locks
// a legitimate agent out of connecting.
async function findAgentUsingInternalAccount(username, excludeAgentId) {
  const escaped = escapeInternalAccountLike(username);
  if (!escaped) return null;
  let query = supabase
    .from('agents')
    .select('id, slug, name')
    .ilike('jamaah_username', escaped)
    .limit(1);
  if (excludeAgentId) query = query.neq('id', excludeAgentId);
  const { data, error } = await query;
  if (error) {
    console.warn(`[internal-account-guard] lookup failed for ${username}: ${error.message}`);
    return null;
  }
  return (data && data[0]) || null;
}

// ── umroh_schedules in-memory cache ──
// Used by /api/laporan/jamaah to enrich rows with jadwal_nama without hitting DB
// each request. Schedules table is small (<200 rows total) and rarely changes
// (sync runs ~daily), so a simple full-table cache with TTL is plenty.
let scheduleMapCache = { map: null, expiresAt: 0 };
const SCHEDULE_CACHE_TTL_MS = 5 * 60 * 1000;
async function getScheduleMap() {
  if (scheduleMapCache.map && Date.now() < scheduleMapCache.expiresAt) {
    return scheduleMapCache.map;
  }
  const { data: schedules, error } = await supabase
    .from('umroh_schedules')
    .select('jadwal_id, jadwal_nama');
  if (error) {
    console.warn('[scheduleMap] fetch failed, returning empty map:', error.message);
    return new Map();
  }
  const map = new Map((schedules || []).map(s => [s.jadwal_id, s.jadwal_nama]));
  scheduleMapCache = { map, expiresAt: Date.now() + SCHEDULE_CACHE_TTL_MS };
  return map;
}

let scheduleDetailMapCache = { map: null, expiresAt: 0 };
async function getScheduleDetailMap() {
  if (scheduleDetailMapCache.map && Date.now() < scheduleDetailMapCache.expiresAt) {
    return scheduleDetailMapCache.map;
  }
  const { data: schedules, error } = await supabase
    .from('umroh_schedules')
    .select('jadwal_id, jadwal_nama, manasik_tgl, manasik_jam, berangkat_tgl, berangkat_kode_penerbangan');
  if (error) {
    console.warn('[scheduleDetailMap] fetch failed, returning empty map:', error.message);
    return new Map();
  }
  const map = new Map((schedules || []).map(s => [s.jadwal_id, s]));
  scheduleDetailMapCache = { map, expiresAt: Date.now() + SCHEDULE_CACHE_TTL_MS };
  return map;
}

// ── Landing config helpers ──
// Raw description from /public/{umroh,haji-plus}.html — read once at boot.
// Shown to agents as placeholder text so they see the literal fallback the public page serves.
let rawLandingDescription = { umroh: '', haji: '' };
try {
  const extractDescription = (html) => {
    const m = html.match(/<meta\s+name=["']description["']\s+content=["']([^"']*)["']/i);
    return m ? m[1] : '';
  };
  rawLandingDescription = {
    umroh: extractDescription(readFileSync(resolve(__dirname, 'public/umroh.html'), 'utf-8')),
    haji: extractDescription(readFileSync(resolve(__dirname, 'public/haji-plus.html'), 'utf-8')),
  };
} catch (e) {
  console.warn('[LandingConfig] Could not read raw HTML descriptions:', e.message);
}

function getDefaultLandingConfig(agent) {
  const name = agent?.name || 'Alhijaz';
  return {
    umroh: {
      title: `Umroh | ${name} | PT Alhijaz Indowisata`,
      description: null,   // null = don't inject; raw HTML description stays
      og_image_url: null,  // null = fall back to /og/{slug}.png
    },
    haji: {
      title: `Haji Plus | ${name} | PT Alhijaz Indowisata`,
      description: null,
      og_image_url: null,
    },
  };
}

function mergeLandingConfig(agent) {
  const defaults = getDefaultLandingConfig(agent);
  const custom = agent?.landing_config || {};
  return {
    umroh: {
      title: custom.umroh?.title || defaults.umroh.title,
      description: custom.umroh?.description ?? defaults.umroh.description,
      og_image_url: custom.umroh?.og_image_url ?? defaults.umroh.og_image_url,
    },
    haji: {
      title: custom.haji?.title || defaults.haji.title,
      description: custom.haji?.description ?? defaults.haji.description,
      og_image_url: custom.haji?.og_image_url ?? defaults.haji.og_image_url,
    },
  };
}

function invalidateLandingCaches(slug) {
  umrohLandingCache.delete(slug);
  hajiLandingCache.delete(slug);
  landingCacheEpochBySlug.set(slug, (landingCacheEpochBySlug.get(slug) || 0) + 1);
}

const landingCacheEpochBySlug = new Map();

function landingCacheEpoch(slug) {
  return landingCacheEpochBySlug.get(slug) || 0;
}

function setLandingCacheIfCurrent(cache, slug, epoch, html) {
  if (landingCacheEpoch(slug) !== epoch) return false;
  cache.set(slug, { html, ts: Date.now() });
  return true;
}

// Fire-and-forget: regenerate /public/og/{slug}.png using fresh agent data.
// Safe to call from any request handler — never throws, never blocks the response.
function triggerOgRegen(slug) {
  if (!slug) return;
  const normalizedSlug = String(slug).toLowerCase();
  (async () => {
    try {
      // Fetch fresh from Supabase (bypass any stale cache)
      const { data, error } = await supabase
        .from('agents')
        .select('slug, name, website, phone, photo')
        .eq('slug', normalizedSlug)
        .maybeSingle();
      if (error || !data) {
        console.warn(`[og-regen] Skipping ${normalizedSlug}:`, error?.message || 'not found');
        return;
      }
      await regenerateOgForAgent(data);
      // Bust the SSR landing-page HTML cache so the new OG URL is re-read on next request
      invalidateLandingCaches(normalizedSlug);
    } catch (err) {
      console.warn(`[og-regen] Failed for ${normalizedSlug}:`, err.message);
    }
  })();
}

