// Buat alias — SEKALI SAJA per agent, tidak bisa diganti setelahnya
app.post('/api/agent/email-alias', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!emailAliasConfigured) {
      return res.status(503).json({ error: 'Fitur email alias belum dikonfigurasi di server' });
    }
    if (agent.email_alias) {
      return res.status(400).json({
        error: 'ALIAS_LOCKED',
        message: 'Alias sudah pernah dibuat dan tidak bisa diganti.',
      });
    }
    if (!agent.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(agent.email)) {
      return res.status(400).json({
        error: 'EMAIL_REQUIRED',
        message: 'Isi email tujuan yang valid terlebih dahulu.',
      });
    }
    const alias = String(req.body?.alias || '').trim().toLowerCase();
    if (!/^[a-z]{3,25}$/.test(alias)) {
      return res.status(400).json({ error: 'Alias hanya boleh huruf, 3-25 karakter' });
    }
    if (RESERVED_EMAIL_LOCAL_PARTS.includes(alias)) {
      return res.status(400).json({ error: 'Alias ini tidak tersedia' });
    }
    // Cegah memakai username agent lain (squatting nama) atau alias yang sudah diambil
    const bySlug = await getAgentBySlug(alias);
    if (bySlug && bySlug.id !== agent.id) {
      return res.status(400).json({ error: 'Alias ini tidak tersedia' });
    }
    if (await getAgentByAlias(alias)) {
      return res.status(400).json({ error: 'Alias ini tidak tersedia' });
    }
    // Set-once: guard .is(null) menahan race double-submit; unique index
    // lower(email_alias) menahan race antar-agent
    const { data: updated, error } = await supabase
      .from('agents')
      .update({ email_alias: alias, email_alias_enabled: true })
      .eq('id', req.user.id)
      .is('email_alias', null)
      .select('email_alias');
    if (error) {
      if (error.code === '23505') return res.status(400).json({ error: 'Alias ini tidak tersedia' });
      throw error;
    }
    if (!updated || !updated.length) {
      return res.status(400).json({ error: 'ALIAS_LOCKED', message: 'Alias sudah pernah dibuat dan tidak bisa diganti.' });
    }
    invalidateAgentCache();
    if (req.user.role !== 'admin') {
      logAnalyticsEvent(req.user.id, 'action', 'set_email_alias', { alias }, getClientIpUa(req));
    }
    res.json({ success: true, alias: `${alias}@${ALIAS_DOMAIN}` });
  } catch (err) {
    console.error('[email-alias] set error:', err);
    res.status(500).json({ error: 'Gagal membuat alias email' });
  }
});

// Upload profile photo (base64 JPEG) → Supabase Storage
app.post('/api/admin/photo', authMiddleware, express.json({ limit: '5mb' }), async (req, res) => {
  const { image, slug: targetSlug } = req.body; // base64 data URL, optional slug for admin
  console.log('[Photo] incoming upload', {
    userId: req.user?.id,
    userSlug: req.user?.slug,
    userRole: req.user?.role,
    targetSlug: targetSlug || null,
    hasImage: !!image,
    imageLength: typeof image === 'string' ? image.length : null,
    imagePrefix: typeof image === 'string' ? image.slice(0, 32) : null,
    contentLength: req.headers['content-length'],
  });
  if (!image) return res.status(400).json({ error: 'No image provided' });

  // Admin can upload for any agent; non-admin only for themselves
  let targetAgent;
  if (req.user.role === 'admin' && targetSlug) {
    targetAgent = await getAgentBySlug(targetSlug.toLowerCase());
  } else {
    targetAgent = await getAgentById(req.user.id);
  }
  if (!targetAgent) return res.status(404).json({ error: 'Agent not found' });
  const slug = targetAgent.slug;

  try {
    // Extract base64 data
    const base64Data = image.replace(/^data:image\/\w+;base64,/, '');
    const buffer = Buffer.from(base64Data, 'base64');

    // Upload to Supabase Storage bucket 'agent-photos'
    const fileName = `${slug}.jpg`;

    // Remove existing file first (upsert can be unreliable)
    await supabase.storage.from('agent-photos').remove([fileName]);

    const { error: uploadError } = await supabase.storage
      .from('agent-photos')
      .upload(fileName, buffer, {
        contentType: 'image/jpeg',
        upsert: true,
        // URL selalu dirujuk dengan ?v= buster, jadi aman di-cache setahun
        cacheControl: '31536000',
      });
    if (uploadError) {
      console.error('Supabase Storage upload error:', uploadError);
      throw uploadError;
    }

    // Get public URL with cache buster
    const { data: urlData } = supabase.storage.from('agent-photos').getPublicUrl(fileName);
    const photoUrl = `${urlData.publicUrl}?v=${Date.now()}`;
    console.log(`[Photo] ${slug} uploaded → ${photoUrl}`);
    await supabase.from('agents').update({ photo: photoUrl }).eq('id', targetAgent.id);

    // Invalidate cache
    invalidateAgentCache();
    // Regenerate default OG image with the new photo (fire-and-forget)
    triggerOgRegen(slug);
    res.json({ success: true, photo: photoUrl });
  } catch (err) {
    console.error('Photo upload error:', err);
    res.status(500).json({ error: 'Failed to save photo' });
  }
});

