app.get('/api/community/feed', dbLoadShedGuard, authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    const before = req.query.before === undefined
      ? null
      : normalizeCommunityCursor(req.query.before);
    if (req.query.before !== undefined && !before) {
      return res.status(400).json({ error: 'Cursor feed tidak valid' });
    }

    // Profile mode: /teras/<slug> reuses the same feed, filtered to one agent.
    if (req.query.agent !== undefined && typeof req.query.agent !== 'string') {
      return res.status(400).json({ error: 'Parameter agent tidak valid' });
    }
    const profileSlug = typeof req.query.agent === 'string'
      ? req.query.agent.trim().toLowerCase()
      : '';
    let profileMember = null;
    if (profileSlug) {
      const members = await loadCommunityMembers();
      profileMember = members.find(m => String(m.slug || '').toLowerCase() === profileSlug) || null;
      if (!profileMember) {
        return res.status(404).json({ error: 'Agent tidak ditemukan di Teras' });
      }
    }

    const buildPostsQuery = (includeMedia, includeQuote, includeLinkPreview, includeThread, includeEdited, includePin) => {
      let query = supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${includeMedia ? 'media, ' : ''}${includeQuote ? 'quoted_post_id, ' : ''}${includeLinkPreview ? 'link_preview, ' : ''}${includeThread ? 'parent_post_id, is_reply, ' : ''}${includeEdited ? 'edited_at, ' : ''}${includePin ? 'pinned_at, ' : ''}is_system, created_at, agent_id, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .is('deleted_at', null);
      if (profileMember) {
        query = query.eq('agent_id', profileMember.id);
      }
      // Segmen lanjutan sebuah utas tidak pernah muncul di daftar. Linimasa
      // (non-profil): hanya kiriman induk (parent_post_id IS NULL) — utas
      // tampil sebagai satu unit lewat kartu segmen pertamanya, balasan tidak
      // muncul di sini sama sekali. Profil: kiriman induk + balasan
      // (is_reply=true) ikut tampil dengan konteks "Membalas ke @X", TAPI
      // segmen lanjutan (parent_post_id terisi, is_reply=false) tetap
      // disembunyikan -- itulah gunanya is_reply sebagai pembeda (keduanya
      // sama-sama punya parent_post_id, lihat reconcile-map §3).
      // Pra-migrasi (includeThread=false): parent_post_id/is_reply belum ada
      // di kolom sama sekali, jadi filter apapun di sini akan 500 -- dilewati
      // total, sama seperti degradasi filter lain di endpoint ini.
      if (includeThread && !profileMember) {
        query = query.is('parent_post_id', null);
      }
      // Mode profil + cursor (parent_post_id.is.null OR is_reply.eq.true) DAN
      // cursor keyset (created_at.lt.C OR (created_at.eq.C AND id.lt.P)) sama-
      // sama butuh .or() -- tapi PostgREST TIDAK dijamin meng-AND-kan dua
      // parameter or= terpisah pada satu query (belum diverifikasi di sini).
      // Kalau salah asumsi, filter thread bisa diam-diam hilang di halaman
      // ke-2 dan SEGMEN LANJUTAN UTAS BOCOR ke profil. Supaya pasti benar,
      // keduanya didistribusikan (DNF) jadi SATU .or() top-level saja untuk
      // kombinasi profil+includeThread. Cabang linimasa (non-profil) tidak
      // tersentuh -- thread di sana pakai .is(), jadi cuma ada satu .or()
      // (cursor) seperti sebelumnya, tidak ada risiko dua-or.
      if (before?.postId) {
        query = (includeThread && profileMember)
          ? query.or(
              `and(parent_post_id.is.null,created_at.lt.${before.createdAt}),` +
              `and(parent_post_id.is.null,created_at.eq.${before.createdAt},id.lt.${before.postId}),` +
              `and(is_reply.eq.true,created_at.lt.${before.createdAt}),` +
              `and(is_reply.eq.true,created_at.eq.${before.createdAt},id.lt.${before.postId})`,
            )
          : query.or(
              `created_at.lt.${before.createdAt},and(created_at.eq.${before.createdAt},id.lt.${before.postId})`,
            );
      } else if (before) {
        // Keep accepting the original timestamp-only cursor for older clients.
        query = (includeThread && profileMember)
          ? query.or(
              `and(parent_post_id.is.null,created_at.lt.${before.createdAt}),` +
              `and(is_reply.eq.true,created_at.lt.${before.createdAt})`,
            )
          : query.lt('created_at', before.createdAt);
      } else if (includeThread && profileMember) {
        query = query.or('parent_post_id.is.null,is_reply.eq.true');
      }
      return query
        .order('created_at', { ascending: false })
        .order('id', { ascending: false })
        .limit(20);
    };

    let includeMedia = true;
    let includeQuote = true;
    let includeLinkPreview = true;
    let includeThread = true;
    let includeEdited = true;
    let includePin = true;
    let posts = null;
    let postsError = null;
    // 6 percobaan gagal (media, quote, link preview, thread, edited, pin) + 1
    // percobaan sukses = 7.
    for (let attempt = 0; attempt < 7; attempt += 1) {
      ({ data: posts, error: postsError } = await buildPostsQuery(includeMedia, includeQuote, includeLinkPreview, includeThread, includeEdited, includePin));
      if (includeMedia && isCommunityMediaSchemaMissing(postsError)) {
        includeMedia = false;
        continue;
      }
      if (includeQuote && isCommunityQuoteSchemaMissing(postsError)) {
        includeQuote = false;
        continue;
      }
      if (includeLinkPreview && isCommunityLinkPreviewSchemaMissing(postsError)) {
        includeLinkPreview = false;
        continue;
      }
      if (includeThread && isCommunityThreadSchemaMissing(postsError)) {
        includeThread = false;
        continue;
      }
      if (includeEdited && isCommunityEditSchemaMissing(postsError)) {
        includeEdited = false;
        continue;
      }
      if (includePin && isCommunityPinSchemaMissing(postsError)) {
        includePin = false;
        continue;
      }
      break;
    }
    if (postsError) throw postsError;

    // Kiriman tersemat: hanya halaman pertama linimasa utama. Query terpisah
    // (bukan bagian cursor) — dedup dilakukan klien saat render.
    let pinnedRow = null;
    if (!before && !profileMember && includePin) {
      const { data: row, error: pinnedError } = await supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${includeMedia ? 'media, ' : ''}${includeQuote ? 'quoted_post_id, ' : ''}${includeLinkPreview ? 'link_preview, ' : ''}${includeThread ? 'parent_post_id, is_reply, ' : ''}pinned_at, ${includeEdited ? 'edited_at, ' : ''}is_system, created_at, agent_id, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .not('pinned_at', 'is', null)
        .is('deleted_at', null)
        .maybeSingle();
      // Degradasi senyap: galat apa pun pada query pinned tidak boleh
      // menggagalkan feed.
      if (!pinnedError && row) pinnedRow = row;
    }

    const postIds = Array.from(new Set([...(posts || []).map(post => post.id), ...(pinnedRow ? [pinnedRow.id] : [])]));
    const {
      reactionCounts,
      myReactions,
      reactionSampleNames,
      commentCounts,
      quoteCounts,
      polls,
      snippets,
    } = await loadCommunityEngagementMaps(postIds, req.user.id, { includeQuoteCounts: includeQuote, context: 'GET /api/community/feed' });

    // Mode profil saja: balasan sudah ikut terkirim (lihat buildPostsQuery di
    // atas), tapi klien butuh siapa penulis induknya untuk baris "Membalas ke
    // @slug". Satu query .in('id', parentIds) untuk semua induk sekaligus --
    // BUKAN satu query per item -- lalu dipetakan ke parent_author per post.
    // Mode linimasa tidak pernah punya balasan (difilter di buildPostsQuery),
    // jadi query ini sengaja dilewati di sana. includeThread=false juga
    // melewatinya (posts pra-migrasi tidak punya parent_post_id di select
    // sama sekali, jadi parentIds selalu kosong -- tapi digerbangi eksplisit
    // di sini juga, bukan cuma mengandalkan itu sebagai efek samping).
    //
    // deleted_at ikut diambil (BUKAN difilter) supaya baris "Membalas ke @X"
    // bisa membedakan induk yang sudah dihapus dari induk yang benar-benar
    // tidak ada -- pola yang sama dengan fetchCommunityAncestorRow di
    // GET /posts/:id. Tanpa ini klien mengklik baris konteks lalu 404 di
    // GET /posts/:id (yang menyaring deleted_at is null), padahal halaman
    // thread untuk kasus identik sudah punya placeholder "Kiriman sudah
    // dihapus".
    const parentAuthorById = new Map();
    if (profileMember && includeThread) {
      const parentIds = [...new Set((posts || []).map(post => post.parent_post_id).filter(Boolean))];
      if (parentIds.length > 0) {
        const { data: parentRows, error: parentAuthorError } = await supabase
          .from('community_posts')
          .select('id, deleted_at, agent:agents!community_posts_agent_id_fkey(name, slug)')
          .in('id', parentIds);
        if (parentAuthorError) throw parentAuthorError;
        for (const row of parentRows || []) {
          if (row.deleted_at) {
            parentAuthorById.set(row.id, { available: false });
            continue;
          }
          const parentAgent = Array.isArray(row.agent) ? row.agent[0] : row.agent;
          parentAuthorById.set(row.id, { available: true, name: parentAgent?.name ?? null, slug: parentAgent?.slug ?? null });
        }
      }
    }

    const quotedIds = includeQuote
      ? [...new Set([
          ...(posts || []).map(post => post.quoted_post_id).filter(Boolean),
          ...(pinnedRow?.quoted_post_id ? [pinnedRow.quoted_post_id] : []),
        ])]
      : [];
    let quotedRows = [];
    if (quotedIds.length > 0) {
      const buildQuotedQuery = withMedia => supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${withMedia ? 'media, ' : ''}is_system, created_at, deleted_at, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .in('id', quotedIds);
      let { data: rows, error: quotedError } = await buildQuotedQuery(true);
      if (isCommunityMediaSchemaMissing(quotedError)) {
        ({ data: rows, error: quotedError } = await buildQuotedQuery(false));
      }
      if (quotedError) throw quotedError;
      quotedRows = rows || [];
    }
    const quotedById = new Map(quotedRows.map(row => [row.id, row]));

    // Jumlah segmen lanjutan tiap utas. Pola yang sama dengan quoteCounts di
    // atas: satu query untuk seluruh halaman, dihitung di aplikasi — tanpa N+1
    // dan tanpa kolom denormalisasi yang bisa basi. is_reply=false wajib:
    // balasan (community_post_comments lama, sekarang community_posts dengan
    // is_reply=true) JUGA punya root_post_id terisi, jadi tanpa filter ini
    // thread_count ikut menghitung balasan sebagai segmen utas.
    const threadCounts = new Map(postIds.map(postId => [postId, 0]));
    if (includeThread && postIds.length > 0) {
      const { data: threadRows, error: threadCountError } = await supabase
        .from('community_posts')
        .select('root_post_id')
        .in('root_post_id', postIds)
        .eq('is_reply', false)
        .is('deleted_at', null);
      // Pra-migrasi is_reply (jendela sempit: root_post_id sudah ada dari
      // Fitur A, is_reply belum) -- degradasi ke 0 untuk semua, sama seperti
      // degradasi thread_count lain di endpoint ini kalau kolom utas hilang
      // total. Tidak retry tanpa filter is_reply supaya tidak diam-diam
      // menghitung balasan sebagai segmen (mencemari lagi apa yang task ini
      // perbaiki).
      if (threadCountError && !isCommunityThreadSchemaMissing(threadCountError)) {
        throw threadCountError;
      }
      for (const row of threadRows || []) {
        if (threadCounts.has(row.root_post_id)) {
          threadCounts.set(row.root_post_id, threadCounts.get(row.root_post_id) + 1);
        }
      }
    }

    const toFeedPayload = post => {
      const media = normalizeStoredCommunityMedia(post.media, post.photo_url);
      return {
        id: post.id,
        body: post.body,
        photo_url: post.photo_url || media.find(item => item.type === 'image')?.url || null,
        media,
        is_system: post.is_system,
        created_at: post.created_at,
        edited_at: post.edited_at ?? null,
        pinned_at: post.pinned_at ?? null,
        is_reply: post.is_reply === true,
        author: communityAuthorProfile(post.agent),
        reactions: reactionCounts.get(post.id),
        my_reaction: myReactions.get(post.id),
        reaction_sample_name: reactionSampleNames.get(post.id),
        comment_count: commentCounts.get(post.id) || 0,
        quote_count: quoteCounts.get(post.id) || 0,
        thread_count: threadCounts.get(post.id) ? threadCounts.get(post.id) + 1 : 0,
        quoted_post: includeQuote && post.quoted_post_id
          ? communityQuotedPostPayload(quotedById.get(post.quoted_post_id))
          : null,
        link_preview: includeLinkPreview ? communityLinkPreviewPayload(post, snippets.has(post.id)) : null,
        poll: polls.get(post.id) || null,
        snippet: snippets.get(post.id) || null,
        is_own: post.agent_id === agent.id,
        // parent_post_id/parent_author cuma berarti di mode profil (linimasa
        // selalu parent_post_id NULL, sudah disaring di buildPostsQuery).
        // parent_author absen lewat spread kosong (bukan `null`) saat kiriman
        // tidak punya induk, sama seperti pola di fitur balasan lain.
        parent_post_id: includeThread ? (post.parent_post_id || null) : null,
        ...(profileMember && includeThread && post.parent_post_id
          ? { parent_author: parentAuthorById.get(post.parent_post_id) || null }
          : {}),
      };
    };
    const data = (posts || []).map(toFeedPayload);
    const nextCursor = data.length < 20
      ? null
      : `${data[data.length - 1].created_at}|${data[data.length - 1].id}`;

    res.json({
      success: true,
      data,
      next_cursor: nextCursor,
      ...(!before && !profileMember ? { pinned: pinnedRow ? toFeedPayload(pinnedRow) : null } : {}),
    });
  } catch (err) {
    console.error('[community] feed error:', err);
    res.status(500).json({ error: 'Gagal memuat feed Teras' });
  }
});

app.get('/api/community/posts/:id', dbLoadShedGuard, authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    // Accept the full UUID (in-app deep-links) or an 8-hex share code from a
    // "/teras/<code>" link. A share code is a UUID prefix, resolved by range.
    const rawId = req.params.id;
    const byFullId = isCommunityUuid(rawId);
    const byShortCode = !byFullId && isTerasShortCode(rawId);
    if (!byFullId && !byShortCode) {
      return res.status(404).json({ error: 'Kiriman tidak ditemukan' });
    }
    const applyPostIdFilter = (query) => {
      if (byFullId) return query.eq('id', rawId);
      const { lo, hi } = communityShortCodeBounds(rawId);
      // Oldest match wins on the (negligible) chance two ids share a prefix.
      return query.gte('id', lo).lte('id', hi).order('created_at', { ascending: true }).limit(1);
    };

    const buildPostQuery = (includeMedia, includeQuote, includeLinkPreview, includeThread, includeEdited, includePin) => applyPostIdFilter(
      supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${includeMedia ? 'media, ' : ''}${includeQuote ? 'quoted_post_id, ' : ''}${includeLinkPreview ? 'link_preview, ' : ''}${includeThread ? 'parent_post_id, root_post_id, is_reply, ' : ''}${includeEdited ? 'edited_at, ' : ''}${includePin ? 'pinned_at, ' : ''}is_system, created_at, agent_id, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .is('deleted_at', null),
    ).maybeSingle();

    let includeMedia = true;
    let includeQuote = true;
    let includeLinkPreview = true;
    let includeThread = true;
    let includeEdited = true;
    let includePin = true;
    let post = null;
    let postError = null;
    // 6 kolom yang bisa mundur (media, quote, link preview, thread, edited, pin) ->
    // hingga 6 percobaan gagal + 1 percobaan sukses = 7, sama seperti buildPostsQuery.
    for (let attempt = 0; attempt < 7; attempt += 1) {
      ({ data: post, error: postError } = await buildPostQuery(includeMedia, includeQuote, includeLinkPreview, includeThread, includeEdited, includePin));
      if (includeMedia && isCommunityMediaSchemaMissing(postError)) {
        includeMedia = false;
        continue;
      }
      if (includeQuote && isCommunityQuoteSchemaMissing(postError)) {
        includeQuote = false;
        continue;
      }
      if (includeLinkPreview && isCommunityLinkPreviewSchemaMissing(postError)) {
        includeLinkPreview = false;
        continue;
      }
      if (includeThread && isCommunityThreadSchemaMissing(postError)) {
        includeThread = false;
        continue;
      }
      if (includeEdited && isCommunityEditSchemaMissing(postError)) {
        includeEdited = false;
        continue;
      }
      if (includePin && isCommunityPinSchemaMissing(postError)) {
        includePin = false;
        continue;
      }
      break;
    }
    if (postError) throw postError;
    if (!post) return res.status(404).json({ error: 'Kiriman tidak ditemukan' });

    // Rantai leluhur menelusuri parent_post_id ke atas, hop demi hop, lewat
    // primary key -- BUKAN mengambil seluruh thread (`.or('id.eq...,root_
    // post_id.eq...')`, dipakai blok `thread` di bawah). Thread ramai bisa
    // punya >500 baris di bawah satu akar, dan PostgREST memotong hasil di
    // max_rows sisi server tanpa pemberitahuan; baris yang tersisa acak, jadi
    // leluhur yang masih hidup bisa salah dirender sebagai "dihapus", atau
    // kalau baris kiriman itu sendiri yang hilang, ancestors diam-diam jadi
    // [] seolah ia kiriman induk. Rantai leluhur sungguhan panjangnya sama
    // dengan kedalaman thread (praktis 1-3), jadi penelusuran per-hop selalu
    // eksak dan murah.
    const communityAncestorRowSelect = 'id, body, created_at, deleted_at, parent_post_id, agent:agents!community_posts_agent_id_fkey(name, slug, photo)';
    const fetchCommunityAncestorRow = parentId => supabase
      .from('community_posts')
      .select(communityAncestorRowSelect)
      .eq('id', parentId)
      .maybeSingle();
    const needsAncestors = includeThread && !!post.parent_post_id;

    const [reactionResult, commentResult, firstAncestorResult, detailPolls, detailSnippets] = await Promise.all([
      supabase
        .from('community_post_reactions')
        .select('post_id, reaction, agent_id, agent:agents(name)')
        .eq('post_id', post.id),
      // Balasan hidup di community_posts dengan is_reply=true (bukan lagi
      // community_post_comments) — head-count: satu kiriman per request, jadi
      // count-exact/head aman dan sekaligus lolos dari batas max_rows
      // PostgREST (beda dengan feed/thread, lihat loadCommunityEngagementMaps).
      // is_reply=true wajib supaya segmen lanjutan utas (parent_post_id juga
      // terisi, is_reply=false) tidak ikut terhitung sebagai komentar.
      supabase
        .from('community_posts')
        .select('id', { count: 'exact', head: true })
        .eq('parent_post_id', post.id)
        .eq('is_reply', true)
        .is('deleted_at', null),
      // Hop pertama (induk langsung) numpang di Promise.all yang sama request
      // ini sudah menembakkan; hop-hop berikutnya baru bisa jalan setelah id
      // induk-dari-induk diketahui, jadi lanjutannya tetap berurutan di bawah.
      needsAncestors ? fetchCommunityAncestorRow(post.parent_post_id) : Promise.resolve({ data: null, error: null }),
      loadCommunityPollMaps([post.id], req.user.id, 'GET /api/community/posts/:id'),
      // Lampiran teks milik segmen PERTAMA saja, jadi cukup kiriman ini —
      // segmen di array `thread` di bawah tidak membawa `snippet`, sama
      // seperti mereka tidak membawa `quoted_post`.
      loadCommunitySnippetMaps([post.id]),
    ]);
    if (reactionResult.error) throw reactionResult.error;
    // Pra-migrasi (is_reply/parent_post_id belum ada): degradasi ke 0, bukan
    // 500 — lihat pemakaian commentResult.count di payload di bawah.
    if (commentResult.error && !isCommunityThreadSchemaMissing(commentResult.error)) throw commentResult.error;

    let ancestors = [];
    if (needsAncestors) {
      if (firstAncestorResult.error) throw firstAncestorResult.error;
      const rows = [post];
      const pushAncestorRow = row => rows.push(row ? { ...row, author: communityAuthorProfile(row.agent) } : row);

      let ancestorRow = firstAncestorResult.data;
      let hops = 1;
      pushAncestorRow(ancestorRow);
      let nextParentId = ancestorRow?.parent_post_id || null;
      while (nextParentId) {
        if (hops >= COMMUNITY_MAX_ANCESTOR_HOPS) {
          console.warn(`[community] ancestor chain for post ${post.id} hit the ${COMMUNITY_MAX_ANCESTOR_HOPS}-hop limit; truncating`);
          break;
        }
        hops += 1;
        const { data, error } = await fetchCommunityAncestorRow(nextParentId);
        if (error) throw error;
        ancestorRow = data;
        pushAncestorRow(ancestorRow);
        nextParentId = ancestorRow?.parent_post_id || null;
      }
      ancestors = buildAncestorChain(rows, post.id);
    }

    const reactions = { suka: 0, selamat: 0, aamiin: 0 };
    let myReaction = null;
    let reactionSampleName = null;
    for (const row of reactionResult.data || []) {
      if (!COMMUNITY_REACTION_TYPES.includes(row.reaction)) continue;
      reactions[row.reaction] += 1;
      if (row.agent_id === req.user.id) {
        myReaction = row.reaction;
      } else if (!reactionSampleName) {
        const sampleName = communityAuthorProfile(row.agent).name;
        if (sampleName) reactionSampleName = sampleName;
      }
    }

    let quotedPost = null;
    if (includeQuote && post.quoted_post_id) {
      const buildQuotedQuery = withMedia => supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${withMedia ? 'media, ' : ''}is_system, created_at, deleted_at, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .eq('id', post.quoted_post_id)
        .maybeSingle();
      let { data: quotedRow, error: quotedError } = await buildQuotedQuery(true);
      if (isCommunityMediaSchemaMissing(quotedError)) {
        ({ data: quotedRow, error: quotedError } = await buildQuotedQuery(false));
      }
      if (quotedError) throw quotedError;
      quotedPost = communityQuotedPostPayload(quotedRow);
    }

    let quoteCount = 0;
    if (includeQuote) {
      const { data: quoteRows, error: quoteCountError } = await supabase
        .from('community_posts')
        .select('quoted_post_id')
        .eq('quoted_post_id', post.id)
        .is('deleted_at', null);
      if (quoteCountError) throw quoteCountError;
      quoteCount = (quoteRows || []).length;
    }

    // Membuka segmen mana pun memberi rantai yang sama. `root_post_id` segmen
    // pertama bernilai NULL, jadi akarnya adalah dirinya sendiri. Kalau
    // buildPostQuery di atas sudah menyimpulkan kolom utas tidak ada
    // (includeThread === false), lewati saja — query ini pasti gagal dengan
    // alasan yang sama, jadi tidak perlu diulang.
    let thread = null;
    if (includeThread) {
      const threadRootId = post.root_post_id || post.id;
      // is_reply=false wajib: `.or('id.eq...,root_post_id.eq...')` juga
      // menarik balasan (is_reply=true) yang berbagi root_post_id yang sama
      // dengan segmen utas — tanpa filter ini, array `thread` tercemar
      // balasan. Akar sendiri (is_reply=false) tetap ikut lewat `id.eq...`.
      const { data: threadRows, error: threadError } = await supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${includeMedia ? 'media, ' : ''}${includeEdited ? 'edited_at, ' : ''}is_system, created_at, agent_id, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .or(`id.eq.${threadRootId},root_post_id.eq.${threadRootId}`)
        .eq('is_reply', false)
        .is('deleted_at', null)
        .order('created_at', { ascending: true });
      // Pra-migrasi is_reply (root_post_id sudah ada dari Fitur A, is_reply
      // belum) -- sama seperti thread_count di feed: degradasi ke null/tanpa
      // segmen tambahan, jangan retry tanpa filter is_reply (itu akan
      // mencemari `thread` lagi dengan balasan).
      if (threadError && !isCommunityThreadSchemaMissing(threadError)) {
        throw threadError;
      }
      if ((threadRows || []).length > 1) {
        // Setiap segmen butuh baris reaksinya sendiri (TerasCard dipakai ulang
        // per segmen) — hitung lewat helper yang sama dengan linimasa, satu
        // set query batched untuk seluruh rantai (maksimal 10 baris), bukan
        // satu query per segmen.
        const threadIds = threadRows.map(row => row.id);
        const {
          reactionCounts: threadReactionCounts,
          myReactions: threadMyReactions,
          reactionSampleNames: threadReactionSampleNames,
          commentCounts: threadCommentCounts,
          quoteCounts: threadQuoteCounts,
          polls: threadPolls,
        } = await loadCommunityEngagementMaps(threadIds, req.user.id, { includeQuoteCounts: includeQuote, context: 'GET /api/community/posts/:id thread' });
        thread = threadRows.map(row => {
          const rowMedia = normalizeStoredCommunityMedia(row.media, row.photo_url);
          return {
            id: row.id,
            body: row.body,
            photo_url: row.photo_url || rowMedia.find(item => item.type === 'image')?.url || null,
            media: rowMedia,
            is_system: row.is_system,
            created_at: row.created_at,
            edited_at: row.edited_at ?? null,
            is_reply: false,
            agent_id: row.agent_id,
            author: communityAuthorProfile(row.agent),
            reactions: threadReactionCounts.get(row.id),
            my_reaction: threadMyReactions.get(row.id),
            reaction_sample_name: threadReactionSampleNames.get(row.id),
            comment_count: threadCommentCounts.get(row.id) || 0,
            quote_count: threadQuoteCounts.get(row.id) || 0,
            poll: threadPolls.get(row.id) || null,
            is_own: row.agent_id === agent.id,
          };
        });
      }
    }

    const media = normalizeStoredCommunityMedia(post.media, post.photo_url);
    res.json({
      success: true,
      data: {
        id: post.id,
        body: post.body,
        photo_url: post.photo_url || media.find(item => item.type === 'image')?.url || null,
        media,
        is_system: post.is_system,
        created_at: post.created_at,
        edited_at: post.edited_at ?? null,
        pinned_at: post.pinned_at ?? null,
        is_reply: post.is_reply === true,
        author: communityAuthorProfile(post.agent),
        reactions,
        my_reaction: myReaction,
        reaction_sample_name: reactionSampleName,
        comment_count: commentResult.error ? 0 : (commentResult.count || 0),
        quote_count: quoteCount,
        quoted_post: post.quoted_post_id ? quotedPost : null,
        link_preview: includeLinkPreview ? communityLinkPreviewPayload(post, detailSnippets.has(post.id)) : null,
        poll: detailPolls.get(post.id) || null,
        snippet: detailSnippets.get(post.id) || null,
        thread,
        parent_post_id: includeThread ? (post.parent_post_id || null) : null,
        ancestors,
        is_own: post.agent_id === agent.id,
      },
    });
  } catch (err) {
    console.error('[community] post detail error:', err);
    res.status(500).json({ error: 'Gagal memuat kiriman' });
  }
});

/**
 * Berapa kali agent sudah broadcast hari ini (kalender WIB). Kiriman yang sudah
 * dihapus IKUT dihitung — kalau tidak, hapus-lalu-kirim-lagi jadi jatah tak
 * terbatas. Kolom yang belum dimigrasi diperlakukan sebagai "belum pernah",
 * jadi endpoint ini tidak pernah menggagalkan komposer.
 *
 * `excludePostId`: retry idempoten mengirim ulang POST dengan `client_id`
 * yang sama (mis. respons pertama hilang di jaringan). Kirimannya sendiri
 * sudah tersimpan dari percobaan pertama, jadi kecualikan dari hitungan di
 * sini — kalau tidak, retry menghitung kirimannya sendiri lalu ditolak 403
 * padahal sudah live. Parameter terpisah (bukan ditambahkan ke signature
 * loadBroadcastQuota) supaya endpoint GET /broadcast-quota, yang tidak
 * punya konsep client_id, tetap memanggil loadBroadcastQuota(agent) apa
 * adanya dan tidak pernah mengecualikan apa pun.
 */
async function loadBroadcastQuota(agent, { excludePostId = null } = {}) {
  const dayStart = jakartaDayStartIso(new Date());
  let usedToday = 0;
  if (agent.role !== 'admin') {
    let query = supabase
      .from('community_posts')
      .select('id', { count: 'exact', head: true })
      .eq('agent_id', agent.id)
      .eq('mentions_everyone', true)
      .gte('created_at', dayStart);
    if (excludePostId) query = query.neq('id', excludePostId);
    const { count, error } = await query;
    if (error && !isCommunityBroadcastSchemaMissing(error)) throw error;
    usedToday = error ? 0 : (count || 0);
  }
  const quota = resolveBroadcastQuota({ role: agent.role, usedToday });
  return {
    unlimited: quota.unlimited,
    allowed: quota.allowed,
    remaining: quota.unlimited ? null : quota.remaining,
    used_today: usedToday,
    // Jatah berikutnya terbuka pada tengah malam WIB setelah dayStart.
    resets_at: new Date(new Date(dayStart).getTime() + 24 * 60 * 60 * 1000).toISOString(),
  };
}

app.get('/api/community/broadcast-quota', dbLoadShedGuard, authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;
    const quota = await loadBroadcastQuota(agent);
    res.json({ success: true, data: quota });
  } catch (err) {
    console.error('[community] broadcast quota error:', err);
    res.status(500).json({ error: 'Gagal memeriksa jatah @semua' });
  }
});

// Satu insert kiriman, lengkap dengan degradasi skema yang sudah lama ada di
// endpoint ini (kolom media, kolom `type` usang, kolom quote, kolom
// mentions_everyone, link preview) dan penanganan 23505 idempoten untuk retry
// ber-client_id yang sama. Dipanggil berulang oleh pembuat utas, jadi ia tidak
// boleh menyentuh `res` maupun melempar — semua kondisi yang tadinya membalas
// langsung (503) sekarang dikembalikan sebagai flag agar pemanggil yang
// memutuskan responsnya.
async function createCommunityPostRow({
  clientId,
  agentId,
  body,
  media,
  photoUrl,
  quotedPostId = null,
  mentionsEveryone = false,
  linkPreview = null,
  parentPostId = null,
  rootPostId = null,
}) {
  const basePostPayload = {
    ...(clientId ? { id: clientId } : {}),
    agent_id: agentId,
    body,
    photo_url: photoUrl,
    is_system: false,
    ...(quotedPostId ? { quoted_post_id: quotedPostId } : {}),
    ...(mentionsEveryone ? { mentions_everyone: true } : {}),
  };
  const isThreadSegment = !!parentPostId;
  // Kiriman dengan >1 media atau video WAJIB kolom media — mundur diam-diam
  // akan membuang lampiran, jadi ini menolak jelas alih-alih itu (perilaku
  // lama endpoint ini, dipertahankan di sini).
  const requiresMediaSchema = media.length > 1 || media.some(item => item.type === 'video');

  let includeMediaColumn = true;
  let includeObsoleteType = false;
  let includeLinkPreview = !!linkPreview;
  // Kiriman biasa tidak butuh kolom utas sama sekali, jadi ia boleh mundur
  // tanpa kolom itu. Segmen lanjutan tidak boleh — utas separuh jadi lebih
  // buruk daripada penolakan yang jelas.
  let includeThread = isThreadSegment || !!rootPostId;
  let createdPost = null;
  let insertError = null;

  for (let attempt = 0; attempt < 5; attempt += 1) {
    const postPayload = {
      ...basePostPayload,
      ...(includeMediaColumn ? { media } : {}),
      ...(includeObsoleteType ? { type: media.length > 0 ? 'foto' : 'tips' } : {}),
      ...(includeLinkPreview ? { link_preview: linkPreview } : {}),
      ...(includeThread ? { parent_post_id: parentPostId, root_post_id: rootPostId } : {}),
    };
    const insertResult = await supabase
      .from('community_posts')
      .insert(postPayload)
      .select(`id, body, photo_url, ${includeMediaColumn ? 'media, ' : ''}is_system, created_at`)
      .single();
    createdPost = insertResult.data;
    insertError = insertResult.error;
    if (!insertError) break;
    if (includeMediaColumn && isCommunityMediaSchemaMissing(insertError)) {
      if (requiresMediaSchema) {
        return { post: null, error: insertError, threadSchemaMissing: false, mediaSchemaRequiredMissing: true };
      }
      includeMediaColumn = false;
      continue;
    }
    if (quotedPostId && isCommunityQuoteSchemaMissing(insertError)) {
      return { post: null, error: insertError, threadSchemaMissing: false, quoteSchemaMissing: true };
    }
    if (mentionsEveryone && isCommunityBroadcastSchemaMissing(insertError)) {
      return { post: null, error: insertError, threadSchemaMissing: false, broadcastSchemaMissing: true };
    }
    if (includeLinkPreview && isCommunityLinkPreviewSchemaMissing(insertError)) {
      includeLinkPreview = false;
      continue;
    }
    if (includeThread && isCommunityThreadSchemaMissing(insertError)) {
      if (isThreadSegment) return { post: null, error: insertError, threadSchemaMissing: true };
      includeThread = false;
      continue;
    }
    // Compatibility for installations that already ran the pre-final Teras
    // draft, where `type` was NOT NULL. Keep that obsolete value server-side.
    if (
      !includeObsoleteType
      && insertError?.code === '23502'
      && /column "type"/i.test(insertError.message || '')
    ) {
      includeObsoleteType = true;
      continue;
    }
    break;
  }

  if (insertError?.code === '23505' && clientId) {
    const loadExistingPost = includeMedia => supabase
      .from('community_posts')
      .select(`id, body, photo_url, ${includeMedia ? 'media, ' : ''}is_system, created_at`)
      .eq('id', clientId)
      .eq('agent_id', agentId)
      .is('deleted_at', null)
      .maybeSingle();
    let { data: existingPost, error: existingError } = await loadExistingPost(true);
    if (isCommunityMediaSchemaMissing(existingError)) {
      ({ data: existingPost, error: existingError } = await loadExistingPost(false));
    }
    if (existingError) return { post: null, error: existingError, threadSchemaMissing: false };
    const existingMedia = normalizeStoredCommunityMedia(existingPost?.media, existingPost?.photo_url);
    if (
      existingPost
      && existingPost.body === body
      && existingPost.photo_url === photoUrl
      && communityMediaEquals(existingMedia, media)
    ) {
      // `reused`: baris ini sudah ada sebelum permintaan ini (retry idempoten).
      // Pembuat utas TIDAK boleh me-rollback baris seperti ini — ia bukan
      // miliknya untuk dihapus.
      return { post: existingPost, error: null, threadSchemaMissing: false, reused: true };
    }
    return { post: null, error: { code: 'DUPLICATE_CLIENT_ID' }, threadSchemaMissing: false };
  }

  return { post: createdPost, error: insertError, threadSchemaMissing: false };
}

// Limit 256kb (lampiran teks boleh 10.000 karakter, dan 96kb tidak cukup
// begitu body sebesar itu datang bersama segmen utas + metadata media).
// CATATAN: parser di baris ini TIDAK PERNAH tereksekusi — parser path-scoped
// di app.use('/api/community/posts', ...) sudah menghabiskan body lebih dulu.
// Angkanya disamakan supaya tidak ada dua angka yang saling bertentangan;
// yang benar-benar berlaku ada di sana (lihat komentarnya).
app.post('/api/community/posts', authMiddleware, express.json({ limit: '256kb' }), async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    const { segments: rawSegments, error: segmentError } = normalizeThreadSegments(req.body);
    if (segmentError) return res.status(400).json({ error: segmentError });

    // Polling ala Threads: milik utas (menempel pada segmen pertama), 2-4 opsi,
    // durasi dari daftar tetap (default 24 jam). Validasi bentuk di sini;
    // larangan gabung dengan media/quote menyusul setelah keduanya diketahui
    // di bawah.
    const {
      options: pollOptions,
      durationMs: pollDurationMs,
      error: pollInputError,
    } = normalizeCommunityPollInput(req.body?.poll);
    if (pollInputError) return res.status(400).json({ error: pollInputError });

    // Lampiran teks: juga milik utas (menempel pada segmen pertama). Body
    // dinormalisasi & dibatasi 10.000 karakter di helper; larangan gabung
    // dengan polling menyusul di bawah, setelah keduanya diketahui.
    const {
      snippet,
      error: snippetInputError,
    } = normalizeCommunitySnippetInput(req.body?.snippet);
    if (snippetInputError) return res.status(400).json({ error: snippetInputError });

    // Segmen pertama memegang identitas utas: quote, link preview, dan @semua
    // hanya dinilai dari sini.
    const body = rawSegments[0].body;
    const clientId = rawSegments[0].clientId || undefined;
    const isThread = rawSegments.length > 1;

    // Broadcast @semua: token dibaca dari body oleh server — klien tidak
    // dipercaya menandai kirimannya sendiri. Kuota diperiksa SEBELUM insert
    // supaya penolakan tidak meninggalkan kiriman setengah jadi.
    const mentionsEveryone = hasEveryoneMention(body);
    if (mentionsEveryone) {
      const quota = await loadBroadcastQuota(agent, { excludePostId: clientId || null });
      if (!quota.allowed) {
        return res.status(403).json({ error: 'Jatah @semua hari ini sudah dipakai. Coba lagi besok.' });
      }
    }

    const quotedPostIdRaw = req.body?.quoted_post_id;
    let quotedPostId = null;
    let quotedPostRow = null;
    if (quotedPostIdRaw !== undefined && quotedPostIdRaw !== null) {
      if (!isCommunityUuid(quotedPostIdRaw)) {
        return res.status(400).json({ error: 'Kiriman yang dikutip tidak valid' });
      }
      const buildQuotedQuery = includeMedia => supabase
        .from('community_posts')
        .select(`id, body, photo_url, ${includeMedia ? 'media, ' : ''}is_system, created_at, deleted_at, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
        .eq('id', quotedPostIdRaw)
        .maybeSingle();
      let { data: quotedRow, error: quotedError } = await buildQuotedQuery(true);
      if (isCommunityMediaSchemaMissing(quotedError)) {
        ({ data: quotedRow, error: quotedError } = await buildQuotedQuery(false));
      }
      if (quotedError) throw quotedError;
      if (!quotedRow || quotedRow.deleted_at) {
        return res.status(400).json({ error: 'Kiriman yang dikutip tidak ditemukan' });
      }
      quotedPostId = quotedPostIdRaw;
      quotedPostRow = quotedRow;
    }

    const mediaPrefixes = communityMediaPublicPrefixes();
    if (!mediaPrefixes.length) throw new Error('Public URL media Teras tidak tersedia');

    const segmentMedia = [];
    for (let i = 0; i < rawSegments.length; i += 1) {
      const segment = rawSegments[i];
      let segmentMediaList;
      if (segment.media !== undefined) {
        segmentMediaList = normalizeCommunityMediaInput(segment.media, mediaPrefixes, agent.slug);
        if (!segmentMediaList) {
          return res.status(400).json({
            error: isThread
              ? `Media kiriman ke-${i + 1} tidak valid atau melebihi ${COMMUNITY_MAX_MEDIA_ITEMS} item`
              : `Media kiriman tidak valid atau melebihi ${COMMUNITY_MAX_MEDIA_ITEMS} item`,
          });
        }
      } else if (segment.photoUrl !== undefined) {
        if (typeof segment.photoUrl !== 'string') {
          return res.status(400).json({ error: 'URL foto tidak valid' });
        }
        segmentMediaList = normalizeCommunityMediaInput(
          [{ type: 'image', url: segment.photoUrl }],
          mediaPrefixes,
          agent.slug,
        );
        if (!segmentMediaList) return res.status(400).json({ error: 'URL foto tidak valid' });
      } else {
        segmentMediaList = [];
      }
      segmentMedia.push(segmentMediaList);
    }
    const media = segmentMedia[0];
    const photoUrl = media.find(item => item.type === 'image')?.url || null;

    // Parity Threads: poll berdiri sendiri di segmen pertama — tidak digabung
    // media segmen itu ataupun kutipan. (Segmen lanjutan boleh tetap bermedia.)
    if (pollOptions && (media.length > 0 || quotedPostId)) {
      return res.status(400).json({ error: 'Polling tidak bisa digabung dengan media atau kutipan' });
    }

    // Lampiran + polling sama-sama merebut blok utama di bawah teks kiriman.
    // Media dan kutipan SENGAJA tetap boleh berdampingan dengan lampiran —
    // kartu cuplikan hidup berdampingan dengan keduanya, tidak seperti poll.
    if (snippet && pollOptions) {
      return res.status(400).json({ error: 'Lampiran teks tidak bisa digabung dengan polling' });
    }

    // Link preview: hanya bila TIDAK ada media, quote, & lampiran (prioritas).
    let linkPreview = null;
    if (media.length === 0 && !quotedPostId && !snippet && req.body?.link_preview != null) {
      const candidate = sanitizeLinkPreview(req.body.link_preview);
      // URL preview wajib benar-benar muncul di body teks.
      if (candidate && body.includes(candidate.url)) {
        linkPreview = candidate;
      }
    }

    const chain = buildThreadChain(rawSegments);
    const segmentPostIds = [];
    // Hanya baris yang BENAR-BENAR dibuat permintaan ini yang boleh di-rollback;
    // baris hasil retry idempoten sudah ada sebelumnya.
    const rollbackIds = [];
    let createdPost = null;
    let failure = null;
    // A retried POST (same client_id, e.g. a client-side timeout retry after
    // the first attempt actually succeeded) surfaces as `reused` on the root
    // segment (i === 0) and is treated as a success rather than an error. It
    // must NOT be treated as a fresh post for side effects:
    // recordCommunityMentions self-guards via the community_mentions table,
    // but the broadcast fan-out below has no such table to dedupe against,
    // so it is gated on this flag instead.
    let isFreshPostInsert = true;

    for (let i = 0; i < chain.length; i += 1) {
      const link = chain[i];
      const segmentMediaList = segmentMedia[i];
      const {
        post,
        error,
        reused,
        threadSchemaMissing,
        quoteSchemaMissing,
        broadcastSchemaMissing,
        mediaSchemaRequiredMissing,
      } = await createCommunityPostRow({
        clientId: link.clientId || undefined,
        agentId: agent.id,
        body: link.body,
        media: segmentMediaList,
        photoUrl: segmentMediaList.find(item => item.type === 'image')?.url || null,
        // Kutipan, link preview, dan @semua adalah milik utas, bukan segmen.
        quotedPostId: i === 0 ? quotedPostId : null,
        mentionsEveryone: i === 0 ? mentionsEveryone : false,
        linkPreview: i === 0 ? linkPreview : null,
        parentPostId: link.parentPostId,
        rootPostId: link.rootPostId,
      });
      if (error) {
        failure = {
          error,
          threadSchemaMissing,
          quoteSchemaMissing,
          broadcastSchemaMissing,
          mediaSchemaRequiredMissing,
        };
        break;
      }
      if (!post) {
        failure = { error: new Error('Kiriman tidak dikembalikan setelah insert') };
        break;
      }
      segmentPostIds.push(post.id);
      if (!reused) {
        rollbackIds.push(post.id);
      } else if (i === 0) {
        isFreshPostInsert = false;
      }
      if (i === 0) createdPost = post;
    }

    if (failure) {
      // Semua-atau-tidak-sama-sekali. Aman dihapus permanen: utas ini berumur
      // detik, belum bisa direaksi atau dikomentari siapa pun.
      if (rollbackIds.length > 0) {
        const { error: rollbackError } = await supabase
          .from('community_posts')
          .delete()
          .in('id', rollbackIds)
          // Pertahanan berlapis pada penghapusan permanen: lingkupi pada pemilik,
          // agar tidak ada risiko menghapus baris agen lain jika invariant berubah.
          .eq('agent_id', agent.id);
        if (rollbackError) {
          // Satu-satunya jalan menuju keadaan tak konsisten. Harus berisik.
          console.error(
            '[community] ROLLBACK UTAS GAGAL — baris yatim perlu dibersihkan manual:',
            rollbackIds.join(', '),
            rollbackError.message,
          );
        }
      }
      // Urutan cabang 503/409 dipertahankan persis seperti sebelum utas ada.
      if (failure.mediaSchemaRequiredMissing) {
        return res.status(503).json({ error: 'Migrasi media Teras belum diterapkan' });
      }
      if (failure.quoteSchemaMissing) {
        return res.status(503).json({ error: 'Migrasi quote Teras belum diterapkan' });
      }
      if (failure.broadcastSchemaMissing) {
        return res.status(503).json({ error: COMMUNITY_BROADCAST_MIGRATION_ERROR });
      }
      // Segmen pertama tidak pernah menyertakan kolom utas, jadi flag ini baru
      // muncul di segmen ke-2 — akar sudah terlanjur tersimpan dan sudah
      // di-rollback di atas.
      if (failure.threadSchemaMissing) {
        return res.status(503).json({ error: 'Migrasi utas Teras belum diterapkan' });
      }
      if (failure.error?.code === 'DUPLICATE_CLIENT_ID') {
        return res.status(409).json({ error: 'ID kiriman sudah digunakan' });
      }
      throw failure.error;
    }

    // Poll disimpan SETELAH seluruh rantai kiriman sukses; gagal -> rollback
    // rantai yang baru dibuat (all-or-nothing yang sama dengan antar-segmen —
    // kiriman "Pilih mana?" tanpa poll-nya lebih buruk daripada penolakan
    // jelas). Retry idempoten (reused/23505) mengambil baris poll yang sudah
    // ada dari percobaan pertama, bukan insert ulang.
    let createdPollPayload = null;
    if (pollOptions && createdPost) {
      const loadExistingPoll = () => supabase
        .from('community_polls')
        .select('post_id, options, ends_at')
        .eq('post_id', createdPost.id)
        .maybeSingle();
      let pollRow = null;
      let pollFailure = null;
      if (isFreshPostInsert) {
        const { data: insertedPoll, error: pollInsertError } = await supabase
          .from('community_polls')
          .insert({
            post_id: createdPost.id,
            options: pollOptions,
            ends_at: new Date(Date.now() + pollDurationMs).toISOString(),
          })
          .select('post_id, options, ends_at')
          .single();
        if (!pollInsertError) {
          pollRow = insertedPoll;
        } else if (pollInsertError.code === '23505') {
          ({ data: pollRow } = await loadExistingPoll());
        } else {
          pollFailure = pollInsertError;
        }
      } else {
        const { data: existingPoll, error: existingPollError } = await loadExistingPoll();
        if (existingPollError && !isCommunityPollSchemaMissing(existingPollError)) {
          pollFailure = existingPollError;
        }
        pollRow = existingPoll || null;
      }
      if (pollFailure) {
        if (rollbackIds.length > 0) {
          const { error: rollbackError } = await supabase
            .from('community_posts')
            .delete()
            .in('id', rollbackIds)
            .eq('agent_id', agent.id);
          if (rollbackError) {
            console.error(
              '[community] ROLLBACK UTAS (poll) GAGAL — baris yatim perlu dibersihkan manual:',
              rollbackIds.join(', '),
              rollbackError.message,
            );
          }
        }
        if (isCommunityPollSchemaMissing(pollFailure)) {
          return res.status(503).json({ error: 'Migrasi polling Teras belum diterapkan' });
        }
        throw pollFailure;
      }
      createdPollPayload = pollRow ? communityPollPayload(pollRow, [], agent.id) : null;
    }

    // Lampiran teks disimpan SETELAH seluruh rantai kiriman sukses dan SETELAH
    // blok poll — all-or-nothing yang sama persis: kiriman yang kehilangan
    // lampirannya (teks panjang yang justru jadi isi utamanya) lebih buruk
    // daripada penolakan yang jelas. Retry idempoten (reused/23505) mengambil
    // baris lampiran yang sudah ada dari percobaan pertama, bukan insert ulang.
    //
    // `body` tidak ikut di-select balik: nilainya sudah ada di memori sebagai
    // `snippet.body`, dan respons kiriman baru pun hanya membawa kartu
    // cuplikan — sama seperti feed.
    let createdSnippetPayload = null;
    if (snippet && createdPost) {
      const loadExistingSnippet = () => supabase
        .from('community_post_snippets')
        .select('post_id, title, preview, char_count')
        .eq('post_id', createdPost.id)
        .maybeSingle();
      let snippetRow = null;
      let snippetFailure = null;
      if (isFreshPostInsert) {
        const { data: insertedSnippet, error: snippetInsertError } = await supabase
          .from('community_post_snippets')
          .insert({
            post_id: createdPost.id,
            title: snippet.title,
            body: snippet.body,
            preview: snippet.preview,
            char_count: snippet.charCount,
          })
          .select('post_id, title, preview, char_count')
          .single();
        if (!snippetInsertError) {
          snippetRow = insertedSnippet;
        } else if (snippetInsertError.code === '23505') {
          ({ data: snippetRow } = await loadExistingSnippet());
        } else {
          snippetFailure = snippetInsertError;
        }
      } else {
        const { data: existingSnippet, error: existingSnippetError } = await loadExistingSnippet();
        if (existingSnippetError && !isCommunitySnippetSchemaMissing(existingSnippetError)) {
          snippetFailure = existingSnippetError;
        }
        snippetRow = existingSnippet || null;
      }
      if (snippetFailure) {
        if (rollbackIds.length > 0) {
          const { error: rollbackError } = await supabase
            .from('community_posts')
            .delete()
            .in('id', rollbackIds)
            .eq('agent_id', agent.id);
          if (rollbackError) {
            console.error(
              '[community] ROLLBACK UTAS (lampiran) GAGAL — baris yatim perlu dibersihkan manual:',
              rollbackIds.join(', '),
              rollbackError.message,
            );
          }
        }
        if (isCommunitySnippetSchemaMissing(snippetFailure)) {
          return res.status(503).json({ error: 'Migrasi lampiran teks Teras belum diterapkan' });
        }
        throw snippetFailure;
      }
      createdSnippetPayload = snippetRow ? communitySnippetCardPayload(snippetRow) : null;
    }

    // Pill "kiriman baru" menghitung baris feed, dan feed hanya menampilkan
    // segmen pertama — jadi satu utas menaikkan head sekali.
    bumpCommunityFeedHead(createdPost);

    const mentionPushedAgentIds = await recordCommunityMentions({
      segments: chain.map((link, i) => ({
        postId: segmentPostIds[i],
        body: link.body,
      })),
      authorAgent: agent,
    });

    const data = {
      ...createdPost,
      photo_url: photoUrl,
      media,
      author: communityAuthorProfile(agent),
      reactions: { suka: 0, selamat: 0, aamiin: 0 },
      my_reaction: null,
      reaction_sample_name: null,
      comment_count: 0,
      quote_count: 0,
      quoted_post: quotedPostId ? communityQuotedPostPayload(quotedPostRow) : null,
      link_preview: linkPreview,
      poll: createdPollPayload,
      snippet: createdSnippetPayload,
      thread_count: chain.length > 1 ? chain.length : 0,
      is_own: true,
    };
    res.status(201).json({ success: true, data });

    // Fan-out runs after the author's response is sent: notifyCommunityBroadcastTelegram
    // sends sequentially (one fetch per recipient) to respect Telegram's rate limit, and
    // awaiting it here would hold the author's POST open for seconds on a large roster.
    // Not awaited — this is fire-and-forget background work on a long-lived server with
    // in-process cron jobs, so it is safe to let it continue after the response. The
    // function already catches its own errors internally and never throws; this .catch
    // is a defensive backstop only. A notification failure must never fail post creation.
    if (mentionsEveryone && isFreshPostInsert) {
      notifyCommunityBroadcastTelegram({
        post: createdPost,
        authorAgent: agent,
        excludeAgentIds: mentionPushedAgentIds,
      }).catch(err => console.error('[community] broadcast telegram fan-out error:', err));
    }
  } catch (err) {
    console.error('[community] create post error:', err);
    res.status(500).json({ error: 'Gagal membuat postingan' });
  }
});

app.post('/api/community/media', authMiddleware, prepareCommunityMediaUpload, parseCommunityMediaBody, async (req, res) => {
  try {
    const agent = req.communityAgent;
    const uploadId = req.communityUploadId;
    const mime = req.communityMediaMime;
    const mediaConfig = req.communityMediaConfig;

    const buffer = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
    if (!buffer.length || buffer.length > mediaConfig.maxBytes) {
      const maxSize = mediaConfig.type === 'image' ? '3MB' : '20MB';
      return res.status(400).json({ error: `Ukuran ${mediaConfig.type === 'image' ? 'gambar' : 'video'} maksimal ${maxSize}` });
    }
    if (!hasExpectedCommunityMediaSignature(buffer, mime)) {
      return res.status(400).json({ error: 'Isi file media tidak valid' });
    }
    if (['video/mp4', 'video/quicktime'].includes(mime)) {
      const rejectedCodec = findRejectedVideoCodec(buffer);
      if (rejectedCodec) return res.status(415).json({ error: rejectedCodec.message });
    }

    const storageMime = mediaConfig.storageMime || mime;
    const contentHash = crypto.createHash('sha256').update(buffer).digest('hex');
    const fileName = `community/${agent.slug}-${uploadId}-${contentHash}.${mediaConfig.ext}`;
    let publicUrl;
    if (getBunnyEnabled()) {
      // PUT is idempotent and the content hash is in the path, so a retried
      // upload of the same bytes simply overwrites the identical object.
      await bunnyUpload(fileName, buffer, storageMime);
      publicUrl = `https://${BUNNY_CDN_HOSTNAME}/${fileName}`;
    } else {
      console.warn('[community] Bunny CDN belum dikonfigurasi — media diunggah ke Supabase Storage');
      const { error: uploadError } = await supabase.storage
        .from('agent-photos')
        .upload(fileName, buffer, {
          contentType: storageMime,
          cacheControl: '31536000',
          upsert: false,
        });
      if (uploadError && !isCommunityStorageConflict(uploadError)) throw uploadError;
      const { data: urlData } = supabase.storage.from('agent-photos').getPublicUrl(fileName);
      publicUrl = urlData.publicUrl;
    }
    res.json({ success: true, url: publicUrl, type: mediaConfig.type });
  } catch (err) {
    console.error('[community] media upload error:', err);
    res.status(500).json({ error: 'Gagal mengunggah media' });
  }
});

app.post('/api/community/posts/:id/reaction', authMiddleware, express.json({ limit: '2kb' }), async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    const reaction = req.body?.reaction;
    if (reaction !== null && !COMMUNITY_REACTION_TYPES.includes(reaction)) {
      return res.status(400).json({ error: 'Reaksi tidak valid' });
    }
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }

    const post = await loadActiveCommunityPost(req.params.id);
    if (!post) return res.status(404).json({ error: 'Postingan tidak ditemukan' });

    await withCommunityReactionMutationLock(post.id, agent.id, async () => {
      if (reaction === null) {
        const { error } = await supabase
          .from('community_post_reactions')
          .delete()
          .eq('post_id', post.id)
          .eq('agent_id', agent.id);
        if (error) throw error;
        return;
      }

      let { error } = await supabase
        .from('community_post_reactions')
        .upsert({
          post_id: post.id,
          agent_id: agent.id,
          reaction,
          created_at: new Date().toISOString(),
        }, { onConflict: 'post_id,agent_id' });

      // Compatibility for the draft schema whose PK included `reaction`.
      // The process-local lock also keeps concurrent tabs on one server from
      // interleaving the temporary delete/insert fallback. The reconciliation
      // migration remains the cross-instance database-level guarantee.
      if (error?.code === '42P10') {
        const { error: deleteError } = await supabase
          .from('community_post_reactions')
          .delete()
          .eq('post_id', post.id)
          .eq('agent_id', agent.id);
        if (deleteError) throw deleteError;
        const fallbackResult = await supabase
          .from('community_post_reactions')
          .insert({
            post_id: post.id,
            agent_id: agent.id,
            reaction,
            created_at: new Date().toISOString(),
          });
        error = fallbackResult.error;
      }
      if (error) throw error;
    });

    res.json({ success: true });
  } catch (err) {
    console.error('[community] reaction error:', err);
    res.status(500).json({ error: 'Gagal memperbarui reaksi' });
  }
});

// Vote polling ala Threads: satu suara per agent per poll, boleh diganti
// selama polling terbuka (upsert), tidak bisa dicabut. Balasan membawa payload
// poll terbaru supaya klien bisa merekonsiliasi hitungan dari suara paralel.
app.post('/api/community/posts/:id/poll-vote', authMiddleware, express.json({ limit: '2kb' }), async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    const option = req.body?.option;
    if (!Number.isInteger(option) || option < 0) {
      return res.status(400).json({ error: 'Opsi polling tidak valid' });
    }
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }
    const post = await loadActiveCommunityPost(req.params.id);
    if (!post) return res.status(404).json({ error: 'Postingan tidak ditemukan' });

    const { data: pollRow, error: pollError } = await supabase
      .from('community_polls')
      .select('post_id, options, ends_at')
      .eq('post_id', post.id)
      .maybeSingle();
    if (pollError) {
      if (isCommunityPollSchemaMissing(pollError)) {
        return res.status(503).json({ error: 'Migrasi polling Teras belum diterapkan' });
      }
      throw pollError;
    }
    if (!pollRow) return res.status(404).json({ error: 'Polling tidak ditemukan' });
    const optionCount = Array.isArray(pollRow.options) ? pollRow.options.length : 0;
    if (option >= optionCount) {
      return res.status(400).json({ error: 'Opsi polling tidak valid' });
    }
    if (isCommunityPollClosed(pollRow.ends_at)) {
      return res.status(409).json({ error: 'Polling sudah berakhir' });
    }

    const { error: voteError } = await supabase
      .from('community_poll_votes')
      .upsert(
        { post_id: post.id, agent_id: agent.id, option_index: option },
        { onConflict: 'post_id,agent_id' },
      );
    if (voteError) throw voteError;

    const { data: voteRows, error: voteRowsError } = await supabase
      .from('community_poll_votes')
      .select('post_id, agent_id, option_index')
      .eq('post_id', post.id);
    if (voteRowsError) throw voteRowsError;

    res.json({ success: true, data: communityPollPayload(pollRow, voteRows || [], agent.id) });
  } catch (err) {
    console.error('[community] poll vote error:', err);
    res.status(500).json({ error: 'Gagal menyimpan suara polling' });
  }
});

// Daftar agent pemberi reaksi untuk satu kiriman — dipakai popover "tap lama"
// pada tombol Suka. Sengaja type-agnostic: enum DB masih memuat selamat/aamiin,
// jadi kita menampilkan SEMUA reaktor apa pun jenisnya, bukan hanya 'suka'.
app.get('/api/community/posts/:id/reactions', dbLoadShedGuard, authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }

    const { data, error } = await supabase
      .from('community_post_reactions')
      .select('agent_id, reaction, created_at, agent:agents(name, slug, photo)')
      .eq('post_id', req.params.id)
      .order('created_at', { ascending: true })
      .limit(100);
    if (error) throw error;

    const reactors = (data || [])
      .map(row => {
        const profile = communityAuthorProfile(row.agent);
        return { slug: profile.slug, name: profile.name, photo: profile.photo, reaction: row.reaction };
      })
      .filter(r => r.name);

    res.json({ success: true, data: reactors });
  } catch (err) {
    console.error('[community] reactions list error:', err);
    res.status(500).json({ error: 'Gagal memuat daftar reaksi' });
  }
});

// Daftar pemilih polling — dipakai popover "N suara" di PollBlock. Bentuknya
// meniru daftar reaktor di atas, plus teks opsi yang dipilih tiap agent
// (option_index diterjemahkan di sini supaya klien tidak perlu menjodohkan
// index sendiri terhadap poll yang mungkin sudah berubah di state-nya).
app.get('/api/community/posts/:id/poll-voters', dbLoadShedGuard, authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }

    const { data: pollRow, error: pollError } = await supabase
      .from('community_polls')
      .select('post_id, options')
      .eq('post_id', req.params.id)
      .maybeSingle();
    if (pollError) {
      if (isCommunityPollSchemaMissing(pollError)) {
        return res.status(503).json({ error: 'Migrasi polling Teras belum diterapkan' });
      }
      throw pollError;
    }
    if (!pollRow) return res.status(404).json({ error: 'Polling tidak ditemukan' });
    const optionTexts = Array.isArray(pollRow.options) ? pollRow.options : [];

    const { data, error } = await supabase
      .from('community_poll_votes')
      .select('agent_id, option_index, created_at, agent:agents(name, slug, photo)')
      .eq('post_id', req.params.id)
      .order('created_at', { ascending: true })
      .limit(200);
    if (error) throw error;

    const voters = (data || [])
      .map(row => {
        const profile = communityAuthorProfile(row.agent);
        return {
          slug: profile.slug,
          name: profile.name,
          photo: profile.photo,
          option_index: row.option_index,
          option_text: typeof optionTexts[row.option_index] === 'string' ? optionTexts[row.option_index] : null,
        };
      })
      .filter(voter => voter.name);

    res.json({ success: true, data: voters });
  } catch (err) {
    console.error('[community] poll voters list error:', err);
    res.status(500).json({ error: 'Gagal memuat daftar pemilih' });
  }
});

/**
 * Body penuh lampiran teks — satu-satunya jalan keluar kolom `body`. Feed dan
 * detail kiriman hanya membawa cuplikannya (lihat loadCommunitySnippetMaps),
 * jadi 10.000 karakter itu baru melintas kabel saat sheet fullscreen dibuka.
 *
 * TIDAK ada cek kepemilikan: Teras adalah feed antar-agent, dan lampiran sama
 * terbukanya dengan body kiriman yang sudah tampil di linimasa untuk semua
 * anggota. Gerbangnya requireCommunityAccess (boleh masuk Teras), bukan
 * kepemilikan kiriman.
 */
app.get('/api/community/posts/:id/snippet', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;
    if (!isCommunityUuid(req.params.id)) {
      return res.status(400).json({ error: 'Kiriman tidak valid' });
    }

    const { data: row, error } = await supabase
      .from('community_post_snippets')
      .select('title, body, char_count')
      .eq('post_id', req.params.id)
      .maybeSingle();
    if (error) {
      // Jalur BACA boleh degradasi: tabel belum dimigrasi berarti belum ada
      // lampiran mana pun untuk dibaca, jadi 404 yang sama dengan "baris tidak
      // ada" — 503 disimpan untuk jalur TULIS, yang benar-benar kehilangan
      // data kalau tetap diteruskan.
      if (isCommunitySnippetSchemaMissing(error)) {
        return res.status(404).json({ error: 'Lampiran teks tidak ditemukan' });
      }
      throw error;
    }
    if (!row) return res.status(404).json({ error: 'Lampiran teks tidak ditemukan' });

    res.json({
      success: true,
      data: { title: row.title ?? null, body: row.body, char_count: Number(row.char_count) || 0 },
    });
  } catch (err) {
    console.error('[community] snippet detail error:', err);
    res.status(500).json({ error: 'Gagal memuat lampiran teks' });
  }
});

app.get('/api/community/posts/:id/comments', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }
    const post = await loadActiveCommunityPost(req.params.id);
    if (!post) return res.status(404).json({ error: 'Postingan tidak ditemukan' });

    // Balasan hidup sebagai baris community_posts dengan is_reply=true (lihat
    // POST di bawah) — bukan lagi community_post_comments. Menyaring HANYA
    // parent_post_id akan ikut menarik segmen lanjutan utas (Fitur A composer
    // juga memakai parent_post_id, dengan is_reply=false); is_reply=true
    // membedakan keduanya.
    //
    // Urutan TERBARU DULU (klien merender apa adanya, jadi komentar baru muncul
    // di baris paling atas — tepat di bawah komposer). Arah order ini bukan
    // sekadar kosmetik: berpasangan dengan limit(100) ia menentukan komentar
    // MANA yang bertahan saat terpotong — descending menyimpan 100 TERBARU,
    // ascending dulu menyimpan 100 TERLAMA (di kiriman ramai, komentar terbaru
    // justru hilang dari daftar yang katanya "terbaru di atas"). id dipakai
    // sebagai pemecah seri supaya dua komentar bercap waktu identik tetap
    // deterministik urutannya, sama seperti pagination feed.
    const loadCommentRows = (includeMedia, includeEdited) => supabase
      .from('community_posts')
      .select(`id, agent_id, body, ${includeMedia ? 'media, ' : ''}${includeEdited ? 'edited_at, ' : ''}created_at, parent_post_id, agent:agents!community_posts_agent_id_fkey(name, slug, photo)`)
      .eq('parent_post_id', post.id)
      .eq('is_reply', true)
      .is('deleted_at', null)
      .order('created_at', { ascending: false })
      .order('id', { ascending: false })
      .limit(100);
    let includeMedia = true;
    let includeEdited = true;
    let comments = null;
    let error = null;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      ({ data: comments, error } = await loadCommentRows(includeMedia, includeEdited));
      if (includeMedia && isCommunityMediaSchemaMissing(error)) {
        includeMedia = false;
        continue;
      }
      if (includeEdited && isCommunityEditSchemaMissing(error)) {
        includeEdited = false;
        continue;
      }
      break;
    }
    // Pra-migrasi (is_reply/parent_post_id belum ada): daftar kosong, bukan
    // 500 — sama dengan degradasi POST /comments di bawah.
    if (isCommunityThreadSchemaMissing(error)) {
      comments = [];
      error = null;
    }
    if (error) throw error;

    const childIds = (comments || []).map(row => row.id);
    const replyCounts = new Map(childIds.map(id => [id, 0]));
    if (childIds.length > 0) {
      // Query RINGAN khusus menghitung: hanya parent_post_id, tanpa body/media/
      // relasi agen. Limit di sini TIDAK bisa dijamin berlaku apa adanya —
      // PostgREST punya plafon max_rows sisi server (default 1000 di Supabase)
      // yang memperkecil limit manapun yang lebih besar tanpa pemberitahuan.
      // Karena itu truncation dideteksi lewat count (jumlah asli di DB) vs
      // panjang data yang benar-benar diterima, bukan lewat ambang yang ditebak.
      // order() ditambahkan supaya baris mana yang tersisa saat terpotong
      // deterministik, bukan acak.
      const REPLY_COUNT_LIMIT = 2000;
      const { data: countRows, error: countError, count: replyCountTotal } = await supabase
        .from('community_posts')
        .select('parent_post_id', { count: 'exact' })
        .in('parent_post_id', childIds)
        .eq('is_reply', true)
        .is('deleted_at', null)
        .order('created_at', { ascending: true })
        .limit(REPLY_COUNT_LIMIT);
      if (countError && !isCommunityThreadSchemaMissing(countError)) throw countError;
      for (const row of (countError ? [] : (countRows || []))) {
        if (replyCounts.has(row.parent_post_id)) {
          replyCounts.set(row.parent_post_id, replyCounts.get(row.parent_post_id) + 1);
        }
      }
      if (!countError && typeof replyCountTotal === 'number' && replyCountTotal > (countRows || []).length) {
        console.warn(`[community] reply count truncated: db count=${replyCountTotal} received=${(countRows || []).length} at GET /api/community/posts/${post.id}/comments`);
      }
    }

    // Ala Threads: balasan TIDAK lagi dikirim sebagai cuplikan inline. Klien
    // menampilkan satu tombol "Lihat N balasan" (N = reply_count) lalu memuat
    // SEMUA balasan lewat GET .../comments milik komentar itu saat dibuka. Jadi
    // tak ada lagi query "grandchildren" untuk cuplikan di sini — cukup
    // reply_count dari query ringan di atas; preview_replies selalu kosong.

    // Komentar adalah kiriman juga, jadi klien butuh reactions/my_reaction/
    // reaction_sample_name dalam bentuk yang SAMA PERSIS dengan feed & detail
    // kiriman (lihat GET /api/community/feed dan GET /api/community/posts/:id)
    // supaya komponen & tipe di klien bisa dipakai ulang. Diambil untuk semua
    // komentar tingkat teratas dalam SATU query .in(), bukan satu per komentar.
    const reactionTargetIds = [...new Set(childIds)];

    const commentReactionCounts = new Map(reactionTargetIds.map(id => [id, { suka: 0, selamat: 0, aamiin: 0 }]));
    const commentMyReactions = new Map(reactionTargetIds.map(id => [id, null]));
    const commentReactionSampleNames = new Map(reactionTargetIds.map(id => [id, null]));

    if (reactionTargetIds.length > 0) {
      // Batas eksplisit + urutan deterministik + deteksi pemotongan lewat
      // count-exact vs panjang data diterima -- disiplin yang sama dipakai di
      // atas untuk reply count/preview, karena limit() saja tidak bisa
      // dipercaya (PostgREST memperkecil limit lewat max_rows sisi server
      // tanpa pemberitahuan, sehingga ambang limit() tidak pernah tercapai).
      const COMMENT_REACTION_LIMIT = 5000;
      const { data: reactionRows, error: reactionError, count: reactionCountTotal } = await supabase
        .from('community_post_reactions')
        .select('post_id, reaction, agent_id, agent:agents(name)', { count: 'exact' })
        .in('post_id', reactionTargetIds)
        .order('created_at', { ascending: true })
        .limit(COMMENT_REACTION_LIMIT);
      if (reactionError) throw reactionError;
      for (const row of reactionRows || []) {
        const counts = commentReactionCounts.get(row.post_id);
        if (!counts || !COMMUNITY_REACTION_TYPES.includes(row.reaction)) continue;
        counts[row.reaction] += 1;
        if (row.agent_id === req.user.id) {
          commentMyReactions.set(row.post_id, row.reaction);
        } else if (!commentReactionSampleNames.get(row.post_id)) {
          const sampleName = communityAuthorProfile(row.agent).name;
          if (sampleName) commentReactionSampleNames.set(row.post_id, sampleName);
        }
      }
      if (typeof reactionCountTotal === 'number' && reactionCountTotal > (reactionRows || []).length) {
        console.warn(`[community] comment reaction count truncated: db count=${reactionCountTotal} received=${(reactionRows || []).length} at GET /api/community/posts/${post.id}/comments`);
      }
    }

    const toCommentPayload = row => ({
      id: row.id,
      body: row.body,
      media: normalizeStoredCommunityMedia(row.media),
      created_at: row.created_at,
      edited_at: row.edited_at ?? null,
      author: communityAuthorProfile(row.agent),
      reactions: commentReactionCounts.get(row.id) || { suka: 0, selamat: 0, aamiin: 0 },
      my_reaction: commentMyReactions.get(row.id) ?? null,
      reaction_sample_name: commentReactionSampleNames.get(row.id) ?? null,
      is_own: row.agent_id === agent.id,
    });

    const data = (comments || []).map(comment => ({
      ...toCommentPayload(comment),
      reply_count: replyCounts.get(comment.id) || 0,
      // Tak ada cuplikan inline (ala Threads) — klien memuat balasan saat dibuka.
      preview_replies: [],
    }));
    res.json({ success: true, data });
  } catch (err) {
    console.error('[community] load comments error:', err);
    res.status(500).json({ error: 'Gagal memuat komentar' });
  }
});

// Balasan komentar sekarang hidup sebagai baris `community_posts` biasa,
// dibedakan dari segmen utas composer (POST /api/community/posts di atas)
// lewat `is_reply: true` — lihat migrasi 20260726000000 & reconcile-map §3.
// parent_post_id menunjuk langsung ke kiriman yang dibalas; root_post_id
// didenormalisasi ke akar utas via resolveRootPostId(post) supaya balasan
// atas balasan tetap mengelompok ke utas yang sama.
app.post('/api/community/posts/:id/comments', authMiddleware, express.json({ limit: '8kb' }), async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    const body = typeof req.body?.body === 'string' ? req.body.body.trim() : '';
    const bodyLength = Array.from(body).length;
    if (bodyLength < 1 || bodyLength > 300) {
      return res.status(400).json({ error: 'Isi komentar wajib 1–300 karakter' });
    }
    const clientId = req.body?.client_id;
    if (clientId !== undefined && !isCommunityUuid(clientId)) {
      return res.status(400).json({ error: 'ID komentar tidak valid' });
    }
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }

    const post = await loadActiveCommunityPost(req.params.id);
    if (!post) return res.status(404).json({ error: 'Postingan tidak ditemukan' });

    let media = [];
    if (req.body?.media !== undefined) {
      const mediaPrefixes = communityMediaPublicPrefixes();
      if (!mediaPrefixes.length) throw new Error('Public URL media Teras tidak tersedia');
      media = normalizeCommunityMediaInput(req.body.media, mediaPrefixes, agent.slug);
      if (!media) {
        return res.status(400).json({ error: `Media komentar tidak valid atau melebihi ${COMMUNITY_MAX_MEDIA_ITEMS} item` });
      }
    }

    const rootPostId = resolveRootPostId(post);

    let includeMediaColumn = true;
    // Kompatibilitas instalasi yang pernah menjalankan draf Teras awal, di
    // mana `type` NOT NULL tanpa default. Cabang ini meniru pola yang sama
    // dipakai jalur kiriman (POST /api/community/posts, createCommunityPostRow)
    // — tanpa cabang ini, setiap balasan di instalasi semacam itu gagal 500
    // sementara kiriman induk/segmen tetap jalan.
    let includeObsoleteType = false;
    let createdComment = null;
    let error = null;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const insertResult = await supabase
        .from('community_posts')
        .insert({
          ...(clientId ? { id: clientId } : {}),
          agent_id: agent.id,
          body,
          is_system: false,
          parent_post_id: post.id,
          root_post_id: rootPostId,
          is_reply: true,
          ...(includeMediaColumn ? { media } : {}),
          ...(includeObsoleteType ? { type: media.length > 0 ? 'foto' : 'tips' } : {}),
        })
        .select(`id, body, ${includeMediaColumn ? 'media, ' : ''}created_at`)
        .single();
      createdComment = insertResult.data;
      error = insertResult.error;
      if (isCommunityThreadSchemaMissing(error)) {
        return res.status(503).json({ error: 'Migrasi thread Teras belum diterapkan' });
      }
      if (includeMediaColumn && isCommunityMediaSchemaMissing(error)) {
        if (media.length > 0) {
          return res.status(503).json({ error: 'Migrasi media komentar Teras belum diterapkan' });
        }
        includeMediaColumn = false;
        continue;
      }
      if (
        !includeObsoleteType
        && error?.code === '23502'
        && /column "type"/i.test(error.message || '')
      ) {
        includeObsoleteType = true;
        continue;
      }
      break;
    }
    if (error?.code === '23505' && clientId) {
      const loadExistingComment = includeMedia => supabase
        .from('community_posts')
        .select(`id, body, ${includeMedia ? 'media, ' : ''}created_at`)
        .eq('id', clientId)
        .eq('parent_post_id', post.id)
        .eq('agent_id', agent.id)
        .eq('is_reply', true)
        .is('deleted_at', null)
        .maybeSingle();
      let { data: existingComment, error: existingError } = await loadExistingComment(true);
      if (isCommunityMediaSchemaMissing(existingError)) {
        ({ data: existingComment, error: existingError } = await loadExistingComment(false));
      }
      if (existingError) throw existingError;
      if (existingComment && existingComment.body === body) {
        createdComment = existingComment;
        error = null;
      } else {
        return res.status(409).json({ error: 'ID komentar sudah digunakan' });
      }
    }
    if (error) throw error;

    await recordCommunityMentions({
      body: createdComment.body,
      postId: post.id,
      authorAgent: agent,
      commentId: createdComment.id,
    });

    const data = {
      id: createdComment.id,
      body: createdComment.body,
      media: normalizeStoredCommunityMedia(createdComment.media),
      created_at: createdComment.created_at,
      author: communityAuthorProfile(agent),
      // Komentar baru belum punya reaksi/balasan apa pun — sama seperti POST
      // /api/community/posts, nilai nol/kosong dikirim langsung tanpa query
      // tambahan, dalam bentuk yang sama dengan GET .../comments.
      reactions: { suka: 0, selamat: 0, aamiin: 0 },
      my_reaction: null,
      reaction_sample_name: null,
      is_own: true,
      reply_count: 0,
      preview_replies: [],
    };
    res.status(201).json({ success: true, data });
  } catch (err) {
    console.error('[community] create comment error:', err);
    res.status(500).json({ error: 'Gagal menambahkan komentar' });
  }
});

// PATCH /api/community/posts/:id — edit teks kiriman/komentar oleh penulisnya.
// Kebijakan (spec 2026-07-22): tanpa batas waktu; teks saja; TANPA notifikasi
// mention baru & TANPA refresh link preview; @semua baru ditolak di helper.
app.patch('/api/community/posts/:id', authMiddleware, express.json({ limit: '8kb' }), async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Kiriman tidak ditemukan' });
    }
    const loadPostForEdit = withThread => supabase
      .from('community_posts')
      .select(`id, agent_id, body, deleted_at${withThread ? ', is_reply' : ''}`)
      .eq('id', req.params.id)
      .maybeSingle();
    let { data: post, error: findError } = await loadPostForEdit(true);
    if (isCommunityThreadSchemaMissing(findError)) {
      ({ data: post, error: findError } = await loadPostForEdit(false));
    }
    if (findError) throw findError;
    if (!post || post.deleted_at) {
      return res.status(404).json({ error: 'Kiriman tidak ditemukan' });
    }
    // Sengaja BUKAN canModerateCommunityContent: admin tidak mengedit tulisan
    // orang — jalur moderasi tetap hapus.
    if (post.agent_id !== agent.id) {
      return res.status(403).json({ error: 'Hanya penulis yang bisa mengedit' });
    }

    const verdict = validateCommunityEdit({
      nextBody: req.body?.body,
      previousBody: post.body,
      isReply: post.is_reply === true,
    });
    if (!verdict.ok) return res.status(400).json({ error: verdict.error });

    const editedAt = new Date().toISOString();
    const { error: updateError } = await supabase
      .from('community_posts')
      .update({ body: verdict.body, edited_at: editedAt })
      .eq('id', post.id);
    if (isCommunityEditSchemaMissing(updateError)) {
      return res.status(503).json({ error: 'Migrasi edit Teras belum diterapkan' });
    }
    if (updateError) throw updateError;

    res.json({ data: { id: post.id, body: verdict.body, edited_at: editedAt } });
  } catch (error) {
    console.error('PATCH /api/community/posts/:id error:', error);
    res.status(500).json({ error: 'Gagal menyimpan perubahan' });
  }
});

// POST /api/community/posts/:id/pin — sematkan SATU kiriman (admin).
// Pin baru melepas pin lama; index parsial unik di DB menegakkan slot tunggal.
app.post('/api/community/posts/:id/pin', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Hanya admin yang bisa menyematkan' });
    }
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Kiriman tidak ditemukan' });
    }
    const loadPostForPin = withThread => supabase
      .from('community_posts')
      .select(`id, deleted_at${withThread ? ', parent_post_id, is_reply' : ''}`)
      .eq('id', req.params.id)
      .maybeSingle();
    let { data: post, error: findError } = await loadPostForPin(true);
    if (isCommunityThreadSchemaMissing(findError)) {
      ({ data: post, error: findError } = await loadPostForPin(false));
    }
    if (findError) throw findError;
    if (!post) return res.status(404).json({ error: 'Kiriman tidak ditemukan' });
    const verdict = canPinCommunityPost(post);
    if (!verdict.ok) {
      return res
        .status(verdict.error === 'Kiriman tidak ditemukan' ? 404 : 400)
        .json({ error: verdict.error });
    }

    const { error: clearError } = await supabase
      .from('community_posts')
      .update({ pinned_at: null })
      .not('pinned_at', 'is', null);
    if (isCommunityPinSchemaMissing(clearError)) {
      return res.status(503).json({ error: 'Migrasi pin Teras belum diterapkan' });
    }
    if (clearError) throw clearError;

    const pinnedAt = new Date().toISOString();
    const { error: pinError } = await supabase
      .from('community_posts')
      .update({ pinned_at: pinnedAt })
      .eq('id', post.id);
    if (isCommunityPinSchemaMissing(pinError)) {
      return res.status(503).json({ error: 'Migrasi pin Teras belum diterapkan' });
    }
    if (String(pinError?.code || '') === '23505') {
      return res.status(409).json({ error: 'Pin sedang diubah, coba lagi' });
    }
    if (pinError) throw pinError;

    res.json({ data: { id: post.id, pinned_at: pinnedAt } });
  } catch (err) {
    console.error('[community] pin error:', err);
    res.status(500).json({ error: 'Gagal menyematkan kiriman' });
  }
});

// DELETE /api/community/posts/:id/pin — lepas sematan (admin, idempoten).
app.delete('/api/community/posts/:id/pin', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;
    if (req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Hanya admin yang bisa menyematkan' });
    }
    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Kiriman tidak ditemukan' });
    }
    const { error: unpinError } = await supabase
      .from('community_posts')
      .update({ pinned_at: null })
      .eq('id', req.params.id);
    if (isCommunityPinSchemaMissing(unpinError)) {
      return res.status(503).json({ error: 'Migrasi pin Teras belum diterapkan' });
    }
    if (unpinError) throw unpinError;
    res.json({ data: { id: req.params.id, pinned_at: null } });
  } catch (err) {
    console.error('[community] unpin error:', err);
    res.status(500).json({ error: 'Gagal melepas sematan' });
  }
});

app.delete('/api/community/posts/:id', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }
    const loadPostForDelete = withThread => supabase
      .from('community_posts')
      .select(`id, agent_id, deleted_at${withThread ? ', parent_post_id, root_post_id' : ''}`)
      .eq('id', req.params.id)
      .maybeSingle();
    let includeThread = true;
    let { data: post, error: findError } = await loadPostForDelete(true);
    if (isCommunityThreadSchemaMissing(findError)) {
      includeThread = false;
      ({ data: post, error: findError } = await loadPostForDelete(false));
    }
    if (findError) throw findError;
    if (!post) return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    if (!canModerateCommunityContent(agent, post)) {
      return res.status(403).json({ error: 'Anda tidak boleh menghapus postingan ini' });
    }
    if (post.deleted_at) return res.json({ success: true });

    // Menghapus segmen pertama (parent_post_id NULL) menghapus seluruh utas
    // sekaligus: sisa segmen jadi yatim kalau tidak ikut disoftdelete — tak
    // muncul di feed tapi masih hidup di tautan langsung/halaman detail.
    // Segmen tengah dihapus sendirian; rantai tidak disusun ulang, segmen
    // yang hilang cuma tak dirender. Kiriman biasa (bukan bagian utas apa
    // pun) juga punya parent_post_id NULL sehingga masuk cabang ini juga —
    // aman, karena root_post_id-nya tak pernah menunjuk siapa pun jadi
    // .or(...) di bawah cuma kena dirinya sendiri.
    const patch = {
      deleted_at: new Date().toISOString(),
      deleted_by: agent.id,
    };
    let deleteError;
    if (includeThread && post.parent_post_id === null) {
      // post.id berasal dari baris yang baru saja dibaca lewat eq('id', ...)
      // di atas (sudah divalidasi UUID oleh isCommunityUuid), aman diselipkan
      // ke string filter .or().
      // Pertahanan berlapis: lingkupi pada penulis ASLI utas (post.agent_id),
      // bukan agent yang meminta — endpoint ini juga melayani moderasi (admin
      // menghapus kiriman agent lain), dan same-author-per-chain dijamin oleh
      // konstruksi saat ini, tapi tidak ada yang menegakkannya di titik ini.
      //
      // is_reply=false wajib: `.or('id.eq...,root_post_id.eq...')` juga
      // menarik balasan (is_reply=true) yang berbagi root_post_id dengan
      // utas ini — termasuk self-reply penulis akar ke kirimannya sendiri
      // (yang lolos filter agent_id di atas karena penulisnya sama). Tanpa
      // filter ini balasan itu ikut soft-deleted, padahal seharusnya cuma
      // jadi placeholder {available:false} di buildAncestorChain seperti
      // balasan agent lain. Akar sendiri (is_reply=false) tetap ikut lewat
      // `id.eq...`; segmen lanjutan (is_reply=false) tetap ikut lewat
      // `root_post_id.eq...`.
      ({ error: deleteError } = await supabase
        .from('community_posts')
        .update(patch)
        .or(`id.eq.${post.id},root_post_id.eq.${post.id}`)
        .eq('agent_id', post.agent_id)
        .eq('is_reply', false)
        .is('deleted_at', null));
      // Pra-migrasi is_reply (jendela sempit: root_post_id sudah ada dari
      // Fitur A, kolom is_reply belum) -- query di atas gagal karena kolom
      // tak dikenal. Fallback ke perilaku main lama (cascade tanpa filter
      // is_reply, menyapu seluruh rantai milik penulis akar termasuk
      // self-reply) hanya untuk jendela sempit ini; begitu migrasi is_reply
      // diterapkan, cabang ini tidak pernah tereksekusi lagi.
      if (isCommunityThreadSchemaMissing(deleteError)) {
        ({ error: deleteError } = await supabase
          .from('community_posts')
          .update(patch)
          .or(`id.eq.${post.id},root_post_id.eq.${post.id}`)
          .eq('agent_id', post.agent_id)
          .is('deleted_at', null));
      }
    } else {
      ({ error: deleteError } = await supabase
        .from('community_posts')
        .update(patch)
        .eq('id', post.id)
        .is('deleted_at', null));
    }
    if (deleteError) throw deleteError;

    // Baris yang baru dihapus tidak boleh terus jadi kartu tersemat -- bersihkan
    // slot pin secara best-effort. Kolom pinned_at mungkin belum ada
    // pra-migrasi, jadi ini TIDAK digabung ke `patch` di atas (kalau digabung,
    // update seluruh soft-delete ikut gagal saat kolomnya belum ada). Gagal di
    // sini tidak boleh menggagalkan respons hapus yang sudah sukses.
    const { error: unpinDeletedError } = await supabase
      .from('community_posts')
      .update({ pinned_at: null })
      .eq('id', req.params.id)
      .not('pinned_at', 'is', null);
    if (unpinDeletedError && !isCommunityPinSchemaMissing(unpinDeletedError)) {
      console.error('[community] clear pin on delete error:', unpinDeletedError);
    }

    res.json({ success: true });
  } catch (err) {
    console.error('[community] delete post error:', err);
    res.status(500).json({ error: 'Gagal menghapus postingan' });
  }
});

app.delete('/api/community/comments/:id', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Komentar tidak ditemukan' });
    }
    // Balasan hidup di community_posts sekarang; endpoint ini adalah alias
    // yang hanya boleh menghapus baris BALASAN (parent_post_id terisi DAN
    // is_reply=true) — bukan kiriman induk (parent_post_id NULL, itu tugas
    // DELETE /posts/:id) dan bukan segmen utas composer (parent_post_id
    // terisi tapi is_reply=false, ikut cascade lewat DELETE /posts/:id juga).
    const { data: comment, error: findError } = await supabase
      .from('community_posts')
      .select('id, agent_id, deleted_at, parent_post_id, is_reply')
      .eq('id', req.params.id)
      .maybeSingle();
    if (isCommunityThreadSchemaMissing(findError)) {
      return res.status(503).json({ error: 'Migrasi thread Teras belum diterapkan' });
    }
    if (findError) throw findError;
    if (!comment || !comment.parent_post_id || !comment.is_reply) {
      return res.status(404).json({ error: 'Komentar tidak ditemukan' });
    }
    if (!canModerateCommunityContent(agent, comment)) {
      return res.status(403).json({ error: 'Anda tidak boleh menghapus komentar ini' });
    }
    if (comment.deleted_at) return res.json({ success: true });

    const { error: updateError } = await supabase
      .from('community_posts')
      .update({ deleted_at: new Date().toISOString(), deleted_by: agent.id })
      .eq('id', comment.id)
      .eq('is_reply', true)
      .not('parent_post_id', 'is', null)
      .is('deleted_at', null);
    if (updateError) throw updateError;

    res.json({ success: true });
  } catch (err) {
    console.error('[community] delete comment error:', err);
    res.status(500).json({ error: 'Gagal menghapus komentar' });
  }
});

// ---------------------------------------------------------------------------
// Purge media Teras: file storage (Bunny/Supabase) milik post & komentar yang
// sudah di-soft-delete lebih dari COMMUNITY_MEDIA_PURGE_AFTER_DAYS hari
// dihapus, lalu kolom media/photo_url baris itu dikosongkan sebagai penanda
// selesai. Soft-delete-nya sendiri tetap — hanya file yang dibersihkan.
const COMMUNITY_MEDIA_PURGE_AFTER_DAYS = 7;
const COMMUNITY_MEDIA_PURGE_BATCH = 50;

function communityMediaStorageTarget(url) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (
    BUNNY_CDN_HOSTNAME
    && parsed.origin === `https://${BUNNY_CDN_HOSTNAME}`
    && parsed.pathname.startsWith('/community/')
  ) {
    return { storage: 'bunny', path: parsed.pathname.slice(1) };
  }
  const marker = '/object/public/agent-photos/';
  const markerIndex = parsed.pathname.indexOf(marker);
  if (markerIndex !== -1) {
    const path = decodeURIComponent(parsed.pathname.slice(markerIndex + marker.length));
    if (path.startsWith('community/')) return { storage: 'supabase', path };
  }
  return null;
}

// URL yang sama bisa saja dirujuk post/komentar lain yang masih hidup —
// filenya baru boleh dihapus kalau tidak ada satu pun rujukan hidup.
async function communityMediaUrlStillReferenced(url) {
  const results = await Promise.all([
    // JSON.stringify wajib: .contains dengan array JS dienkode postgrest-js
    // sebagai literal array Postgres `{...}`, bukan containment JSONB → 400.
    supabase.from('community_posts')
      .select('id', { count: 'exact', head: true })
      .is('deleted_at', null)
      .contains('media', JSON.stringify([{ url }])),
    supabase.from('community_posts')
      .select('id', { count: 'exact', head: true })
      .is('deleted_at', null)
      .eq('photo_url', url),
    supabase.from('community_post_comments')
      .select('id', { count: 'exact', head: true })
      .is('deleted_at', null)
      .contains('media', JSON.stringify([{ url }])),
    // File yang sama bisa dirujuk sebagai poster video (key `poster`,
    // bukan `url`) oleh baris hidup lain.
    supabase.from('community_posts')
      .select('id', { count: 'exact', head: true })
      .is('deleted_at', null)
      .contains('media', JSON.stringify([{ poster: url }])),
    supabase.from('community_post_comments')
      .select('id', { count: 'exact', head: true })
      .is('deleted_at', null)
      .contains('media', JSON.stringify([{ poster: url }])),
  ]);
  let referenced = 0;
  for (const result of results) {
    if (
      result.error
      && !isCommunityMediaSchemaMissing(result.error)
      && !isCommunityCommentsTableMissing(result.error)
    ) {
      throw result.error;
    }
    referenced += result.count || 0;
  }
  return referenced > 0;
}

// Return false hanya kalau file Bunny tidak bisa dihapus karena kredensial
// Bunny tidak dikonfigurasi — baris dibiarkan untuk dicoba lagi run berikutnya.
async function deleteCommunityMediaFile(target) {
  if (target.storage === 'bunny') {
    if (!getBunnyEnabled()) return false;
    await bunnyDelete(target.path);
    return true;
  }
  const { error } = await supabase.storage.from('agent-photos').remove([target.path]);
  if (error) throw error;
  return true;
}

async function purgeDeletedCommunityMedia() {
  const cutoff = new Date(Date.now() - COMMUNITY_MEDIA_PURGE_AFTER_DAYS * 24 * 60 * 60 * 1000).toISOString();
  const stats = { rowsCleared: 0, filesDeleted: 0, filesKept: 0, rowsRetried: 0, errors: 0 };

  const tables = [
    { table: 'community_posts', hasPhotoUrl: true },
    { table: 'community_post_comments', hasPhotoUrl: false },
  ];

  for (const { table, hasPhotoUrl } of tables) {
    const baseQuery = columns => supabase
      .from(table)
      .select(columns)
      .not('deleted_at', 'is', null)
      .lt('deleted_at', cutoff)
      .order('deleted_at', { ascending: true })
      .limit(COMMUNITY_MEDIA_PURGE_BATCH);

    // Dua query terpisah (media terisi / photo_url terisi) alih-alih .or()
    // supaya nilai `[]` tidak perlu lewat parser filter or PostgREST.
    let includeMedia = true;
    const rowsById = new Map();

    let { data: mediaRows, error: mediaError } = await baseQuery(`id, media${hasPhotoUrl ? ', photo_url' : ''}`)
      .neq('media', '[]');
    // Tabel itu sendiri hilang (community_post_comments di-rename Langkah 6)
    // ditoleransi sama seperti kolomnya hilang: lewati diam-diam, jangan catat
    // sebagai error tiap sweep purge.
    if (isCommunityMediaSchemaMissing(mediaError) || isCommunityCommentsTableMissing(mediaError)) {
      includeMedia = false;
      mediaRows = [];
      mediaError = null;
    }
    if (mediaError) {
      console.error(`[community] media purge fetch ${table}:`, mediaError.message);
      stats.errors += 1;
      continue;
    }
    for (const row of mediaRows || []) rowsById.set(row.id, row);

    if (hasPhotoUrl) {
      const { data: photoRows, error: photoError } = await baseQuery(`id${includeMedia ? ', media' : ''}, photo_url`)
        .not('photo_url', 'is', null);
      if (photoError) {
        console.error(`[community] media purge fetch ${table} photo_url:`, photoError.message);
        stats.errors += 1;
      } else {
        for (const row of photoRows || []) {
          if (!rowsById.has(row.id)) rowsById.set(row.id, row);
        }
      }
    }

    // Komentar pada instalasi tanpa kolom media: tidak ada yang bisa dibersihkan.
    if (!includeMedia && !hasPhotoUrl) continue;

    for (const row of rowsById.values()) {
      try {
        const urls = new Set();
        for (const item of Array.isArray(row.media) ? row.media : []) {
          if (item && typeof item.url === 'string') urls.add(item.url);
          // Poster video adalah file storage tersendiri — tanpa ini ia yatim
          // permanen di CDN setiap kali kirimannya dihapus.
          if (item && typeof item.poster === 'string' && item.poster) urls.add(item.poster);
        }
        if (hasPhotoUrl && typeof row.photo_url === 'string' && row.photo_url) urls.add(row.photo_url);

        let retryRow = false;
        for (const url of urls) {
          const target = communityMediaStorageTarget(url);
          // URL asing (bukan storage kelolaan kita) tetap dianggap selesai —
          // kalau tidak, barisnya bakal dicoba ulang selamanya.
          if (!target) {
            stats.filesKept += 1;
            continue;
          }
          if (await communityMediaUrlStillReferenced(url)) {
            stats.filesKept += 1;
            continue;
          }
          const deleted = await deleteCommunityMediaFile(target);
          if (!deleted) {
            retryRow = true;
            continue;
          }
          stats.filesDeleted += 1;
        }
        if (retryRow) {
          stats.rowsRetried += 1;
          continue;
        }

        const { error: clearError } = await supabase
          .from(table)
          .update({
            ...(includeMedia ? { media: [] } : {}),
            ...(hasPhotoUrl ? { photo_url: null } : {}),
          })
          .eq('id', row.id);
        if (clearError) throw clearError;
        stats.rowsCleared += 1;
      } catch (err) {
        stats.errors += 1;
        console.error(`[community] media purge row ${table}/${row.id}:`, err.message);
      }
    }
  }

  if (stats.rowsCleared || stats.filesDeleted || stats.rowsRetried || stats.errors) {
    console.log(`[community] Media purge: ${stats.filesDeleted} file dihapus, ${stats.filesKept} dipertahankan (masih dirujuk/asing), ${stats.rowsCleared} baris dibersihkan, ${stats.rowsRetried} ditunda, ${stats.errors} error`);
  }
  return stats;
}

let communityMediaPurgeRunning = false;
if (shouldRunBackgroundJobs()) {
  // 02:40 WIB — offset dari maintenance analytics (02:00) biar tidak berebut DB.
  cron.schedule('40 2 * * *', async () => {
    if (communityMediaPurgeRunning || isDbDegraded()) return;
    communityMediaPurgeRunning = true;
    try {
      await purgeDeletedCommunityMedia();
    } catch (err) {
      console.error('[community] media purge threw:', err.message);
    } finally {
      communityMediaPurgeRunning = false;
    }
  }, { timezone: 'Asia/Jakarta' });
}

app.post('/api/community/posts/:id/report', authMiddleware, async (req, res) => {
  try {
    const agent = await getAgentById(req.user.id);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (!requireCommunityAccess(agent, res)) return;

    if (!isCommunityUuid(req.params.id)) {
      return res.status(404).json({ error: 'Postingan tidak ditemukan' });
    }
    const post = await loadActiveCommunityPost(req.params.id);
    if (!post) return res.status(404).json({ error: 'Postingan tidak ditemukan' });

    const { error } = await supabase
      .from('community_post_reports')
      .insert({ post_id: post.id, agent_id: agent.id });
    if (error && error.code !== '23505') throw error;

    res.json({ success: true });
  } catch (err) {
    console.error('[community] report error:', err);
    res.status(500).json({ error: 'Gagal melaporkan postingan' });
  }
});

// ──────────────────────────────────────────────
// Custom Domain API
// Agent dapat point apex domain (mis. nilanovita.com) ke VPS_PUBLIC_IP.
// Setelah A record verified, Caddy on-demand TLS akan issue cert otomatis.
// ──────────────────────────────────────────────

const VALID_DOMAIN_REGEX = /^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i;
const RESERVED_CUSTOM_DOMAIN_BASE = 'alhijaz.co';
const CUSTOM_DOMAIN_DISABLED_MESSAGE = 'Fitur Custom Domain belum tersedia untuk agent ini';
const MULTI_LABEL_PUBLIC_SUFFIXES = new Set([
  'ac.id',
  'biz.id',
  'co.id',
  'desa.id',
  'go.id',
  'my.id',
  'net.id',
  'or.id',
  'ponpes.id',
  'sch.id',
  'web.id',
]);

function isAllowedCustomDomainName(domain) {
  const parts = domain.split('.');
  if (parts.length === 2) return !MULTI_LABEL_PUBLIC_SUFFIXES.has(domain);
  if (parts.length === 3) {
    return MULTI_LABEL_PUBLIC_SUFFIXES.has(`${parts[1]}.${parts[2]}`);
  }
  return false;
}

function validateDomainFormat(domain) {
  if (!domain || typeof domain !== 'string') return false;
  const d = domain.trim().toLowerCase();
  if (d.includes('://') || d.includes('/') || d.includes(' ')) return false;
  if (d.startsWith('www.')) return false;
  return VALID_DOMAIN_REGEX.test(d) && isAllowedCustomDomainName(d);
}

function isReservedDomain(domain) {
  const d = (domain || '').trim().toLowerCase();
  return d === RESERVED_CUSTOM_DOMAIN_BASE || d.endsWith(`.${RESERVED_CUSTOM_DOMAIN_BASE}`);
}

async function verifyDomainDns(domain) {
  const expectedIp = process.env.VPS_PUBLIC_IP;
  if (!expectedIp) return false;
  try {
    const ips = await dns.resolve4(domain);
    return Array.isArray(ips) && ips.includes(expectedIp);
  } catch {
    return false;
  }
}

async function getResolvedIp(domain) {
  try {
    const ips = await dns.resolve4(domain);
    return ips?.[0] || null;
  } catch {
    return null;
  }
}

function buildCustomDomainPayload(agent, resolvedIp = null) {
  return {
    domain: agent?.custom_domain || null,
    status: agent?.custom_domain_status || null,
    verified_at: agent?.custom_domain_verified_at || null,
    ip_required: process.env.VPS_PUBLIC_IP || null,
    resolved_ip: resolvedIp,
  };
}

// GET /api/config/server-ip — public, dipakai UI untuk display instruksi DNS
app.get('/api/config/server-ip', (_req, res) => {
  res.json({ ip: process.env.VPS_PUBLIC_IP || null });
});

