app.get('/api/portal/jamaah/sessions', authMiddleware, async (req, res) => {
  try {
    const now = new Date().toISOString();
    const { data: sessions, error } = await supabase
      .from('jamaah_portal_sessions')
      .select('id_umroh, initiating_jamaah_id, last_active_at, created_at, user_agent')
      .eq('agent_id', req.user.id)
      .gt('expires_at', now)
      .order('last_active_at', { ascending: false });
    if (error) return res.status(500).json({ error: error.message });

    const ids = [...new Set((sessions || []).map((s) => s.initiating_jamaah_id).filter(Boolean))];
    const bookingIds = [...new Set((sessions || []).map((s) => s.id_umroh).filter(Boolean))];
    const [initiatorsRes, bookingNamesRes] = await Promise.all([
      ids.length
        ? supabase.from('jamaah').select('id, nama').eq('agent_id', req.user.id).in('id', ids)
        : Promise.resolve({ data: [], error: null }),
      bookingIds.length
        ? supabase.from('jamaah').select('id_umroh, nama').eq('agent_id', req.user.id).in('id_umroh', bookingIds).order('id', { ascending: true })
        : Promise.resolve({ data: [], error: null }),
    ]);
    if (initiatorsRes.error) return res.status(500).json({ error: initiatorsRes.error.message });
    if (bookingNamesRes.error) return res.status(500).json({ error: bookingNamesRes.error.message });

    const initiatorNames = new Map((initiatorsRes.data || []).map((row) => [row.id, row.nama]));
    const bookingNames = new Map();
    for (const row of bookingNamesRes.data || []) {
      if (!bookingNames.has(row.id_umroh)) bookingNames.set(row.id_umroh, row.nama);
    }

    res.json((sessions || []).map((session) => ({
      id_umroh: session.id_umroh,
      jamaah_name: initiatorNames.get(session.initiating_jamaah_id) || bookingNames.get(session.id_umroh) || null,
      last_active_at: session.last_active_at,
      created_at: session.created_at,
      user_agent: session.user_agent,
    })));
  } catch (err) {
    console.error('[PortalJamaah] sessions error:', err.message);
    res.status(500).json({ error: 'Gagal mengambil sessions' });
  }
});

// ──────────────────────────────────────────────
// Umroh Schedules: Sync from external API → Supabase
// ──────────────────────────────────────────────
// Active hijri years to sync. 1447 was dropped on 2026-06-09: it is a past year that
// the upstream API no longer serves (returns 522/empty), so its rows could never be
// refreshed — they lingered with frozen prices. Years removed from this list are reaped
// by the post-loop orphan cleanup in syncUmrohSchedules(). Keep in sync with the
// dashboard year selector (src/App.tsx availableYears).
const SCHEDULE_YEAR_CODES = ['1448', '1449'];
const SCHEDULE_SOURCE_URLS = [
  'https://jadwal.alhijaz.co',
  'http://115.124.86.220',
];

async function fetchScheduleYear(year) {
  let lastError = null;
  for (const baseUrl of SCHEDULE_SOURCE_URLS) {
    const url = `${baseUrl}/jadwal/api-get/${year}`;
    try {
      const res = await fetch(url, {
        headers: { 'User-Agent': 'Mozilla/5.0', 'Accept': 'application/json' },
        signal: AbortSignal.timeout(15000),
      });

      if (!res.ok) {
        lastError = new Error(`${url} HTTP ${res.status}`);
        console.warn(`[ScheduleSync] API ${year} ${baseUrl} HTTP ${res.status}`);
        continue;
      }

      return await res.json();
    } catch (err) {
      lastError = err;
      console.warn(`[ScheduleSync] API ${year} ${baseUrl} failed: ${err.message}`);
    }
  }
  throw lastError || new Error(`No schedule source available for ${year}`);
}

async function syncUmrohSchedules() {
  console.log('[ScheduleSync] Starting...');
  const startTime = Date.now();
  let totalSynced = 0;

  for (const year of SCHEDULE_YEAR_CODES) {
    try {
      const json = await fetchScheduleYear(year);
      const packages = json.aaData || [];

      if (!packages.length) {
        console.log(`[ScheduleSync] No packages for year ${year}`);
        continue;
      }

      // Read the previous brochure locator before upsert.  If upstream points
      // a jadwal_id at a different asset, the old CDN + thumb must be cleared
      // in the same write as the new source URL; otherwise readers keep seeing
      // the old artwork while (or after) the mirror refresh fails.
      const { data: previousRows, error: previousRowsError } = await supabase
        .from('umroh_schedules')
        .select('jadwal_id, brosur')
        .eq('year_code', year);
      if (previousRowsError) {
        throw new Error(`Gagal membaca provenance brosur ${year}: ${previousRowsError.message}`);
      }
      const previousById = new Map(
        (previousRows || []).map(row => [String(row.jadwal_id), row]),
      );

      const includedPackages = [];
      const rejectedPackages = [];
      for (const p of packages) {
        if (shouldKeepScheduleRow(p)) {
          includedPackages.push(p);
        } else {
          rejectedPackages.push({ jadwal_id: p.jadwal_id, jadwal_nama: p.jadwal_nama, seat_sisa: p.seat_sisa });
        }
      }
      if (rejectedPackages.length) {
        const sample = rejectedPackages.slice(0, 5).map(r => `${r.jadwal_id}(${r.jadwal_nama}, seat=${r.seat_sisa ?? '-'})`).join(', ');
        console.log(`[ScheduleSync] Year ${year}: filtered ${rejectedPackages.length} paket tanpa harga valid dan tanpa seat tersedia: ${sample}${rejectedPackages.length > 5 ? ', ...' : ''}`);
      }

      const rows = includedPackages.map(p => {
        const brochureSource = resolveScheduleBrochureSource(p);
        return {
          jadwal_id: p.jadwal_id,
          year_code: year,
          jadwal_nama: p.jadwal_nama,
          promo: p.promo,
          seat_total: p.seat_total,
          seat_sisa: p.seat_sisa,
          maskapai: p.maskapai,
          berangkat_tgl: /^\d{4}-\d{2}-\d{2}$/.test(p.berangkat_tgl) ? p.berangkat_tgl : null,
          berangkat_jam: p.berangkat_jam,
          berangkat_rute: p.berangkat_rute,
          berangkat_kode_penerbangan: p.berangkat_kode_penerbangan,
          pulang_tgl: /^\d{4}-\d{2}-\d{2}$/.test(p.pulang_tgl) ? p.pulang_tgl : null,
          pulang_jam: p.pulang_jam,
          pulang_rute: p.pulang_rute,
          pulang_kode_penerbangan: p.pulang_kode_penerbangan,
          manasik_tgl: p.manasik_tgl,
          manasik_jam: p.manasik_jam,
          brosur: brochureSource,
          ...buildBrochureCacheReset(previousById.get(String(p.jadwal_id)), brochureSource),
          itinerary: p.itinerary,
          perlengkapan_harga: p.perlengkapan_harga,
          paket_harga: p.paket_harga,
          paket_hotel: p.paket_hotel,
          synced_at: new Date().toISOString(),
        };
      });

      const { error } = await supabase
        .from('umroh_schedules')
        .upsert(rows, { onConflict: 'jadwal_id,year_code' });

      if (error) {
        console.error(`[ScheduleSync] Upsert error for year ${year}:`, error.message);
      } else {
        // Delete stale packages no longer in external API
        const currentIds = rows.map(r => r.jadwal_id);
        // First, fetch stale rows to clean up Bunny files
        const { data: staleRows } = await supabase
          .from('umroh_schedules')
          .select('jadwal_id, brosur_cdn, brosur_thumb_cdn, itinerary_cdn')
          .eq('year_code', year)
          .not('jadwal_id', 'in', `(${currentIds.join(',')})`);
        if (staleRows?.length && getBunnyEnabled()) {
          for (const stale of staleRows) {
            try {
              if (stale.brosur_cdn) await bunnyDelete(stale.brosur_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, ''));
              if (stale.brosur_thumb_cdn) await bunnyDelete(stale.brosur_thumb_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, ''));
              if (stale.itinerary_cdn) await bunnyDelete(stale.itinerary_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, ''));
            } catch (e) { console.error(`[ScheduleSync] Bunny cleanup ${stale.jadwal_id}: ${e.message}`); }
          }
        }
        // Then delete from Supabase
        const { error: delErr, count } = await supabase
          .from('umroh_schedules')
          .delete({ count: 'exact' })
          .eq('year_code', year)
          .not('jadwal_id', 'in', `(${currentIds.join(',')})`);
        if (delErr) {
          console.error(`[ScheduleSync] Cleanup error for year ${year}:`, delErr.message);
        } else if (count > 0) {
          console.log(`[ScheduleSync] Year ${year}: removed ${count} stale packages`);
        }

        totalSynced += rows.length;
        console.log(`[ScheduleSync] Year ${year}: ${rows.length} packages synced`);
      }
    } catch (err) {
      console.error(`[ScheduleSync] Year ${year} failed:`, err.message);
    }
  }

  // Reap rows for decommissioned year_codes (years no longer in SCHEDULE_YEAR_CODES).
  // This runs OUTSIDE the per-year loop and is independent of any fetch succeeding, so a
  // year that drops off the upstream API (e.g. a past hijri year now returning 522/empty)
  // still gets purged instead of lingering forever with frozen prices. The per-year
  // cleanup inside the loop only runs on a successful upsert and so could never reap a
  // year whose fetch failed — that gap is exactly how the stale 1447 rows survived.
  try {
    const activeList = `(${SCHEDULE_YEAR_CODES.join(',')})`;
    const { data: orphanRows } = await supabase
      .from('umroh_schedules')
      .select('jadwal_id, year_code, brosur_cdn, brosur_thumb_cdn, itinerary_cdn')
      .not('year_code', 'in', activeList);
    if (orphanRows?.length) {
      if (getBunnyEnabled()) {
        for (const stale of orphanRows) {
          try {
            if (stale.brosur_cdn) await bunnyDelete(stale.brosur_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, ''));
            if (stale.brosur_thumb_cdn) await bunnyDelete(stale.brosur_thumb_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, ''));
            if (stale.itinerary_cdn) await bunnyDelete(stale.itinerary_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, ''));
          } catch (e) { console.error(`[ScheduleSync] Bunny cleanup orphan ${stale.jadwal_id}: ${e.message}`); }
        }
      }
      const { error: orphanDelErr, count: orphanCount } = await supabase
        .from('umroh_schedules')
        .delete({ count: 'exact' })
        .not('year_code', 'in', activeList);
      if (orphanDelErr) console.error('[ScheduleSync] Orphan-year cleanup error:', orphanDelErr.message);
      else if (orphanCount > 0) console.log(`[ScheduleSync] Reaped ${orphanCount} rows for decommissioned year_codes (not in ${activeList})`);
    }
  } catch (e) {
    console.error('[ScheduleSync] Orphan-year cleanup failed:', e.message);
  }

  const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
  console.log(`[ScheduleSync] Complete: ${totalSynced} packages in ${elapsed}s`);
}

// ──────────────────────────────────────────────
// Bunny CDN: Sync brosur & itinerary files to Bunny Storage
// ──────────────────────────────────────────────
const BUNNY_STORAGE_API_KEY = process.env.BUNNY_STORAGE_API_KEY;
const BUNNY_STORAGE_ZONE = process.env.BUNNY_STORAGE_ZONE;
const BUNNY_STORAGE_HOSTNAME = process.env.BUNNY_STORAGE_HOSTNAME || 'storage.bunnycdn.com';
const BUNNY_CDN_HOSTNAME = process.env.BUNNY_CDN_HOSTNAME;

function getBunnyEnabled() {
  return !!(BUNNY_STORAGE_API_KEY && BUNNY_STORAGE_ZONE && BUNNY_CDN_HOSTNAME);
}

async function bunnyFileExists(path) {
  try {
    const res = await fetch(`https://${BUNNY_CDN_HOSTNAME}/${path}`, {
      method: 'HEAD',
      signal: AbortSignal.timeout(5000),
    });
    return res.ok;
  } catch {
    return false;
  }
}

// ── Thumbnail brosur ──────────────────────────────────────────────
// Brosur resmi AWAPI adalah file resolusi CETAK (terukur 1 Agt 2026: 64 brosur
// = 71,8 MB, rata-rata 1,1 MB, terbesar 4500x6000 px / 8,1 MB). Grid "Brosur
// Paket" menampilkannya sebagai thumbnail ~180px, jadi >99% byte-nya terbuang:
// di Fast 3G, 4 thumbnail pertama butuh ~10 detik. Bunny Optimizer tidak aktif
// (?width= diabaikan), jadi turunannya kita buat sendiri saat sync.
const BROSUR_THUMB_FOLDER = 'brosur-thumb';
const BROSUR_THUMB_WIDTH = 400;
const BROSUR_THUMB_QUALITY = 78;

// Nama objek di-fingerprint dengan sha256 SUMBER, sama seperti file utama, jadi
// URL thumb otomatis berubah saat brosurnya diganti — tidak perlu kolom sha
// terpisah dan edge cache lama tidak mungkin terpakai ulang.
async function clearBrosurThumb(pkg) {
  if (!pkg.brosur_thumb_cdn) return 'skip';
  const { error } = await supabase
    .from('umroh_schedules')
    .update({ brosur_thumb_cdn: null })
    .eq('jadwal_id', pkg.jadwal_id)
    .eq('year_code', pkg.year_code);
  if (error) throw new Error(`stale thumb clear failed: ${error.message}`);
  return 'cleared';
}

async function ensureBrosurThumb(pkg, file) {
  const path = buildContentAddressedCdnPath(BROSUR_THUMB_FOLDER, pkg.jadwal_id, file.sha256, '.webp');
  const cdnUrl = `https://${BUNNY_CDN_HOSTNAME}/${path}`;
  if (pkg.brosur_thumb_cdn === cdnUrl) return 'skip';

  // JANGAN percaya Content-Type: sumber AWAPI menyajikan brosur sebagai
  // application/octet-stream (83 dari 84 file per 1 Agt 2026), sehingga guard
  // berbasis MIME menolak hampir semua brosur yang sah. Biarkan sharp membaca
  // header file — kalau gagal berarti memang bukan raster (mis. PDF) dan itu
  // dilewati diam-diam, bukan dihitung sebagai error.
  let meta;
  try {
    meta = await sharp(file.buffer).metadata();
  } catch {
    return clearBrosurThumb(pkg);
  }
  if (!meta?.width) return clearBrosurThumb(pkg);

  try {
    const thumb = await sharp(file.buffer)
      .rotate()                                                   // hormati EXIF orientation
      .resize({ width: BROSUR_THUMB_WIDTH, withoutEnlargement: true })
      .webp({ quality: BROSUR_THUMB_QUALITY })
      .toBuffer();

    await bunnyUpload(path, thumb, 'image/webp');
    const { error } = await supabase
      .from('umroh_schedules')
      .update({ brosur_thumb_cdn: cdnUrl })
      .eq('jadwal_id', pkg.jadwal_id)
      .eq('year_code', pkg.year_code);
    if (error) throw new Error(`thumb metadata update failed: ${error.message}`);

    console.log(`[BunnySync] Thumb ${pkg.jadwal_id}: ${(file.bytes / 1048576).toFixed(2)} MB → ${(thumb.length / 1024).toFixed(0)} KB`);
    return 'uploaded';
  } catch (err) {
    // A failed replacement must not leave the previous brochure's thumbnail
    // visible.  The full, fingerprint-checked brochure is the safe fallback.
    try {
      await clearBrosurThumb(pkg);
    } catch (clearErr) {
      console.error(`[BunnySync] Thumb ${pkg.jadwal_id}: ${clearErr.message}`);
    }
    throw err;
  }
}

async function bunnyUpload(path, buffer, contentType) {
  const res = await fetch(
    `https://${BUNNY_STORAGE_HOSTNAME}/${BUNNY_STORAGE_ZONE}/${path}`,
    {
      method: 'PUT',
      headers: {
        'AccessKey': BUNNY_STORAGE_API_KEY,
        'Content-Type': contentType || 'application/octet-stream',
      },
      body: buffer,
      signal: AbortSignal.timeout(120000),
    }
  );
  if (!res.ok) throw new Error(`Bunny upload failed: ${res.status} ${res.statusText}`);
}

async function bunnyDelete(path) {
  const res = await fetch(
    `https://${BUNNY_STORAGE_HOSTNAME}/${BUNNY_STORAGE_ZONE}/${path}`,
    {
      method: 'DELETE',
      headers: { 'AccessKey': BUNNY_STORAGE_API_KEY },
      signal: AbortSignal.timeout(10000),
    }
  );
  if (!res.ok && res.status !== 404) throw new Error(`Bunny delete failed: ${res.status}`);
}

async function downloadFile(url) {
  const candidates = buildSourceDownloadCandidates(url);
  let res = null;
  let lastError = null;

  for (const candidate of candidates) {
    try {
      const response = await fetch(candidate, {
        headers: {
          'User-Agent': 'Mozilla/5.0',
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache',
        },
        cache: 'no-store',
        signal: AbortSignal.timeout(120000),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      res = response;
      break;
    } catch (err) {
      lastError = err;
    }
  }

  if (!res) {
    throw new Error(`Download failed: ${lastError?.message || 'no usable source URL'}`);
  }
  const contentType = res.headers.get('content-type') || 'application/octet-stream';
  // Extract extension from Content-Disposition or Content-Type
  const disposition = res.headers.get('content-disposition') || '';
  let ext = '';
  const fnMatch = disposition.match(/filename[^;=\n]*=["']?([^"';\n]+)/i);
  if (fnMatch) {
    const dotIdx = fnMatch[1].lastIndexOf('.');
    if (dotIdx > 0) ext = fnMatch[1].substring(dotIdx);
  }
  if (!ext) {
    if (contentType.includes('pdf')) ext = '.pdf';
    else if (contentType.includes('webp')) ext = '.webp';
    else if (contentType.includes('jpeg') || contentType.includes('jpg')) ext = '.jpg';
    else if (contentType.includes('png')) ext = '.png';
  }
  const buffer = Buffer.from(await res.arrayBuffer());
  const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
  return { buffer, contentType, ext, bytes: buffer.length, sha256 };
}

// ──────────────────────────────────────────────
// Top Partner public cache
// ──────────────────────────────────────────────
const TOP_PARTNER_DB_READ_TTL_MS = 10 * 60 * 1000;
const TOP_PARTNER_REFRESH_RETRY_MS = 5 * 60 * 1000;
let topPartnerMemory = null; // { partners: [...], syncedAt: string }
let topPartnerDbReadAt = 0;
let topPartnerFetchInFlight = null;
let topPartnerFetchAttemptedAt = 0;

async function topPartnerBunnyFileExists(path) {
  try {
    const res = await fetch(`https://${BUNNY_CDN_HOSTNAME}/${path}`, {
      method: 'HEAD',
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) return false;
    const bytes = Number(res.headers.get('content-length') || '0');
    return !bytes || bytes > 512;
  } catch {
    return false;
  }
}

async function loadTopPartnersFromSupabase() {
  try {
    const { data, error } = await supabase
      .from('top_partners_cache')
      .select('data, synced_at')
      .eq('id', 'partners')
      .maybeSingle();
    if (error || !data) return false;
    topPartnerMemory = { partners: Array.isArray(data.data) ? data.data : [], syncedAt: data.synced_at };
    return topPartnerMemory.partners.length > 0;
  } catch (err) {
    console.error('[TopPartner] Supabase load error:', err.message);
    return false;
  }
}

function topPartnerBunnyDeps() {
  return {
    enabled: getBunnyEnabled(),
    cdnHostname: BUNNY_CDN_HOSTNAME,
    fileExists: topPartnerBunnyFileExists,
    downloadFile: url => downloadFile(normalizeBunnyDownloadUrl(url)),
    uploadFile: bunnyUpload,
    logger: console,
  };
}

async function fetchTopPartnersOnce() {
  const { partners: sanitized, endpoint } = await fetchTopPartnerData({
    fetchImpl: fetch,
    headers: {
      'User-Agent': 'Mozilla/5.0 (compatible; AlhijazTopPartner/1.0)',
      'Referer': 'https://alhijazindowisata.com/jadwal/',
      'Accept': 'application/json,text/plain,*/*',
    },
    timeoutMs: 20_000,
  });

  const partners = await mirrorTopPartnerPhotos(sanitized, topPartnerBunnyDeps());

  const syncedAt = new Date().toISOString();
  topPartnerMemory = { partners, syncedAt };

  try {
    const { error } = await supabase.from('top_partners_cache').upsert(
      { id: 'partners', data: partners, synced_at: syncedAt },
      { onConflict: 'id' }
    );
    if (error) throw new Error(error.message);
    console.log(`[TopPartner] ${partners.length} partner dari ${new URL(endpoint).host} dipersist ke Supabase`);
  } catch (err) {
    console.error('[TopPartner] Supabase persist error:', err.message);
  }
  return true;
}

function fetchTopPartners() {
  if (!topPartnerFetchInFlight) {
    topPartnerFetchAttemptedAt = Date.now();
    topPartnerFetchInFlight = fetchTopPartnersOnce().finally(() => {
      topPartnerFetchInFlight = null;
    });
  }
  return topPartnerFetchInFlight;
}

if (shouldRunBackgroundJobs()) {
  (async () => {
    try {
      await loadTopPartnersFromSupabase();
      if (!isTopPartnerCacheFresh(topPartnerMemory?.syncedAt)) {
        console.log('[TopPartner] Cache kosong/basi saat startup, fetch sekali...');
        await fetchTopPartners();
      } else {
        console.log(`[TopPartner] Cache masih segar (synced ${topPartnerMemory.syncedAt}), skip fetch startup`);
      }
    } catch (err) {
      console.error('[TopPartner] Startup init error:', err.message);
    }
  })();

  cron.schedule('0 4 * * *', async () => {
    try {
      await fetchTopPartners();
    } catch (err) {
      console.error('[TopPartner] Cron fetch error:', err.message);
    }
  }, { timezone: 'Asia/Jakarta' });
}

if (process.env.NODE_ENV !== 'production') {
  app.post('/api/dev/trigger-top-partner-refresh', authMiddleware, async (req, res) => {
    try {
      const ok = await fetchTopPartners();
      res.json({
        success: ok,
        syncedAt: topPartnerMemory?.syncedAt ?? null,
        partners: topPartnerMemory?.partners?.length ?? 0,
      });
    } catch (err) {
      console.error('[TopPartner/dev-trigger] error:', err.message);
      res.status(500).json({ success: false, error: err.message });
    }
  });
}

app.get('/api/top-partner', async (req, res) => {
  try {
    const now = Date.now();
    if (!topPartnerMemory || now - topPartnerDbReadAt >= TOP_PARTNER_DB_READ_TTL_MS) {
      await loadTopPartnersFromSupabase();
      topPartnerDbReadAt = now;
    }

    // Endpoint publik ikut memulihkan cache basi. Ini penting bila cron pernah
    // gagal (misalnya upstream diblokir WAF) atau background jobs dimatikan.
    // Cache lama tetap dilayani selama refresh agar landing page tidak blank.
    let stale = !isTopPartnerCacheFresh(topPartnerMemory?.syncedAt, now);
    const retryAllowed = now - topPartnerFetchAttemptedAt >= TOP_PARTNER_REFRESH_RETRY_MS;
    if (!topPartnerMemory?.partners?.length && (topPartnerFetchInFlight || retryAllowed)) {
      try {
        await fetchTopPartners();
      } catch (refreshErr) {
        console.error('[TopPartner] On-demand refresh error:', refreshErr.message);
      }
      stale = !isTopPartnerCacheFresh(topPartnerMemory?.syncedAt);
    } else if (stale && !topPartnerFetchInFlight && retryAllowed) {
      void fetchTopPartners().catch((refreshErr) => {
        console.error('[TopPartner] Background refresh error:', refreshErr.message);
      });
    }

    if (!topPartnerMemory?.partners?.length) {
      return res.status(503).json({ error: 'Data partner belum tersedia' });
    }
    res.set('Cache-Control', 'public, max-age=60, stale-while-revalidate=3600');
    res.json({
      success: true,
      partners: topPartnerMemory.partners,
      syncedAt: topPartnerMemory.syncedAt,
      ...(stale ? { stale: true } : {}),
    });
  } catch (err) {
    console.error('[TopPartner] read error:', err.message);
    if (topPartnerMemory?.partners?.length) {
      return res.json({ success: true, partners: topPartnerMemory.partners, stale: true, syncedAt: topPartnerMemory.syncedAt });
    }
    res.status(500).json({ error: 'Gagal mengambil data partner' });
  }
});

async function syncFilesToBunny({ kinds = ['brosur', 'itinerary'] } = {}) {
  if (!getBunnyEnabled()) {
    console.log('[BunnySync] Skipped — Bunny credentials not configured');
    return;
  }

  const requestedKinds = new Set(kinds);
  console.log(`[BunnySync] Starting (${[...requestedKinds].join(', ') || 'no file kinds'})...`);
  const startTime = Date.now();
  let uploaded = 0, metadataUpdated = 0, skipped = 0, errors = 0;
  let thumbsUploaded = 0, thumbsCleared = 0, thumbErrors = 0;
  let uploadsSincePause = 0;

  const syncBrochureThumb = async (pkg, file) => {
    try {
      const result = await ensureBrosurThumb(pkg, file);
      if (result === 'uploaded') thumbsUploaded++;
      if (result === 'cleared') thumbsCleared++;
    } catch (thumbErr) {
      // Thumb failure never blocks the canonical brochure.  Readers fall back
      // to the full fingerprint-checked asset while this is retried.
      console.error(`[BunnySync] Thumb ${pkg.jadwal_id}: ${thumbErr.message}`);
      thumbErrors++;
    }
  };

  const { data: packages, error } = await supabase
    .from('umroh_schedules')
    .select([
      'jadwal_id',
      'year_code',
      'brosur',
      'itinerary',
      'brosur_cdn',
      'brosur_thumb_cdn',
      'itinerary_cdn',
      'brosur_source_sha256',
      'brosur_source_bytes',
      'brosur_source_content_type',
      'brosur_cdn_synced_at',
      'itinerary_source_sha256',
      'itinerary_source_bytes',
      'itinerary_source_content_type',
      'itinerary_cdn_synced_at',
    ].join(', '));

  if (error || !packages?.length) {
    if (error) console.error('[BunnySync] Package fetch failed:', error.message);
    else console.log('[BunnySync] No packages to sync');
    return;
  }

  const fileConfigs = [
    { kind: 'brosur', folder: 'brosur', sourceField: 'brosur', cdnField: 'brosur_cdn', fallbackExt: '.webp', label: 'Brosur' },
    { kind: 'itinerary', folder: 'itinerary', sourceField: 'itinerary', cdnField: 'itinerary_cdn', fallbackExt: '.pdf', label: 'Itinerary' },
  ].filter(config => requestedKinds.has(config.kind));

  for (const pkg of packages) {
    for (const config of fileConfigs) {
      let currentFileMeta = null;
      let currentDecision = null;
      try {
        if (!pkg[config.sourceField]) {
          skipped++;
          continue;
        }

        const file = await downloadFile(pkg[config.sourceField]);
        const fileMeta = {
          sha256: file.sha256,
          bytes: file.bytes,
          contentType: file.contentType,
        };
        currentFileMeta = fileMeta;

        const decision = getCdnFileDecision(pkg, config.kind, fileMeta);
        currentDecision = decision;
        if (decision.action === 'skip') {
          // Unchanged brochures still need thumbnail backfill/repair.
          if (config.kind === 'brosur') await syncBrochureThumb(pkg, file);
          skipped++;
          continue;
        }
        if (decision.action === 'verify_cdn') {
          const cdnFile = await downloadFile(pkg[config.cdnField]);
          if (cdnFile.sha256 === fileMeta.sha256 && cdnFile.bytes === fileMeta.bytes) {
            const update = buildCdnMetadataUpdate(config.kind, pkg[config.cdnField], fileMeta);
            const { error: updateError } = await supabase
              .from('umroh_schedules')
              .update(update)
              .eq('jadwal_id', pkg.jadwal_id)
              .eq('year_code', pkg.year_code);
            if (updateError) throw new Error(`metadata update failed: ${updateError.message}`);
            if (config.kind === 'brosur') {
              await syncBrochureThumb({ ...pkg, ...update }, file);
            }
            metadataUpdated++;
            console.log(`[BunnySync] ${config.label} ${pkg.jadwal_id}: metadata updated (cdn unchanged)`);
            continue;
          }
        }

        // Bunny can be configured to ignore query strings in its cache key. A
        // fingerprint in the object name guarantees changed files cannot reuse
        // stale edge content even when `?v=` is ignored by the pull zone.
        const path = buildContentAddressedCdnPath(
          config.folder,
          pkg.jadwal_id,
          file.sha256,
          file.ext || config.fallbackExt,
        );
        await bunnyUpload(path, file.buffer, file.contentType);
        const cdnUrl = `https://${BUNNY_CDN_HOSTNAME}/${path}`;
        const update = {
          ...buildCdnMetadataUpdate(config.kind, cdnUrl, fileMeta),
          // Main brochure and source fingerprint become authoritative in one
          // write.  The old thumb is hidden until its matching replacement is
          // ready, so the grid and modal cannot disagree across versions.
          ...(config.kind === 'brosur' ? { brosur_thumb_cdn: null } : {}),
        };
        const { error: updateError } = await supabase
          .from('umroh_schedules')
          .update(update)
          .eq('jadwal_id', pkg.jadwal_id)
          .eq('year_code', pkg.year_code);
        if (updateError) throw new Error(`metadata update failed: ${updateError.message}`);
        if (config.kind === 'brosur') {
          await syncBrochureThumb({ ...pkg, ...update }, file);
        }
        uploaded++;
        uploadsSincePause++;
        console.log(`[BunnySync] ${config.label} ${pkg.jadwal_id}: uploaded (${decision.reason})`);
      } catch (err) {
        if (config.kind === 'brosur' && pkg.brosur_cdn && currentFileMeta && currentDecision?.action !== 'skip') {
          // We have proved the source bytes need verification/replacement.  If
          // that process fails, retain the new fingerprint for diagnostics but
          // stop advertising the known-old main image and thumbnail.
          const invalidation = {
            ...buildCdnInvalidationUpdate('brosur', currentFileMeta),
            brosur_thumb_cdn: null,
          };
          const { error: invalidationError } = await supabase
            .from('umroh_schedules')
            .update(invalidation)
            .eq('jadwal_id', pkg.jadwal_id)
            .eq('year_code', pkg.year_code);
          if (invalidationError) {
            console.error(`[BunnySync] Brosur ${pkg.jadwal_id}: stale cache invalidation failed: ${invalidationError.message}`);
          }
        }
        console.error(`[BunnySync] ${config.label} ${pkg.jadwal_id}: ${err.message}`);
        errors++;
      }
    }

    // Small delay to avoid hammering origin server
    if (uploadsSincePause >= 5) {
      uploadsSincePause = 0;
      await new Promise(r => setTimeout(r, 1000));
    }
  }

  const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
  console.log(`[BunnySync] Complete: ${uploaded} uploaded, ${thumbsUploaded} thumbs, ${thumbsCleared} stale thumbs cleared, ${metadataUpdated} metadata updated, ${skipped} skipped, ${errors} errors, ${thumbErrors} thumb errors in ${elapsed}s`);
}

// Schedule and daily timers may land on the same minute. Serialize file scans so
// they never race uploads/metadata updates for the same Bunny object.
let bunnySyncQueue = Promise.resolve();
function queueFilesToBunny(options) {
  const run = bunnySyncQueue.then(() => syncFilesToBunny(options));
  bunnySyncQueue = run.catch(() => {});
  return run;
}

// ──────────────────────────────────────────────
// Bunny CDN: Cleanup expired & stale files
// ──────────────────────────────────────────────
async function cleanupExpiredPackages() {
  if (!getBunnyEnabled()) return;

  console.log('[BunnyCleanup] Checking for expired packages...');
  const sixMonthsAgo = new Date();
  sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
  const cutoffDate = sixMonthsAgo.toISOString().split('T')[0];

  const { data: expired, error } = await supabase
    .from('umroh_schedules')
    .select('jadwal_id, year_code, brosur_cdn, brosur_thumb_cdn, itinerary_cdn')
    .lt('berangkat_tgl', cutoffDate);

  if (error || !expired?.length) {
    if (!error) console.log('[BunnyCleanup] No expired packages');
    return;
  }

  let deleted = 0;
  for (const pkg of expired) {
    try {
      // Delete files from Bunny
      if (pkg.brosur_cdn) {
        const path = pkg.brosur_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, '');
        await bunnyDelete(path);
      }
      if (pkg.brosur_thumb_cdn) {
        const path = pkg.brosur_thumb_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, '');
        await bunnyDelete(path);
      }
      if (pkg.itinerary_cdn) {
        const path = pkg.itinerary_cdn.replace(`https://${BUNNY_CDN_HOSTNAME}/`, '');
        await bunnyDelete(path);
      }

      // Delete row from Supabase
      await supabase
        .from('umroh_schedules')
        .delete()
        .eq('jadwal_id', pkg.jadwal_id)
        .eq('year_code', pkg.year_code);

      deleted++;
    } catch (err) {
      console.error(`[BunnyCleanup] ${pkg.jadwal_id}: ${err.message}`);
    }
  }

  console.log(`[BunnyCleanup] Removed ${deleted} expired packages (> 6 months past departure)`);
}

// ──────────────────────────────────────────────
// API: Read schedules from Supabase (with external API fallback)
// ──────────────────────────────────────────────
// Sekali per jadwal per proses — endpoint ini dipanggil tiap klien (TTL 30 mnt)
// dan cache basi baru sembuh di siklus ItinerarySync berikutnya.
const warnedContradictoryJourneyOrder = new Set();
const warnedSuspectRouteJourneyOrder = new Set();
const warnedForeignItineraryContent = new Set();

app.get('/api/schedules/:yearCode', async (req, res) => {
  const yearCode = req.params.yearCode;

  if (!/^\d{4}$/.test(yearCode)) {
    return res.status(400).json({ status: 'error', error: 'Invalid year code' });
  }

  // Defense in depth: only serve active hijri years. Decommissioned years (e.g. a past
  // 1447) may still have orphan rows in flight before the sync reaper removes them; never
  // hand their frozen prices to a caller. The dashboard only ever requests active years.
  if (!SCHEDULE_YEAR_CODES.includes(yearCode)) {
    return res.status(404).json({ status: 'error', error: 'Year not active' });
  }

  let cachedRows = [];
  let cachedError = null;
  try {
    const { data, error } = await supabase
      .from('umroh_schedules')
      .select('*')
      .eq('year_code', yearCode)
      .order('berangkat_tgl', { ascending: true });

    if (error) throw error;
    cachedRows = data || [];
  } catch (err) {
    cachedError = err;
    console.error(`[Schedules] Supabase error for ${yearCode}: ${err.message}`);
  }

  if (cachedError) {
    return res.status(500).json({ status: 'error', error: 'Failed to read schedule data' });
  }

  if (cachedRows.length === 0) {
    return res.status(500).json({ status: 'error', error: 'No schedule data available' });
  }

  try {
    const scheduleRows = buildScheduleRows(cachedRows, null, yearCode);

    let journeyOrderById = new Map();
    try {
      const jadwalIds = scheduleRows.map(row => row.jadwal_id).filter(Boolean);
      if (jadwalIds.length) {
        const { data: itineraryRows, error: itineraryError } = await supabase
          .from('itineraries')
          .select('jadwal_id, content, source_sha256')
          .in('jadwal_id', jadwalIds);

        if (itineraryError) {
          console.warn('[Schedules] Itinerary order lookup failed:', itineraryError.message);
        } else {
          const scheduleById = new Map(scheduleRows.map(row => [row.jadwal_id, row]));
          journeyOrderById = new Map(
            (itineraryRows || [])
              .filter(row => canServeItineraryCache(row, scheduleById.get(row.jadwal_id)))
              .map(row => {
                const order = inferJourneyOrderFromItinerary(row.content);
                if (!Array.isArray(order) || order.length < 2) return null;
                const schedule = scheduleById.get(row.jadwal_id);
                // Dokumen bertanggal keberangkatan lain tidak pernah layak
                // dipakai, bahkan saat rutenya tidak bertentangan (JBU1528).
                if (itineraryBelongsToOtherSchedule(row.content, schedule?.berangkat_tgl)) {
                  if (!warnedForeignItineraryContent.has(row.jadwal_id)) {
                    warnedForeignItineraryContent.add(row.jadwal_id);
                    console.warn(`[Schedules] Itinerary ${row.jadwal_id} bertanggal di luar keberangkatan ${schedule?.berangkat_tgl} — dokumen milik jadwal lain, urutan diabaikan`);
                  }
                  return null;
                }
                if (shouldSuppressJourneyOrder({
                  order,
                  berangkatRute: schedule?.berangkat_rute,
                  content: row.content,
                  berangkatTgl: schedule?.berangkat_tgl,
                })) {
                  if (!warnedContradictoryJourneyOrder.has(row.jadwal_id)) {
                    warnedContradictoryJourneyOrder.add(row.jadwal_id);
                    console.warn(`[Schedules] Itinerary order ${row.jadwal_id} bertentangan dengan rute (${schedule?.berangkat_rute}) — konten tak terbukti milik jadwal ini, pakai fallback rute`);
                  }
                  return null;
                }
                if (saudiOrderContradictsRoute(order, schedule?.berangkat_rute)
                  && !warnedSuspectRouteJourneyOrder.has(row.jadwal_id)) {
                  warnedSuspectRouteJourneyOrder.add(row.jadwal_id);
                  console.warn(`[Schedules] Rute ${row.jadwal_id} (${schedule?.berangkat_rute}) bertentangan dengan itinerary yang bertanggal cocok — curigai salah entri rute upstream, pakai urutan itinerary`);
                }
                return [row.jadwal_id, order];
              })
              .filter(Boolean)
          );
        }
      }
    } catch (journeyErr) {
      console.warn('[Schedules] Itinerary order inference failed:', journeyErr.message);
    }

    const aaData = serializeScheduleRows(scheduleRows, journeyOrderById);

    res.json({
      status: 'ok',
      iTotalDisplayRecords: aaData.length,
      aaData,
    });
  } catch (err) {
    console.error(`[Schedules] Response build error for ${yearCode}: ${err.message}`);
    res.status(500).json({
      status: 'error',
      error: 'Failed to build schedule response from cached data',
    });
  }
});

// Build version marker = entry chunk hash of the deployed bundle. The client polls
// this (it's NetworkOnly in the SW, so always fresh) to detect a new deploy and
// force-refresh even when the SW serves a stale precached shell. MUST be before the
// /api/{*path} proxy below.
app.get('/api/version', (req, res) => {
  let entry = '';
  try {
    const m = getIndexHtml().match(/assets\/(index-[A-Za-z0-9]+\.js)/);
    entry = m ? m[1] : '';
  } catch { /* ignore */ }
  res.set('Cache-Control', 'no-store').json({ entry });
});

// ──────────────────────────────────────────────
// API: Proxy to jadwal.alhijaz.co
// ──────────────────────────────────────────────
app.all('/api/{*path}', async (req, res) => {
  const path = req.path.replace(/^\/api\//, ''); // everything after /api/
  const targetUrl = `https://jadwal.alhijaz.co/jadwal/${path}`;

  try {
    const response = await fetch(targetUrl, {
      method: req.method,
      headers: { 'Accept': 'application/json', 'Content-Type': 'application/json' },
      ...(req.method === 'POST' ? { body: JSON.stringify(req.body) } : {}),
    });

    const data = await response.text();
    res.set({
      'Content-Type': 'application/json',
      'Access-Control-Allow-Origin': '*',
      'Cache-Control': 'public, max-age=60',
    }).status(response.status).send(data);
  } catch (error) {
    res.status(500).json({ error: 'Proxy error', message: error.message });
  }
});

// ──────────────────────────────────────────────
// Proxy: itinerary & brosur files (with timeout + retry)
// ──────────────────────────────────────────────
// 25s default: origin alhijaz men-generate PDF on-the-fly & sering lambat;
// Cloudflare-nya menyerah dgn 522 di ~19.5s. Timeout di atas itu memberi
// regen lambat-tapi-sukses kesempatan selesai, dan membuat kita menerima
// status upstream asli alih-alih meng-abort jadi 502 palsu.
async function fetchWithTimeout(url, timeoutMs = 25000, options = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { ...options, signal: controller.signal });
    clearTimeout(timer);
    return response;
  } catch (err) {
    clearTimeout(timer);
    throw err;
  }
}

app.get(['/itinerary/{*path}', '/brosur/{*path}'], async (req, res) => {
  const targetUrl = new URL(req.originalUrl, 'https://jadwal.alhijaz.co').toString();
  const candidates = buildSourceDownloadCandidates(targetUrl);
  let lastError = null;

  // Direct origin first, public HTTPS as fallback — the same source ordering
  // used by the fingerprint sync.  These stable source paths are never browser
  // cached; immutable CDN objects handle caching after a successful mirror.
  for (const candidate of candidates) {
    try {
      const response = await fetchWithTimeout(candidate, 25000, {
        headers: {
          'User-Agent': 'Mozilla/5.0',
          'Cache-Control': 'no-cache',
          'Pragma': 'no-cache',
        },
        cache: 'no-store',
      });
      if (!response.ok) {
        if (response.status >= 500) {
          lastError = new Error(`${candidate} HTTP ${response.status}`);
          continue;
        }
        return res.sendStatus(response.status);
      }

      const contentType = response.headers.get('content-type') || 'application/octet-stream';
      res.set('Content-Type', contentType);
      res.set('Access-Control-Allow-Origin', '*');
      res.set('Cache-Control', 'no-store');

      const buffer = Buffer.from(await response.arrayBuffer());
      return res.send(buffer);
    } catch (error) {
      lastError = error;
      console.warn(`[Proxy] ${candidate} failed for ${req.path}: ${error.message}`);
    }
  }

  console.error(`[Proxy] All sources failed for ${req.path}:`, lastError?.message || 'no source');
  return res.status(502).json({ error: 'File gagal dimuat', message: 'Server sumber tidak merespon, silakan coba lagi.' });
});

