// ──────────────────────────────────────────────
// Bio Page: /:slug/bio — SSR OG meta injection (React SPA handles body)
// ──────────────────────────────────────────────

function escapeHtmlAttr(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function serializeInlineJson(value) {
  return JSON.stringify(value).replace(/</g, '\\u003c');
}

function buildAgentContextPayload(agent, servedCustomDomain = null) {
  const hasCustomDomain = !!(
    isCustomDomainEnabledForAgent(agent) &&
    agent.custom_domain &&
    agent.custom_domain_status === 'active'
  );
  return {
    slug: agent.slug,
    name: agent.name,
    website: agent.website || null,
    phone: agent.phone || null,
    photo: agent.photo || null,
    email: agent.email || null,
    customDomain: servedCustomDomain || (hasCustomDomain ? agent.custom_domain : null),
    hasCustomDomain,
  };
}

function renderBioPageHtml({ agent, slug, origin, pageUrl, customDomain = null }) {
  const bioConfig = agent.bio_config || {};
  if (bioConfig.enabled === false) return null;

  const title = bioConfig.seo?.title
    || `${agent.name} — Konsultan Umroh & Haji Plus`;
  const description = bioConfig.seo?.description
    || `Halaman resmi ${agent.name}, mitra travel Umroh dan Haji Plus Alhijaz Indowisata.`;
  const canonicalSlug = String(agent.slug || slug || '').toLowerCase();
  const ogImage = bioConfig.seo?.og_image_url || `${origin}/og/${canonicalSlug}.png`;

  let html = getIndexHtml();

  const t = escapeHtmlAttr(title);
  const d = escapeHtmlAttr(description);
  const img = escapeHtmlAttr(ogImage);
  const url = escapeHtmlAttr(pageUrl);
  const agentContextScript = customDomain
    ? `\n    <script>window.__AGENT_CONTEXT__ = ${serializeInlineJson(buildAgentContextPayload(agent, customDomain))};</script>`
    : '';

  html = html.replace(/<title>[^<]*<\/title>/i, `<title>${t}</title>`);
  html = html.replace(
    /<meta\s+name="description"\s+content="[^"]*"\s*\/?>/i,
    `<meta name="description" content="${d}" />`
  );
  // Strip any inherited OG tags so bio's canonical tags win
  html = html.replace(/<meta\s+property="og:[^"]*"\s+content="[^"]*"\s*\/?>\s*/gi, '');
  html = html.replace(/<link\s+rel="canonical"[^>]*>\s*/gi, '');

  const metaTags = `
    <link rel="canonical" href="${url}" />
    <meta property="og:title" content="${t}" />
    <meta property="og:description" content="${d}" />
    <meta property="og:type" content="profile" />
    <meta property="og:url" content="${url}" />
    <meta property="og:site_name" content="Alhijaz Indowisata" />
    <meta property="og:image" content="${img}" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${t}" />
    <meta name="twitter:description" content="${d}" />
    <meta name="twitter:image" content="${img}" />${agentContextScript}
    `;
  return html.replace('</head>', `${metaTags}</head>`);
}

app.get('/bio', async (req, res, next) => {
  if (!req.customDomain || !req.customDomainAgent) return next();
  const agent = req.customDomainAgent;
  const slug = String(agent.slug || '').toLowerCase();
  if (!slug) return next();
  try {
    const origin = `https://${req.customDomain}`;
    const pageUrl = `${origin}/bio`;
    const html = renderBioPageHtml({
      agent,
      slug,
      origin,
      pageUrl,
      customDomain: req.customDomain,
    });
    if (!html) return next(); // explicitly disabled → SPA 404

    res.set({
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'private, no-store, must-revalidate',
    }).send(html);
  } catch (err) {
    console.error('[bio] custom-domain SSR error for', slug, ':', err.message);
    next();
  }
});

app.get('/:slug/bio', async (req, res, next) => {
  const slug = String(req.params.slug || '').toLowerCase();
  try {
    const resolved = await resolveSlug(slug);
    if (!resolved) return next(); // unknown slug → SPA fallback (React 404)
    if (resolved.redirect) {
      return res.redirect(301, `/${resolved.redirect}/bio`);
    }

    const agent = resolved.agent;
    const origin = `${req.protocol}://${req.get('host')}`;
    const canonicalSlug = String(agent.slug || slug).toLowerCase();
    const pageUrl = `${origin}/${canonicalSlug}/bio`;
    const html = renderBioPageHtml({ agent, slug: canonicalSlug, origin, pageUrl });
    if (!html) return next(); // explicitly disabled → SPA 404

    res.set({
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'public, max-age=300',
    }).send(html);
  } catch (err) {
    console.error('[bio] SSR error for', slug, ':', err.message);
    next();
  }
});

// ──────────────────────────────────────────────
// Itinerary share: /:slug/:packageId/itinerary — SSR OG meta (SPA renders body).
// Pola sama dengan bio di atas: resolveSlug + getIndexHtml + replace meta.
// ──────────────────────────────────────────────

async function renderItineraryShareSSR(req, res, { agent, canonicalSlug, packageId, pagePath }) {
    let schedule = null;
    try {
      const { data } = await supabase
        .from('umroh_schedules')
        .select('jadwal_nama, berangkat_tgl, maskapai, itinerary_source_sha256')
        .eq('jadwal_id', packageId)
        .limit(1);
      schedule = data?.[0] || null;
    } catch { /* fallback: pakai packageId */ }

    let days = [];
    try {
      const itinerary = await getItineraryContext(packageId);
      days = itinerary?.days || [];
    } catch { /* itinerary belum tersusun — kartu OG dilewati */ }

    const { title, description } = buildItineraryShareMeta({
      paketName: schedule?.jadwal_nama || '',
      packageId,
      segments: ogSegments(days),
      dayCount: days.length,
      departDate: schedule?.berangkat_tgl || null,
      airline: schedule?.maskapai || null,
      agentName: agent.name,
    });

    const origin = `${req.protocol}://${req.get('host')}`;
    const pageUrl = `${origin}${pagePath}`;
    // Bot menyimpan preview per-URL. Tanpa penanda versi, itinerary yang
    // di-resync tetap tampil dengan kartu lama sampai cache bot kedaluwarsa.
    const sha = String(schedule?.itinerary_source_sha256 || '').slice(0, 8);
    const ogImage = days.length
      ? `${origin}/og/itinerary/${canonicalSlug}/${packageId}.png${sha ? `?v=${sha}` : ''}`
      : null;

    let html = getIndexHtml();
    html = html.replace(/<title>[^<]*<\/title>/i, `<title>${escapeHtmlAttr(title)}</title>`);
    html = html.replace(
      /<meta\s+name="description"\s+content="[^"]*"\s*\/?>/i,
      `<meta name="description" content="${escapeHtmlAttr(description)}" />`
    );
    html = html.replace(
      /<meta\s+property="og:title"\s+content="[^"]*"\s*\/?>/i,
      `<meta property="og:title" content="${escapeHtmlAttr(title)}" />`
    );
    html = html.replace(
      /<meta\s+property="og:description"\s+content="[^"]*"\s*\/?>/i,
      `<meta property="og:description" content="${escapeHtmlAttr(description)}" />`
    );
    html = html.replace(
      /<meta\s+property="og:type"\s+content="[^"]*"\s*\/?>/i,
      '<meta property="og:type" content="article" />'
    );

    // og:title/og:description/og:type ADA di index.html jadi cukup diganti.
    // og:image, canonical, dan twitter:* TIDAK ada di sana — .replace() untuk
    // tag yang tak ada gagal diam-diam dan tagnya tak akan pernah muncul, jadi
    // yang ini harus disisipkan.
    // Di custom domain SPA butuh __AGENT_CONTEXT__ untuk tahu slug tersirat host
    // (rute /:jadwalId/itinerary tanpa slug) — pola sama dengan bio SSR di atas.
    const agentContextScript = req.customDomain
      ? `\n    <script>window.__AGENT_CONTEXT__ = ${serializeInlineJson(buildAgentContextPayload(agent, req.customDomain))};</script>`
      : '';
    const extraTags = `${agentContextScript}
    <link rel="canonical" href="${escapeHtmlAttr(pageUrl)}" />
    <meta property="og:url" content="${escapeHtmlAttr(pageUrl)}" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${escapeHtmlAttr(title)}" />
    <meta name="twitter:description" content="${escapeHtmlAttr(description)}" />${ogImage ? `
    <meta property="og:image" content="${escapeHtmlAttr(ogImage)}" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta property="og:image:type" content="image/png" />
    <meta name="twitter:image" content="${escapeHtmlAttr(ogImage)}" />` : ''}
    `;
    html = html.replace('</head>', `${extraTags}</head>`);

    res.set({
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'public, max-age=300',
    }).send(html);
}

app.get('/:slug/:packageId/itinerary', async (req, res, next) => {
  const slug = String(req.params.slug || '').toLowerCase();
  const packageId = String(req.params.packageId || '').toUpperCase();
  try {
    const resolved = await resolveSlug(slug);
    if (!resolved) return next(); // unknown slug → SPA fallback
    if (resolved.redirect) {
      return res.redirect(301, `/${resolved.redirect}/${packageId}/itinerary`);
    }
    const agent = resolved.agent;
    const canonicalSlug = String(agent.slug || slug).toLowerCase();
    await renderItineraryShareSSR(req, res, {
      agent,
      canonicalSlug,
      packageId,
      pagePath: `/${canonicalSlug}/${packageId}/itinerary`,
    });
  } catch (err) {
    console.error('[itinerary-share] SSR error:', slug, packageId, err.message);
    next(); // fallback ke SPA tanpa OG
  }
});

