// Kartu OG halaman share itinerary. Dirender on-demand seperti kartu lain; bot
// menyimpannya sejam. Slug ikut di path supaya kartunya membawa identitas agent
// yang membagikan, bukan cuma paketnya.
app.get('/og/itinerary/:slug/:packageId.png', async (req, res) => {
  const slug = String(req.params.slug || '').toLowerCase();
  const packageId = String(req.params.packageId || '').toUpperCase();
  if (!/^[a-z0-9-]{1,64}$/.test(slug) || !/^[A-Z0-9-]{3,32}$/.test(packageId)) {
    return res.status(404).type('text/plain').send('not found');
  }
  try {
    const resolved = await resolveSlug(slug);
    if (!resolved || !resolved.agent) return res.status(404).type('text/plain').send('not found');
    const agent = resolved.agent;

    const { data: rows } = await supabase
      .from('umroh_schedules')
      .select('jadwal_nama, berangkat_tgl, maskapai')
      .eq('jadwal_id', packageId)
      .limit(1);
    const schedule = rows?.[0] || null;

    const itinerary = await getItineraryContext(packageId);
    const days = itinerary?.days || [];
    // Tanpa itinerary tersusun, halamannya sendiri menampilkan "belum
    // tersedia" — lebih baik tak ada gambar daripada gambar yang menjanjikan
    // isi yang tidak ada.
    if (!days.length) return res.status(404).type('text/plain').send('not found');

    const agentPhotoBuffer = await loadAgentPhotoBuffer(agent.photo, agent.slug);
    const png = await generateItineraryOgPng({
      paketName: schedule?.jadwal_nama || packageId,
      departDate: schedule?.berangkat_tgl || null,
      airline: schedule?.maskapai || null,
      dayCount: days.length,
      segments: ogSegments(days),
      agentName: agent.name,
      agentPhotoBuffer,
    });

    return res.set({
      'Content-Type': 'image/png',
      'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
    }).send(png);
  } catch (err) {
    console.error('[og/itinerary] generation failed:', slug, packageId, err.message);
    return res.status(500).type('text/plain').send('og generation failed');
  }
});

// Serve static assets from dist/ first, then fallback to public/
// This ensures uploaded files (e.g. agent photos in public/agents/)
// are always accessible, even if they were added after the last build.
app.get('/agents/:file', async (req, res, next) => {
  const match = String(req.params.file || '').match(/^([a-z0-9-]+)\.(jpe?g|png|webp)$/i);
  if (!match) return next();

  const slug = match[1].toLowerCase();
  const ext = match[2].toLowerCase();
  const fallbackContentType = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';

  try {
    const agent = await getAgentBySlug(slug);
    const photoBuffer = await loadAgentPhotoBuffer(agent?.photo, slug);
    if (!photoBuffer) return next();

    res.set({
      'Content-Type': detectImageContentType(photoBuffer, fallbackContentType),
      'Cache-Control': 'public, max-age=3600, stale-while-revalidate=86400',
    });
    return res.send(photoBuffer);
  } catch (err) {
    console.warn(`[agents-photo] failed to serve ${slug}:`, err.message);
    return next();
  }
});
// maxAge+immutable: kebijakan cache milik origin sendiri — tidak bergantung header
// injeksi Cloudflare (custom domain tidak melewatinya). Asset ber-hash di assets/
// aman immutable. TAPI file kontrol PWA (sw.js, manifest, index.html) memakai URL
// TETAP yang isinya berubah tiap deploy — kalau immutable, browser nyangkut di
// service worker lama → layar blank pasca-deploy. Paksa revalidasi untuk file itu.
const forceRevalidate = (res, filePath) => {
  if (
    filePath.endsWith('/sw.js') ||
    filePath.endsWith('/index.html') ||
    filePath.endsWith('/manifest.webmanifest') ||
    filePath.endsWith('/registerSW.js')
  ) {
    res.setHeader('Cache-Control', 'no-cache');
  }
};
app.use(express.static(distPath, { index: false, maxAge: '30d', immutable: true, setHeaders: forceRevalidate }));
app.use(express.static(publicPath, { index: false, maxAge: '30d', immutable: true, setHeaders: forceRevalidate }));

// Berkas statis yang TIDAK ada di disk tidak boleh jatuh ke SPA fallback di bawah.
// `vite build` membersihkan chunk hash lama tiap deploy; kalau request chunk lama
// dijawab HTML-200, respons itu di-cache browser sebagai "JS" selama 30 hari
// (immutable) → dynamic import gagal → halaman blank permanen sampai cache
// dibuang. 404 + no-store membuat klien mencoba lagi begitu deploy selesai.
const STATIC_FILE_RE = /\.(?:js|mjs|css|map|png|jpe?g|gif|ico|svg|woff2?|ttf|eot|otf|webp|avif|json|webmanifest|txt|xml|mp4|webm|pdf)$/i;
app.use((req, res, next) => {
  if ((req.method === 'GET' || req.method === 'HEAD') &&
      (req.path.startsWith('/assets/') || STATIC_FILE_RE.test(req.path))) {
    res.set('Cache-Control', 'no-store');
    return res.status(404).type('text/plain').send('Not found');
  }
  next();
});

function injectTopPartnerMeta(html, origin) {
  const title = escapeHtmlAttr(TOP_PARTNER_META_TITLE);
  const description = escapeHtmlAttr(TOP_PARTNER_META_DESCRIPTION);
  const pageUrl = escapeHtmlAttr(`${origin}/top-partner`);
  const ogImageUrl = escapeHtmlAttr(`${origin}${TOP_PARTNER_OG_IMAGE_PATH}`);

  html = html.replace(/<title>[^<]*<\/title>/i, `<title>${title}</title>`);
  html = html.replace(
    /<meta\s+name="description"\s+content="[^"]*"\s*\/?>/i,
    `<meta name="description" content="${description}" />`
  );
  html = html.replace(/<meta\s+property="og:[^"]*"\s+content="[^"]*"\s*\/?>\s*/gi, '');
  html = html.replace(/<meta\s+name="twitter:[^"]*"\s+content="[^"]*"\s*\/?>\s*/gi, '');
  html = html.replace(/<link\s+rel="canonical"[^>]*>\s*/gi, '');

  const metaTags = `
    <link rel="canonical" href="${pageUrl}" />
    <meta property="og:title" content="${title}" />
    <meta property="og:description" content="${description}" />
    <meta property="og:type" content="website" />
    <meta property="og:url" content="${pageUrl}" />
    <meta property="og:site_name" content="Alhijaz Indowisata" />
    <meta property="og:image" content="${ogImageUrl}" />
    <meta property="og:image:width" content="1200" />
    <meta property="og:image:height" content="630" />
    <meta property="og:image:type" content="image/png" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content="${title}" />
    <meta name="twitter:description" content="${description}" />
    <meta name="twitter:image" content="${ogImageUrl}" />
  `;

  return html.replace('</head>', `${metaTags}\n</head>`);
}

app.get('/top-partner', (req, res) => {
  const origin = `${req.protocol}://${req.get('host')}`;
  const html = injectTopPartnerMeta(getIndexHtml(), origin);
  res.set('Content-Type', 'text/html');
  res.set('Cache-Control', 'no-cache');
  res.send(html);
});

